export const analyzeCells = "\"\"\"Static analysis of notebook cells against the live kernel namespace.\n\nFor each cell: the names it defines and uses, the data frame columns it\ntouches, its decisions, and the sections of the user's own files it depends\non. A decision is a value that changes the result:\n\n- ``defaulted``: a parameter of the user's own function left at its default,\n  such as ``min_days=MIN_DAYS`` in ``prep.drop_sparse``;\n- ``library_default``: a library parameter from a short list of defaults known\n  to change results, such as ``reml=True`` in statsmodels' MixedLM.fit;\n- ``literal``: a value written in the cell itself, such as ``n_boot=1000``.\n\nA library default also names its ``library`` and that library's ``version``\nwhen it is known, for the popover that says \"default in pandas 3.0.6\". A\nkeyword argument that keeps the books, such as ``drop=True`` of\n``reset_index``, makes no ``literal`` decision (``bookkeeping`` below), and\nneither does a call that picks the rows that the cell only shows, such as the\n``head()`` that ends it (``showing_functions``).\n\nEach decision of a call is keyed by that call: where the cell names the\nfunction, its line and column. Calls that leave the same parameter at the\nsame value share one decision, which lists them in ``calls``, so a cell\nthat merges twice with the default ``how='inner'`` has one decision with two\ncalls. Each call also names, in one word, the frame that it joins or reads\n(``target``), such as ``weather`` for ``.merge(weather, on=\"date\")`` and\n``homes`` for ``pd.read_csv(\"homes.csv\")``. The line counts from 1 and the\ncolumn counts UTF-8 bytes from the start of the line, as ``ast`` does, and\n``codegen.call_site`` on the server finds the call by the same place.\n\nA formula is whole: one that the cell builds, as\n``'y ~ x + ' + ' + '.join(covariates)``, is read with the names it joins,\nor with what the join adds in words, and a piece such as \"y ~ x +\" is no\nformula (``formula_texts``).\n\nWith ``signatures`` in the arguments (the view's setting \"Find more defaults\nwith AI\", design iteration 1.53), a cell also lists the library functions\nthat it calls, under ``signatures``: each function's module, its library and\nthe library's version, each parameter of its signature that has a default,\nwith the default as code, and each call with the parameters that it leaves at\ntheir defaults. A default that holds data, such as a frame, says what it is\n(``<DataFrame 3 × 2>``, ``\"data\": true``), and one that looks like a key is\nleft out. A marker that no code can write, such as pandas' ``<no_default>``,\ngives way to the default that the function's documentation gives, ``','``\nfor the separator of ``read_csv``, and without one its parameter is left\nout. Builtins, the notebook's own functions and those of the analyst's\nmodules are left out too, a cell lists at most ``max_signatures`` functions,\nand what was read of each function stays on the shell for the kernel's\nsession. The analysis is the same with or without them.\n\nThe frontend bundle holds the text of this file and runs it in the kernel, so\nit must not import the whybook package.\n\"\"\"\n\n\ndef _whybook_analyze_cells(args):\n    import ast\n    import builtins\n    import inspect\n    import os\n    import re\n    import sys\n    import textwrap\n\n    from IPython import get_ipython\n    from IPython.display import display\n\n    shell = get_ipython()\n    ns = shell.user_ns\n    cwd = os.path.realpath(os.getcwd())\n    max_decisions = args.get(\"max_decisions\", 6)\n    read_signatures = bool(args.get(\"signatures\"))\n    max_signatures = args.get(\"max_signatures\", 8)\n    # What was read of each function, by its qualified name, and each\n    # library's version: kept on the shell for the kernel's session, as the\n    # plot hooks keep their state.\n    kept_signatures = getattr(shell, \"_whybook_signatures\", None)\n    if kept_signatures is None:\n        kept_signatures = shell._whybook_signatures = {\"functions\": {}, \"versions\": {}}\n\n    # What a reader's default header does, for the readers below.\n    first_row = \"the first row names the columns: header=None reads it as data\"\n    # Library defaults that change results, keyed by the qualified function name.\n    library_defaults = {\n        \"statsmodels.base.model.Model.from_formula\": {\n            \"missing\": (\"'drop'\", \"rows with a missing value in any formula variable are dropped\"),\n        },\n        \"statsmodels.regression.mixed_linear_model.MixedLM.from_formula\": {\n            \"re_formula\": (\"None\", \"random intercept only, no random slopes\"),\n        },\n        \"statsmodels.regression.mixed_linear_model.MixedLM.fit\": {\n            \"reml\": (\"True\", \"REML fit: likelihoods cannot compare models with different fixed effects\"),\n        },\n        \"pandas.core.frame.DataFrame.merge\": {\n            \"how\": (\"'inner'\", \"rows without a match in both frames are dropped\"),\n        },\n        \"pandas.core.reshape.merge.merge\": {\n            \"how\": (\"'inner'\", \"rows without a match in both frames are dropped\"),\n        },\n        # pandas 3 names pd.merge after its public module.\n        \"pandas.merge\": {\n            \"how\": (\"'inner'\", \"rows without a match in both frames are dropped\"),\n        },\n        \"pandas.core.frame.DataFrame.dropna\": {\n            \"how\": (\"'any'\", \"a row with any missing value is dropped\"),\n        },\n        # pandas 3 names the readers after their public module, pandas 2 after the file that defines them.\n        \"pandas.io.parsers.readers.read_csv\": {\n            \"header\": (\"'infer'\", first_row),\n        },\n        \"pandas.read_csv\": {\n            \"header\": (\"'infer'\", first_row),\n        },\n        \"pandas.io.parsers.readers.read_table\": {\n            \"header\": (\"'infer'\", first_row),\n        },\n        \"pandas.read_table\": {\n            \"header\": (\"'infer'\", first_row),\n        },\n        \"pandas.io.excel._base.read_excel\": {\n            \"header\": (\"0\", first_row),\n        },\n        \"pandas.read_excel\": {\n            \"header\": (\"0\", first_row),\n        },\n        \"pandas.core.frame.DataFrame.corr\": {\n            \"method\": (\"'pearson'\", \"linear correlation, sensitive to outliers\"),\n        },\n        \"pandas.core.series.Series.corr\": {\n            \"method\": (\"'pearson'\", \"linear correlation, sensitive to outliers\"),\n        },\n        \"scipy.stats._stats_py.ttest_ind\": {\n            \"equal_var\": (\"True\", \"Student's t test: assumes equal variances\"),\n        },\n        \"numpy.std\": {\"ddof\": (\"0\", \"population standard deviation, unlike pandas (ddof=1)\")},\n        \"sklearn.linear_model._logistic.LogisticRegression.__init__\": {\n            \"C\": (\"1.0\", \"L2 regularisation is on by default\"),\n        },\n        \"whybook.plots.ribbon\": {\"ci\": (\"'normal'\", \"t interval of the mean, with n - 1 degrees of freedom: assumes normal values at each x\")},\n    }\n    # Keyword arguments that name data rather than choose how to analyse it,\n    # and those that keep the books: inplace and copy say where the result\n    # goes, and ignore_index numbers the rows again, in every function that has it.\n    skipped_params = {\n        \"data\", \"x\", \"y\", \"by\", \"on\", \"columns\", \"column\", \"groups\", \"group\", \"index\", \"name\", \"labels\",\n        \"title\", \"as_index\", \"observed\", \"sort\", \"disp\", \"verbose\", \"inplace\", \"copy\", \"axis\", \"left_on\",\n        \"right_on\", \"id_vars\", \"value_vars\", \"var_name\", \"value_name\", \"subset\", \"keys\", \"path\", \"sep\",\n        \"outcome\", \"random_state\", \"seed\", \"formula\", \"ignore_index\",\n    }\n    # Parameters that keep the books in one function and mean more in another,\n    # by the function's name (design iteration 1.86): reset_index(drop=True)\n    # throws the old index away, where drop_duplicates keeps its `keep`. The\n    # chip of such a value would tell the analyst nothing about a result.\n    bookkeeping = {\n        \"reset_index\": {\"drop\", \"names\"},\n        \"set_index\": {\"drop\"},\n    }\n    # Calls whose arguments are not analysis choices.\n    skipped_functions = {\"progress\", \"print\", \"display\", \"range\", \"len\", \"enumerate\", \"zip\", \"format\", \"round\"}\n    # The parameters of a drawing function that shape the drawing and not a\n    # result: the size of a figure, its labels, marks and colours. They make\n    # no decision, so that they leave room for those that do (design\n    # iteration 1.83). The view holds the same rule (withoutDrawing in\n    # src/model/decisions.ts), for the analyses that notebooks kept before.\n    drawing_params = {\n        \"figsize\", \"dpi\", \"xlabel\", \"ylabel\", \"zlabel\", \"label\", \"title\", \"suptitle\", \"t\", \"s\", \"marker\",\n        \"markersize\", \"ms\", \"linestyle\", \"ls\", \"linewidth\", \"lw\", \"color\", \"c\", \"colors\", \"palette\", \"cmap\",\n        \"alpha\", \"edgecolor\", \"facecolor\", \"fontsize\", \"loc\", \"ncol\", \"frameon\", \"rotation\", \"grid\", \"legend\",\n        \"width\", \"height\", \"aspect\", \"size\", \"style\", \"theme\", \"bbox_inches\",\n    }\n    drawing_functions = re.compile(\n        r\"(subplots|figure|plot|scatter|bar|barh|hist|boxplot|violinplot|errorbar|fill_between|axhline|axvline\"\n        r\"|axline|step|stairs|stem|pie|imshow|text|annotate|legend|title|suptitle|savefig|xlabel|ylabel\"\n        r\"|set_xlabel|set_ylabel|set_title|set|set_xlim|set_ylim|xlim|ylim|tight_layout|grid|lineplot\"\n        r\"|scatterplot|barplot|histplot|kdeplot|regplot|lmplot|catplot|relplot|pointplot|stripplot|swarmplot\"\n        r\"|heatmap|pairplot|jointplot|displot|countplot|ggplot|aes|labs|ggtitle|xlab|ylab|theme|geom_\\w+)\"\n    )\n    # The calls that pick the rows that a cell shows, or write a value out as\n    # text to show it: the first rows of a frame, its last rows, a few rows\n    # at random. When the cell only shows their value, their arguments change\n    # what the analyst sees and nothing that a later cell reads, so they make\n    # no decision, and their signatures go to no model: the 5 rows that\n    # head() shows make no chip (design iteration 1.91). top = df.head(12)\n    # keeps its chip.\n    showing_functions = {\"head\", \"tail\", \"sample\", \"show\", \"glimpse\", \"to_string\", \"to_markdown\", \"to_html\", \"round\"}\n    # The calls that show their arguments.\n    display_functions = {\"print\", \"display\"}\n    frame_methods = {\n        \"pipe\", \"merge\", \"assign\", \"query\", \"dropna\", \"fillna\", \"sort_values\", \"rename\", \"drop\",\n        \"reset_index\", \"set_index\", \"copy\", \"astype\", \"join\", \"loc\", \"head\", \"tail\", \"sample\",\n    }\n    # Calls that join one frame to another, named by the frame they join.\n    joins = {\"merge\", \"join\", \"merge_asof\", \"merge_ordered\"}\n\n    # A key, a token or a password is no choice to try, and its text would go\n    # into the notebook with the analysis. The server, inspect_variables.py and\n    # the view hold the same rule (privacy.py says it in full,\n    # tests/data/secret_names.json holds its cases): only a string is a\n    # secret, so max_tokens=512 keeps its chip.\n    secret_words = {\"token\", \"secret\", \"secrets\", \"password\", \"passwords\", \"passwd\", \"pwd\", \"credential\", \"credentials\", \"bearer\", \"apikey\", \"auth\"}\n    secret_endings = (\"token\", \"secret\", \"password\", \"passwd\", \"apikey\")\n    secret_pairs = {(\"api\", \"key\"), (\"access\", \"key\"), (\"private\", \"key\"), (\"secret\", \"key\")}\n    secret_prefix = re.compile(\n        r\"(?<![A-Za-z0-9])(?:sk-|sk_live_|sk_test_|hf_|ghp_|gho_|ghu_|ghs_|ghr_|github_pat_|glpat-|xox[abpr]-|xapp-\"\n        r\"|AKIA|ASIA|AIza|ya29\\.|eyJ|npm_|pypi-)[A-Za-z0-9_.=-]{16,}\"\n    )\n    name_parts = re.compile(r\"[A-Z]+(?![a-z])|[A-Z]?[a-z]+\")\n    long_run = re.compile(r\"[A-Za-z0-9]{20,}\")\n    # A password in a URL, as a connection string holds it, and a query parameter named as a secret.\n    url_password = re.compile(r\"[A-Za-z][A-Za-z0-9+.-]*://[^\\s/?#@:]*:[^\\s/?#@]+@\")\n    query_name = re.compile(r\"[?&]([A-Za-z0-9_.-]+)=[^&#\\s]\")\n\n    def secret_name(name):\n        parts = [part.lower() for part in name_parts.findall(name or \"\")]\n        if any(part in secret_words or part.endswith(secret_endings) for part in parts):\n            return True\n        return any(pair in secret_pairs for pair in zip(parts, parts[1:]))\n\n    def looks_secret(name, value):\n        \"\"\"Whether a decision holds a secret, from its name and its value as written: repr of a string.\"\"\"\n        try:\n            text = ast.literal_eval(value)\n        except Exception:\n            return False\n        if not isinstance(text, str):\n            return False\n        if secret_name(name):\n            return True\n        if secret_prefix.search(text) or url_password.search(text):\n            return True\n        if any(secret_name(key) for key in query_name.findall(text)):\n            return True\n        return any(\n            len(run) >= 32 or (re.search(\"[A-Z]\", run) and re.search(\"[a-z]\", run) and re.search(\"[0-9]\", run))\n            for run in long_run.findall(text)\n        )\n\n    frames = {}\n    for name, value in list(ns.items()):\n        columns = getattr(value, \"columns\", None)\n        if name.startswith(\"_\") or columns is None or not hasattr(value, \"shape\"):\n            continue\n        try:\n            frames[name] = set(map(str, columns))\n        except Exception:\n            pass\n    known_names = set(ns) | set(dir(builtins))\n\n    def is_user_code(func):\n        # whybook is the view's own helper library, even when the notebook sits next to it.\n        module = getattr(inspect.getmodule(func), \"__name__\", None) or \"\"\n        if module.split(\".\")[0] == \"whybook\":\n            return None\n        try:\n            path = inspect.getsourcefile(func)\n        except TypeError:\n            return None\n        if not path or \"site-packages\" in path:\n            return None\n        path = os.path.realpath(path)\n        return path if path.startswith(cwd + os.sep) else None\n\n    def qualified(func):\n        target = getattr(func, \"__func__\", func)\n        module = getattr(target, \"__module__\", None)\n        name = getattr(target, \"__qualname__\", None)\n        return f\"{module}.{name}\" if module and name else None\n\n    # Where a module's name is not the name of the distribution that installs it.\n    distributions = {\"sklearn\": \"scikit-learn\", \"PIL\": \"pillow\", \"yaml\": \"PyYAML\", \"cv2\": \"opencv-python\", \"bs4\": \"beautifulsoup4\"}\n    stdlib = getattr(sys, \"stdlib_module_names\", frozenset())\n\n    def version_of(library):\n        \"\"\"A library's version: Python's for the standard library, else its __version__, else its distribution's.\"\"\"\n        versions = kept_signatures[\"versions\"]\n        if library not in versions:\n            version = getattr(sys.modules.get(library), \"__version__\", None)\n            if library in stdlib:\n                version = sys.version.split()[0]\n            elif not isinstance(version, str):\n                # importlib.metadata.packages_distributions() would tell every\n                # name, and takes about a second.\n                try:\n                    import importlib.metadata\n\n                    version = importlib.metadata.version(distributions.get(library, library))\n                except Exception:\n                    version = None\n            versions[library] = version\n        return versions[library]\n\n    plain_types = (type(None), bool, int, float, complex, str)\n    address = re.compile(r\" at 0x[0-9A-Fa-f]+\")\n    # A default that no code can write, such as pandas' <no_default> or\n    # numpy's <no value>: a marker that the parameter was not given, for\n    # which the function uses a value of its own.\n    marker = re.compile(r\"<[^<>]*>\")\n    # The value of a default as numpydoc writes it, after \"default\": a\n    # string in quotes, a number, True, False or None.\n    doc_value = re.compile(r\"\"\"'(?:[^'\\\\]|\\\\.)*'|\"(?:[^\"\\\\]|\\\\.)*\"|[-+]?\\d+(?:\\.\\d+)?(?:[eE][-+]?\\d+)?|True\\b|False\\b|None\\b\"\"\")\n\n    def documented(target, name):\n        \"\"\"The default that a function's documentation gives one of its parameters, as code; None when it gives none.\n\n        numpydoc writes it after the type, \"sep : str, default ','\", and\n        scikit-learn and SciPy as \"default=1.0\" and \"default: 0\". The value\n        that a marker stands for is there: the separator of read_csv, whose\n        signature holds <no_default>, is the comma of \"default ','\" (design\n        iteration 1.91).\n        \"\"\"\n        try:\n            doc = inspect.getdoc(target) or \"\"\n        except Exception:\n            return None\n        line = re.search(rf\"^\\s*{re.escape(name)}\\s*:\\s*(.+)$\", doc, re.M)\n        found = line and re.search(r\"\\bdefault\\b\\s*(?:[:=]\\s*)?(.+)$\", line.group(1))\n        value = found and doc_value.match(found.group(1).strip())\n        if not value:\n            return None\n        try:\n            return repr(ast.literal_eval(value.group(0)))\n        except (ValueError, SyntaxError):\n            return None\n\n    def default_of(name, value):\n        \"\"\"A default as code, and whether it holds data rather than code; None for a key, a token or a password.\n\n        A frame or an array says its type and its shape, a long text or a\n        large container its length: their values stay in the kernel.\n        \"\"\"\n        kind = type(value).__name__\n        try:\n            if isinstance(value, plain_types) and not isinstance(value, str):\n                return repr(value), False\n            if isinstance(value, str):\n                if looks_secret(name, repr(value)):\n                    return None\n                return (repr(value), False) if len(value) <= 60 else (f\"<str of {len(value)} characters>\", True)\n            if isinstance(value, (tuple, list, set, frozenset, dict)):\n                items = list(value.items()) if isinstance(value, dict) else list(value)\n                flat = [part for item in items for part in (item if isinstance(value, dict) else (item,))]\n                text = repr(value)\n                if len(items) <= 8 and len(text) <= 80 and all(isinstance(part, plain_types) for part in flat):\n                    return text, False\n                return f\"<{kind} of {len(items)} items>\", True\n            shape = getattr(value, \"shape\", None)\n            if isinstance(shape, tuple) or hasattr(value, \"columns\") or hasattr(value, \"__array__\"):\n                size = \" × \".join(str(part) for part in shape) if isinstance(shape, tuple) else \"\"\n                return (f\"<{kind} {size}>\" if size else f\"<{kind}>\"), True\n            if inspect.isroutine(value) or inspect.isclass(value) or inspect.ismodule(value):\n                module = getattr(value, \"__module__\", None)\n                label = getattr(value, \"__qualname__\", None) or getattr(value, \"__name__\", None)\n                if label:\n                    return (f\"{module}.{label}\" if module and module != \"builtins\" else label), False\n            text = address.sub(\"\", repr(value))\n            return (text, False) if len(text) <= 80 else (f\"<{kind}>\", True)\n        except Exception:\n            return f\"<{kind}>\", True\n\n    def signature_of(func, signature):\n        \"\"\"What the signature of a library function holds, read once in the session; None for any other function.\n\n        A builtin, a function that the notebook defines (``__main__``) and\n        a module whose name starts with ``_`` are no library's.\n        \"\"\"\n        key = qualified(func)\n        if key is None:\n            return None\n        functions = kept_signatures[\"functions\"]\n        if key in functions:\n            return functions[key]\n        target = getattr(func, \"__func__\", func)\n        module = getattr(target, \"__module__\", None) or \"\"\n        library = module.split(\".\")[0]\n        entry = None\n        if library and library not in (\"builtins\", \"__main__\") and not library.startswith(\"_\"):\n            params = []\n            for param in signature.parameters.values():\n                if param.default is inspect.Parameter.empty or param.kind in (param.VAR_POSITIONAL, param.VAR_KEYWORD):\n                    continue\n                found = default_of(param.name, param.default)\n                if found is not None and not found[1] and marker.fullmatch(found[0]):\n                    # A marker is no value: the default that the documentation\n                    # gives, or no parameter, so no chip says <no_default>.\n                    text = documented(target, param.name)\n                    found = (text, False) if text is not None else None\n                if found is not None:\n                    params.append({\"name\": param.name, \"default\": found[0], **({\"data\": True} if found[1] else {})})\n            name = getattr(target, \"__qualname__\", key)\n            entry = {\n                \"function\": key,\n                # A class by its own name, as the cell calls it: DataFrame, not DataFrame.__init__.\n                \"name\": name[: -len(\".__init__\")] if name.endswith(\".__init__\") else name,\n                \"module\": module,\n                \"library\": library,\n                \"version\": version_of(library),\n                \"params\": params,\n            }\n        functions[key] = entry\n        return entry\n\n    def literal(node):\n        \"\"\"The source text of a literal argument, or None.\"\"\"\n        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, str, bool)):\n            return node.value, repr(node.value)\n        if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.USub) and isinstance(node.operand, ast.Constant):\n            if isinstance(node.operand.value, (int, float)):\n                return -node.operand.value, repr(-node.operand.value)\n        if isinstance(node, (ast.List, ast.Tuple)) and 0 < len(node.elts) <= 8:\n            values = [literal(e) for e in node.elts]\n            if all(v is not None and isinstance(v[0], (int, float)) for v in values):\n                text = ast.unparse(node)\n                return text, text\n        return None\n\n    def infer(node):\n        \"\"\"What an expression evaluates to, without running it.\n\n        Returns (\"value\", object) for names and attributes found in the\n        namespace, (\"type\", class) for calls whose result type is known, or None.\n        \"\"\"\n        try:\n            if isinstance(node, ast.Name):\n                if node.id in ns:\n                    return (\"value\", ns[node.id])\n                if hasattr(builtins, node.id):\n                    return (\"value\", getattr(builtins, node.id))\n                return None\n            if isinstance(node, ast.Attribute):\n                base = infer(node.value)\n                if base is None:\n                    return None\n                kind, obj = base\n                if kind == \"value\":\n                    return (\"value\", getattr(obj, node.attr))\n                return (\"method\", (obj, getattr(obj, node.attr)))\n            if isinstance(node, ast.Call):\n                callee = infer(node.func)\n                if callee is None:\n                    return None\n                kind, obj = callee\n                if kind == \"value\" and getattr(obj, \"__name__\", \"\") == \"from_formula\" and isinstance(getattr(obj, \"__self__\", None), type):\n                    return (\"type\", obj.__self__)\n                owner = None\n                name = \"\"\n                if kind == \"value\" and hasattr(obj, \"__self__\"):\n                    owner, name = type(obj.__self__), getattr(obj, \"__name__\", \"\")\n                elif kind == \"method\":\n                    owner, name = obj[0], getattr(obj[1], \"__name__\", \"\")\n                if owner is not None and owner.__name__ == \"DataFrame\" and name in frame_methods:\n                    return (\"type\", owner)\n                if owner is not None and owner.__name__ == \"DataFrame\" and name == \"groupby\":\n                    return None\n            return None\n        except Exception:\n            return None\n\n    def resolve_call(call):\n        \"\"\"The function a call runs, how many positional slots the receiver fills, and the call's arguments.\"\"\"\n        func_node = call.func\n        positional = list(call.args)\n        keywords = {kw.arg: kw.value for kw in call.keywords if kw.arg}\n        # df.pipe(func, *args, **kwargs) runs func(df, *args, **kwargs).\n        if isinstance(func_node, ast.Attribute) and func_node.attr == \"pipe\" and positional:\n            target = infer(positional[0])\n            if target and target[0] == \"value\" and callable(target[1]):\n                return target[1], 1, positional[1:], keywords\n            return None\n        target = infer(func_node)\n        if target is None:\n            return None\n        kind, obj = target\n        if kind == \"method\":\n            owner, func = obj\n            return func, 1, positional, keywords\n        if not callable(obj):\n            return None\n        if isinstance(obj, type):\n            init = getattr(obj, \"__init__\", None)\n            return init, 1, positional, keywords\n        return obj, 0, positional, keywords\n\n    def default_node(func, param):\n        \"\"\"The AST node of a parameter's default, from the function's source.\"\"\"\n        try:\n            source = textwrap.dedent(inspect.getsource(func))\n            tree = ast.parse(source)\n        except Exception:\n            return None\n        definition = next((n for n in ast.walk(tree) if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))), None)\n        if definition is None:\n            return None\n        arguments = definition.args\n        positional = arguments.posonlyargs + arguments.args\n        defaults = dict(zip([a.arg for a in positional][-len(arguments.defaults):], arguments.defaults)) if arguments.defaults else {}\n        for a, d in zip(arguments.kwonlyargs, arguments.kw_defaults):\n            if d is not None:\n                defaults[a.arg] = d\n        return defaults.get(param)\n\n    def line_of(path, name):\n        try:\n            with open(path, encoding=\"utf-8\") as handle:\n                for number, text in enumerate(handle, start=1):\n                    if re.match(rf\"\\s*{re.escape(name)}\\s*(:[^=]*)?=\", text):\n                        return number, text.rstrip(\"\\n\")\n        except OSError:\n            pass\n        return None, None\n\n    def attachment_for(func, path, highlight):\n        try:\n            lines, start = inspect.getsourcelines(func)\n        except (OSError, TypeError):\n            return None\n        shown = [[start + i, text.rstrip(\"\\n\")] for i, text in enumerate(lines[:12])]\n        if highlight and all(number != highlight[0] for number, _ in shown):\n            shown = [highlight] + [[None, \"…\"]] + shown\n        return {\n            \"file\": os.path.relpath(path, cwd),\n            \"symbol\": getattr(func, \"__name__\", \"?\"),\n            \"start\": start,\n            \"end\": start + len(lines) - 1,\n            \"lines\": shown,\n            \"highlight\": [highlight[0]] if highlight else [],\n        }\n\n    def building(tree):\n        \"\"\"The strings of assignments that make a frame without reading one.\n\n        The keys of the dict given to pd.DataFrame name the frame's columns,\n        and so does a list of columns to read from a file, but they build the\n        frame and analyse nothing: they are not columns the cell uses.\n        \"\"\"\n        found = set()\n        for node in ast.walk(tree):\n            if not isinstance(node, ast.Assign):\n                continue\n            if not any(isinstance(target, ast.Name) and target.id in frames for target in node.targets):\n                continue\n            reads = {n.id for n in ast.walk(node.value) if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Load)}\n            if not reads & set(frames):\n                found.update(id(n) for n in ast.walk(node.value) if isinstance(n, ast.Constant))\n        return found\n\n    def parse(source):\n        \"\"\"The cell's syntax tree, with the lines and columns of the cell as it is written.\n\n        IPython's transform drops a cell's leading blank lines, which would\n        move every line of a call, so the transform is only for a cell that\n        is not plain Python, such as one with a magic.\n        \"\"\"\n        try:\n            return ast.parse(source)\n        except SyntaxError:\n            return ast.parse(shell.transform_cell(source))\n\n    def name_site(node):\n        \"\"\"Where a name is written: for ``a.b``, where ``b`` starts.\"\"\"\n        if isinstance(node, ast.Attribute):\n            return node.end_lineno, node.end_col_offset - len(node.attr.encode(\"utf-8\"))\n        return node.lineno, node.col_offset\n\n    def call_site(call):\n        \"\"\"Where a call names its function: ``merge`` in ``.merge(...)``, ``f`` in ``.pipe(f)``.\n\n        The call's own place does not tell two calls of a chain apart: each\n        starts where the chain starts.\n        \"\"\"\n        func = call.func\n        if isinstance(func, ast.Attribute) and func.attr == \"pipe\" and call.args and isinstance(call.args[0], (ast.Name, ast.Attribute)):\n            return name_site(call.args[0])\n        return name_site(func)\n\n    def shown_calls(tree):\n        \"\"\"The calls of showing_functions whose value the cell only shows, by their ids.\n\n        A value is shown, or thrown away, when it is an expression statement,\n        such as the cell's last line, or what print or display gets. The walk\n        goes down a chain while its calls only show: in ``df.head(3).round(2)``\n        both calls show, and in ``df.sort_values(\"x\").head(3)`` the sort is\n        a choice. A value that goes into a file, ``df.sample(9).to_csv(...)``,\n        is no value that the cell shows.\n        \"\"\"\n        found = set()\n\n        def walk(node):\n            while True:\n                if isinstance(node, (ast.Attribute, ast.Subscript)):\n                    node = node.value\n                    continue\n                if not isinstance(node, ast.Call):\n                    return\n                func = node.func\n                name = func.attr if isinstance(func, ast.Attribute) else func.id if isinstance(func, ast.Name) else None\n                if name in display_functions:\n                    for argument in node.args:\n                        walk(argument)\n                    return\n                if name not in showing_functions:\n                    return\n                found.add(id(node))\n                if not isinstance(func, ast.Attribute):\n                    return\n                node = func.value\n\n        for node in ast.walk(tree):\n            if isinstance(node, ast.Expr):\n                walk(node.value)\n        return found\n\n    def root(node):\n        \"\"\"The name an expression starts from: ``homes`` for ``homes[[\"home_id\"]]`` or ``homes.drop(...)``.\"\"\"\n        while node is not None:\n            if isinstance(node, ast.Name):\n                return node.id\n            if isinstance(node, (ast.Subscript, ast.Attribute)):\n                node = node.value\n            elif isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):\n                node = node.func.value\n            else:\n                return None\n        return None\n\n    def target_of(call, function_name, bound, file_param):\n        \"\"\"The frame a call joins or reads, in one word, or None.\n\n        A join names the frame it joins, a read the file it reads without its\n        extension, and another call the first frame it reads: the start of the\n        chain it is called on, else the first frame in its arguments.\n        \"\"\"\n        if function_name in joins:\n            other = bound.get(\"right\", bound.get(\"other\"))\n            name = root(other)\n            if name and (name in frames or name not in ns):\n                return name\n        if file_param:\n            file = bound.get(file_param)\n            if isinstance(file, ast.Constant) and isinstance(file.value, str):\n                return os.path.splitext(os.path.basename(file.value))[0] or None\n        if isinstance(call.func, ast.Attribute):\n            name = root(call.func.value)\n            if name in frames:\n                return name\n        for node in ast.walk(call):\n            if isinstance(node, ast.Name) and node.id in frames:\n                return node.id\n        return None\n\n    # A formula that a cell builds, such as 'y ~ x + ' + ' + '.join(covariates),\n    # is read whole from the values that it is built from: texts, numbers,\n    # and lists and dicts of them. Reading them runs no code of the analyst.\n    unknown = object()\n    max_formula = 600\n    # A text that ends in an operator is a piece of a formula: \"y ~ x +\".\n    dangling = re.compile(r\"[-+*/:~|^(,]\\s*$\")\n    scalars = (str, int, float, bool)\n    # The tests of a comprehension's condition, such as v != \"sex\".\n    comparisons = {\n        ast.Eq: lambda left, right: left == right,\n        ast.NotEq: lambda left, right: left != right,\n        ast.In: lambda left, right: left in right,\n        ast.NotIn: lambda left, right: left not in right,\n    }\n\n    def plain(value, nested=False):\n        \"\"\"Whether a value of the kernel is one that a formula is built from: a text, a number, or a list or a dict of them.\"\"\"\n        if type(value) in scalars:\n            return not isinstance(value, str) or len(value) <= max_formula\n        if not nested and type(value) in (list, tuple) and len(value) <= 200:\n            return all(plain(item, True) for item in value)\n        if not nested and type(value) is dict and len(value) <= 200:\n            return all(type(key) in (str, int) and plain(item, True) for key, item in value.items())\n        return False\n\n    def is_join(node):\n        \"\"\"Whether a node is ``sep.join(items)``.\"\"\"\n        return isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == \"join\" and len(node.args) == 1 and not node.keywords\n\n    def text_value(node, scope, stored):\n        \"\"\"What a string expression evaluates to, read without running code; ``unknown`` when it cannot be read.\n\n        It reads texts and numbers, lists and dicts of them, ``+``, f-strings,\n        an index or a slice, ``sep.join(...)``, and a comprehension over a\n        list with conditions such as ``v != \"sex\"``, which ``==``, ``!=``,\n        ``in``, ``not in``, ``not``, ``and`` and ``or`` make. A name is the\n        value that the cell assigned it above\n        (``scope``), else the kernel's, unless the cell also sets it in\n        another way (``stored``), as a loop does.\n        \"\"\"\n        if isinstance(node, ast.Constant):\n            return node.value if type(node.value) in scalars else unknown\n        if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.USub):\n            value = text_value(node.operand, scope, stored)\n            return -value if type(value) in (int, float) else unknown\n        if isinstance(node, ast.Name):\n            if node.id in scope:\n                return scope[node.id]\n            value = unknown if node.id in stored else ns.get(node.id, unknown)\n            if value is unknown or not plain(value):\n                return unknown\n            return list(value) if type(value) is tuple else value\n        if isinstance(node, (ast.List, ast.Tuple)):\n            items = [text_value(item, scope, stored) for item in node.elts]\n            return unknown if any(item is unknown for item in items) else items\n        if isinstance(node, ast.Subscript):\n            base = text_value(node.value, scope, stored)\n            if isinstance(node.slice, ast.Slice):\n                parts = (node.slice.lower, node.slice.upper, node.slice.step)\n                bounds = [None if part is None else text_value(part, scope, stored) for part in parts]\n                if isinstance(base, (str, list)) and all(bound is None or type(bound) is int for bound in bounds) and bounds[2] != 0:\n                    return base[slice(*bounds)]\n                return unknown\n            key = text_value(node.slice, scope, stored)\n            if isinstance(base, (str, list)) and type(key) is int and -len(base) <= key < len(base):\n                return base[key]\n            if isinstance(base, dict) and type(key) in (str, int) and key in base:\n                return base[key]\n            return unknown\n        if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):\n            left, right = text_value(node.left, scope, stored), text_value(node.right, scope, stored)\n            if (isinstance(left, str) and isinstance(right, str)) or (isinstance(left, list) and isinstance(right, list)):\n                return left + right\n            return unknown\n        if isinstance(node, ast.JoinedStr):\n            parts = []\n            for part in node.values:\n                if isinstance(part, ast.Constant):\n                    parts.append(str(part.value))\n                    continue\n                value = text_value(part.value, scope, stored) if part.format_spec is None else unknown\n                if type(value) not in scalars or part.conversion not in (-1, 114, 115):\n                    return unknown\n                parts.append(repr(value) if part.conversion == 114 else str(value))\n            return \"\".join(parts)\n        if is_join(node):\n            separator, items = text_value(node.func.value, scope, stored), text_value(node.args[0], scope, stored)\n            if isinstance(separator, str) and isinstance(items, list) and all(isinstance(item, str) for item in items):\n                return separator.join(items)\n            return unknown\n        if isinstance(node, ast.Compare) and len(node.ops) == 1 and type(node.ops[0]) in comparisons:\n            left, right = text_value(node.left, scope, stored), text_value(node.comparators[0], scope, stored)\n            if left is unknown or right is unknown or (type(node.ops[0]) in (ast.In, ast.NotIn) and not isinstance(right, (str, list, dict))):\n                return unknown\n            if isinstance(right, str) and type(node.ops[0]) in (ast.In, ast.NotIn) and not isinstance(left, str):\n                return unknown\n            return comparisons[type(node.ops[0])](left, right)\n        if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):\n            value = text_value(node.operand, scope, stored)\n            return not value if type(value) is bool else unknown\n        if isinstance(node, ast.BoolOp):\n            values = [text_value(item, scope, stored) for item in node.values]\n            if any(type(value) is not bool for value in values):\n                return unknown\n            return all(values) if isinstance(node.op, ast.And) else any(values)\n        if isinstance(node, (ast.ListComp, ast.GeneratorExp)) and len(node.generators) == 1:\n            loop = node.generators[0]\n            items = text_value(loop.iter, scope, stored)\n            if loop.is_async or not isinstance(loop.target, ast.Name) or not isinstance(items, list):\n                return unknown\n            values = []\n            for item in items:\n                inner = {**scope, loop.target.id: item}\n                kept = [text_value(condition, inner, stored) for condition in loop.ifs]\n                if any(type(keep) is not bool for keep in kept):\n                    return unknown\n                if all(kept):\n                    values.append(text_value(node.elt, inner, stored))\n            return unknown if any(value is unknown for value in values) else values\n        return unknown\n\n    def in_words(node, scope, stored):\n        \"\"\"A string expression as text, with what each join adds in words: \"y ~ x + the 9 names of covariates\".\n\n        The names are counted when the list is known. None where a part\n        that is no join cannot be read.\n        \"\"\"\n        if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):\n            left, right = in_words(node.left, scope, stored), in_words(node.right, scope, stored)\n            return left + right if left is not None and right is not None else None\n        if isinstance(node, ast.JoinedStr):\n            parts = []\n            for part in node.values:\n                if isinstance(part, ast.FormattedValue) and is_join(part.value) and part.format_spec is None and part.conversion == -1:\n                    parts.append(in_words(part.value, scope, stored))\n                else:\n                    value = text_value(ast.JoinedStr(values=[part]), scope, stored)\n                    parts.append(value if isinstance(value, str) else None)\n            return None if None in parts else \"\".join(parts)\n        if is_join(node):\n            items = node.args[0]\n            if isinstance(items, (ast.ListComp, ast.GeneratorExp)) and len(items.generators) == 1:\n                if items.generators[0].ifs:\n                    # A condition picks some of the names: no count says how many.\n                    return None\n                items = items.generators[0].iter\n            elif isinstance(items, ast.Call) and isinstance(items.func, ast.Name) and items.func.id == \"map\" and len(items.args) == 2:\n                items = items.args[1]\n            name = ast.unparse(items)\n            if len(name) > 40:\n                return None\n            known = text_value(items, scope, stored)\n            if not isinstance(known, list):\n                return f\"the names of {name}\"\n            return f\"the name of {name}\" if len(known) == 1 else f\"the {len(known)} names of {name}\"\n        value = text_value(node, scope, stored)\n        return value if isinstance(value, str) else None\n\n    def operands(node):\n        \"\"\"The parts that a string expression adds up: those of ``a + b``, and those of an f-string.\"\"\"\n        if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):\n            return operands(node.left) + operands(node.right)\n        return list(node.values) if isinstance(node, ast.JoinedStr) else [node]\n\n    def holds_pieces(value, node):\n        \"\"\"Whether a text holds the strings that an expression writes itself, in their order.\"\"\"\n        at = 0\n        for part in operands(node):\n            if isinstance(part, ast.Constant) and isinstance(part.value, str):\n                at = value.find(part.value, at)\n                if at < 0:\n                    return False\n                at += len(part.value)\n        return True\n\n    def formula_texts(tree, pieces):\n        \"\"\"The formulas of a cell, from its strings that hold \"~\" (``pieces``), each whole and in their order.\n\n        A formula that the cell writes as one string is that string. One\n        that it builds, as ``'y ~ x + ' + ' + '.join(covariates)``, is the\n        text that the code builds (``text_value``); else the kernel's value\n        of the name that the cell assigns it to, when that value holds the\n        strings of the code; else the text with what a join adds in words,\n        \"y ~ x + the 9 names of covariates\" (``in_words``). For a name that\n        the cell changes after, as ``formula += \" + age\"`` does, the\n        kernel's value comes first. A function's names are its own, so a\n        formula in a function is read only when it is written whole. A piece\n        that cannot be read whole, such as \"y ~ x +\", is no formula.\n        \"\"\"\n        if not pieces:\n            return []\n        parents = {}\n        for node in ast.walk(tree):\n            for child in ast.iter_child_nodes(node):\n                parents[child] = node\n        # The names that the cell sets in another way than ``name = ...`` at\n        # its top level, such as a loop's: they hold no one value to read.\n        plain_targets = {\n            id(statement.targets[0])\n            for statement in tree.body\n            if isinstance(statement, ast.Assign) and len(statement.targets) == 1 and isinstance(statement.targets[0], ast.Name)\n        }\n        stored = {node.id for node in ast.walk(tree) if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store) and id(node) not in plain_targets}\n        # What the assignments at the top level hold before each statement.\n        scopes, scope = {}, {}\n        for statement in tree.body:\n            scopes[statement] = dict(scope)\n            if isinstance(statement, ast.Assign) and id(statement.targets[0]) in plain_targets:\n                name = statement.targets[0].id\n                try:\n                    value = text_value(statement.value, scope, stored)\n                except Exception:\n                    value = unknown\n                if value is unknown or name in stored:\n                    scope.pop(name, None)\n                else:\n                    scope[name] = value\n\n        def whole(text):\n            return isinstance(text, str) and \"~\" in text and len(text) <= max_formula and not dangling.search(text)\n\n        def read(top):\n            statement, inside = top, False\n            while not isinstance(parents[statement], ast.Module):\n                statement = parents[statement]\n                inside = inside or isinstance(statement, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda))\n            if inside:\n                return top.value if isinstance(top, ast.Constant) and whole(top.value) and len(top.value) < 300 else None\n            # The kernel's value of the name that the statement assigns the formula to.\n            assigned = isinstance(statement, ast.Assign) and parents[top] is statement and id(statement.targets[0]) in plain_targets\n            kept = ns.get(statement.targets[0].id) if assigned else None\n            kept = kept if whole(kept) and holds_pieces(kept, top) else None\n            if kept and statement.targets[0].id in stored:\n                # The cell changes the name after, as formula += \" + age\" does.\n                return kept\n            if isinstance(top, ast.Constant):\n                return top.value if whole(top.value) and len(top.value) < 300 else None\n            built = text_value(top, scopes[statement], stored)\n            if whole(built):\n                return built\n            if kept:\n                return kept\n            words = in_words(top, scopes[statement], stored)\n            return words if whole(words) else None\n\n        found, seen = [], set()\n        for piece in pieces:\n            top = piece\n            while (isinstance(parents.get(top), ast.BinOp) and isinstance(parents[top].op, ast.Add)) or isinstance(parents.get(top), ast.JoinedStr):\n                top = parents[top]\n            if top in seen:\n                continue\n            seen.add(top)\n            try:\n                text = read(top)\n            except Exception:\n                text = None\n            if text is not None and text not in found:\n                found.append(text)\n        return found\n\n    def analyze(source):\n        tree = parse(source)\n        defs, uses, strings = [], [], []\n        # The strings that hold \"~\": formulas, or pieces of one.\n        pieces = []\n        made = building(tree)\n        for node in ast.walk(tree):\n            if isinstance(node, ast.Name):\n                (defs if isinstance(node.ctx, ast.Store) else uses).append(node.id)\n            elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):\n                defs.append(node.name)\n            elif isinstance(node, (ast.Import, ast.ImportFrom)):\n                for alias in node.names:\n                    defs.append((alias.asname or alias.name).split(\".\")[0])\n            elif isinstance(node, ast.Constant) and isinstance(node.value, str):\n                if id(node) not in made:\n                    strings.append(node.value)\n                if \"~\" in node.value:\n                    pieces.append(node)\n        formulas = formula_texts(tree, pieces)\n        used_frames = [name for name in dict.fromkeys(uses) if name in frames]\n        defined_frames = [name for name in dict.fromkeys(defs) if name in frames]\n        touched = {}\n        candidates = set()\n        for text in strings:\n            if \"~\" in text:\n                candidates.update(re.findall(r\"[A-Za-z_][A-Za-z0-9_]*\", text))\n            else:\n                candidates.add(text)\n        for node in ast.walk(tree):\n            if isinstance(node, ast.Attribute) and isinstance(node.value, ast.Name) and node.value.id in frames:\n                candidates.add(node.attr)\n        for frame in dict.fromkeys(used_frames + defined_frames):\n            for column in sorted(candidates & frames[frame]):\n                touched.setdefault(frame, []).append(column)\n\n        decisions, attachments, seen = [], [], set()\n        # The library functions that the cell calls, by qualified name, with their calls.\n        signatures = {}\n        shown = shown_calls(tree)\n\n        def short(function):\n            return (function or \"\").rsplit(\".\", 1)[-1]\n\n        def add(entry, call=None):\n            \"\"\"Add a decision of a call, keyed by the call, or of an assignment, keyed by its name.\n\n            A call that leaves the same parameter at the same value as an\n            earlier call joins that call's decision: both merges of a cell\n            that leave ``how='inner'`` make one decision with two calls.\n            \"\"\"\n            key = (entry[\"name\"], call and (call[\"line\"], call[\"col\"]))\n            if key in seen or looks_secret(entry[\"name\"], str(entry[\"value\"])):\n                return\n            seen.add(key)\n            if call is None:\n                decisions.append(entry)\n                return\n            for other in decisions:\n                if (\n                    \"calls\" in other\n                    and other[\"name\"] == entry[\"name\"]\n                    and other[\"value\"] == entry[\"value\"]\n                    and other[\"provenance\"] == entry[\"provenance\"]\n                    and other.get(\"param\") == entry.get(\"param\")\n                    and short(other.get(\"function\")) == short(entry.get(\"function\"))\n                ):\n                    other[\"calls\"].append(dict(call))\n                    return\n            decisions.append({**entry, \"calls\": [dict(call)]})\n\n        for node in ast.walk(tree):\n            if not isinstance(node, ast.Call):\n                continue\n            try:\n                resolved = resolve_call(node)\n            except Exception:\n                resolved = None\n            if resolved is None:\n                continue\n            func, receiver_slots, positional, keywords = resolved\n            try:\n                signature = inspect.signature(func)\n            except (TypeError, ValueError):\n                continue\n            params = [p for p in signature.parameters.values() if p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD)]\n            bound_positional = [p.name for p in params[receiver_slots : receiver_slots + len(positional)]]\n            passed = set(bound_positional) | set(keywords)\n            if receiver_slots and params:\n                passed.add(params[0].name)\n            function_name = getattr(func, \"__name__\", \"?\")\n            if function_name in skipped_functions or id(node) in shown:\n                continue\n            # The file that a reader such as read_csv or read_parquet reads, even\n            # where its parameter is named \"path\", a name kept out below.\n            reads_file = function_name.startswith((\"read_\", \"scan_\")) and len(params) > receiver_slots\n            file_param = params[receiver_slots].name if reads_file else None\n            bound = {**dict(zip(bound_positional, positional)), **keywords}\n            line, col = call_site(node)\n            try:\n                target = target_of(node, function_name, bound, file_param)\n            except Exception:\n                target = None\n            call = {\"line\": line, \"col\": col, \"target\": target}\n            user_path = is_user_code(func)\n            qualname = qualified(func)\n            # A call that unpacks its arguments may pass any parameter.\n            unpacks = any(isinstance(arg, ast.Starred) for arg in node.args) or any(kw.arg is None for kw in node.keywords)\n            if read_signatures and not user_path and not unpacks:\n                read = signature_of(func, signature)\n                defaulted = [p[\"name\"] for p in read[\"params\"] if p[\"name\"] not in passed] if read else []\n                if defaulted:\n                    signatures.setdefault(read[\"function\"], {**read, \"calls\": []})[\"calls\"].append({**call, \"defaulted\": defaulted})\n            for param in signature.parameters.values():\n                if param.name in passed or param.default is inspect.Parameter.empty:\n                    continue\n                if param.kind in (param.VAR_POSITIONAL, param.VAR_KEYWORD):\n                    continue\n                if user_path:\n                    node_default = default_node(func, param.name)\n                    highlight = None\n                    if isinstance(node_default, ast.Name) and node_default.id in getattr(func, \"__globals__\", {}):\n                        constant = node_default.id\n                        number, text = line_of(user_path, constant)\n                        highlight = [number, text] if number else None\n                        add({\n                            \"name\": constant,\n                            \"value\": repr(func.__globals__[constant]),\n                            \"provenance\": \"defaulted\",\n                            \"param\": param.name,\n                            \"function\": function_name,\n                            \"source\": {\"file\": os.path.relpath(user_path, cwd), \"line\": number},\n                        }, call)\n                    else:\n                        add({\n                            \"name\": param.name,\n                            \"value\": repr(param.default),\n                            \"provenance\": \"defaulted\",\n                            \"param\": param.name,\n                            \"function\": function_name,\n                            \"source\": {\"file\": os.path.relpath(user_path, cwd), \"line\": None},\n                        }, call)\n                    attachment = attachment_for(func, user_path, highlight)\n                    if attachment and all(a[\"symbol\"] != attachment[\"symbol\"] for a in attachments):\n                        attachments.append(attachment)\n                elif qualname in library_defaults and param.name in library_defaults[qualname]:\n                    label, note = library_defaults[qualname][param.name]\n                    library = qualname.split(\".\")[0]\n                    version = version_of(library)\n                    add({\n                        \"name\": param.name,\n                        \"value\": label,\n                        \"provenance\": \"library_default\",\n                        \"param\": param.name,\n                        \"function\": qualname.rsplit(\".\", 2)[-2] + \".\" + function_name if \".\" in qualname else function_name,\n                        \"note\": note,\n                        # The popover says \"default in pandas 3.0.6\".\n                        \"library\": library,\n                        **({\"version\": version} if version else {}),\n                    }, call)\n            for name, value_node in bound.items():\n                if name in skipped_params and name != file_param:\n                    continue\n                if name in bookkeeping.get(function_name, ()):\n                    continue\n                if name in drawing_params and drawing_functions.fullmatch(function_name):\n                    continue\n                found = literal(value_node)\n                if found is None:\n                    continue\n                value, text = found\n                if isinstance(value, str) and (value in known_names or any(value in cols for cols in frames.values())):\n                    continue\n                add({\"name\": name, \"value\": text, \"provenance\": \"literal\", \"param\": name, \"function\": function_name}, call)\n        for node in tree.body:\n            if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):\n                name = node.targets[0].id\n                found = literal(node.value)\n                # A helper of one cell, named with an underscore by Python's\n                # custom and by the cells that Whybook and its agents write,\n                # holds no constant to try; and a string that names a column,\n                # a variable or a model, y = \"wt82_71\" or a formula, names\n                # data, as a keyword argument does (design iteration 1.91).\n                if found is None or name.startswith(\"_\"):\n                    continue\n                if isinstance(found[0], str) and isinstance(node.value, ast.Constant):\n                    if found[0] in known_names or any(found[0] in cols for cols in frames.values()) or \"~\" in found[0]:\n                        continue\n                add({\"name\": name, \"value\": found[1], \"provenance\": \"literal\", \"param\": None, \"function\": None})\n        order = {\"defaulted\": 0, \"library_default\": 1, \"literal\": 2}\n        decisions.sort(key=lambda d: order[d[\"provenance\"]])\n        for decision in decisions:\n            if \"calls\" in decision:\n                decision[\"calls\"].sort(key=lambda call: (call[\"line\"], call[\"col\"]))\n        result = {\n            \"defs\": sorted(set(defs)),\n            \"uses\": sorted({u for u in uses if u in known_names and not hasattr(builtins, u)}),\n            \"formulas\": formulas,\n            \"columns\": touched,\n            \"decisions\": decisions[:max_decisions],\n            \"attachments\": attachments,\n        }\n        if read_signatures:\n            # In the order of the code: ast.walk reaches the last call of a chain first.\n            for listed in signatures.values():\n                listed[\"calls\"].sort(key=lambda call: (call[\"line\"], call[\"col\"]))\n            ordered = sorted(signatures.values(), key=lambda listed: (listed[\"calls\"][0][\"line\"], listed[\"calls\"][0][\"col\"]))\n            result[\"signatures\"] = ordered[:max_signatures]\n        return result\n\n    results = {}\n    for cell in args.get(\"cells\", []):\n        try:\n            results[cell[\"id\"]] = analyze(cell[\"source\"])\n        except SyntaxError as error:\n            results[cell[\"id\"]] = {\"error\": f\"SyntaxError: {error.msg}\"}\n        except Exception as error:\n            results[cell[\"id\"]] = {\"error\": repr(error)}\n    display({\"application/vnd.whybook.result+json\": {\"cells\": results}}, raw=True)\n";

export const inspectVariables = "\"\"\"List the user's variables with what the Variables and Contents sections show.\n\nThe frontend bundle holds the text of this file (scripts/embed-kernel-code.mjs)\nand runs it in the kernel, preferably in a subshell, so it must not import the\nwhybook package. It uses narwhals for data frames and series, and skips them\nwhen narwhals is not installed. The result goes out as display data with a\nMIME type that output areas do not render.\n\n``args[\"known\"]`` maps variable names to the fingerprint the frontend already\nholds. A frame whose fingerprint has not changed is sent as a stub, which keeps\na 4 812-column panel from being summarised again after every cell.\n\"\"\"\n\n\ndef _whybook_inspect_variables(args):\n    import importlib.metadata\n    import importlib.util\n    import math\n    import os\n    import re\n    import sys\n    import types\n\n    from IPython import get_ipython\n    from IPython.display import display\n\n    try:\n        import narwhals as nw\n    except ImportError:\n        nw = None\n\n    known = args.get(\"known\") or {}\n    max_columns = args.get(\"max_columns\", 20000)\n    # Above this many values, distinct counts and ranges are skipped.\n    detail_limit = args.get(\"detail_limit\", 20_000_000)\n\n    skipped_types = (types.ModuleType, types.FunctionType, types.BuiltinFunctionType, types.MethodType, type)\n    packages_to_report = (\n        (\"pandas\", \"pandas\"),\n        (\"polars\", \"polars\"),\n        (\"pyarrow\", \"pyarrow\"),\n        (\"narwhals\", \"narwhals\"),\n        (\"numpy\", \"numpy\"),\n        (\"scipy\", \"scipy\"),\n        (\"statsmodels\", \"statsmodels\"),\n        (\"sklearn\", \"scikit-learn\"),\n        (\"pingouin\", \"pingouin\"),\n        (\"matplotlib\", \"matplotlib\"),\n        (\"seaborn\", \"seaborn\"),\n        (\"altair\", \"altair\"),\n        (\"plotly\", \"plotly\"),\n        (\"whybook\", \"whybook\"),\n    )\n    cwd = os.path.realpath(os.getcwd())\n\n    # A key, a token or a password in a variable is listed with its length and\n    # \"secret\": true, never its text: the view keeps the listing in the\n    # notebook and sends it with every request to a model. The server, this\n    # file, analyze_cells.py and the view hold the same rule (privacy.py says\n    # it in full, tests/data/secret_names.json holds its cases): only a string\n    # is a secret, when a part of its name says so, as the \"token\" of HF_TOKEN,\n    # or its text holds a known prefix of a key or a long run of letters and digits.\n    secret_words = {\"token\", \"secret\", \"secrets\", \"password\", \"passwords\", \"passwd\", \"pwd\", \"credential\", \"credentials\", \"bearer\", \"apikey\", \"auth\"}\n    secret_endings = (\"token\", \"secret\", \"password\", \"passwd\", \"apikey\")\n    secret_pairs = {(\"api\", \"key\"), (\"access\", \"key\"), (\"private\", \"key\"), (\"secret\", \"key\")}\n    secret_prefix = re.compile(\n        r\"(?<![A-Za-z0-9])(?:sk-|sk_live_|sk_test_|hf_|ghp_|gho_|ghu_|ghs_|ghr_|github_pat_|glpat-|xox[abpr]-|xapp-\"\n        r\"|AKIA|ASIA|AIza|ya29\\.|eyJ|npm_|pypi-)[A-Za-z0-9_.=-]{16,}\"\n    )\n    name_parts = re.compile(r\"[A-Z]+(?![a-z])|[A-Z]?[a-z]+\")\n    long_run = re.compile(r\"[A-Za-z0-9]{20,}\")\n    # A password in a URL, as a connection string holds it, and a query parameter named as a secret.\n    url_password = re.compile(r\"[A-Za-z][A-Za-z0-9+.-]*://[^\\s/?#@:]*:[^\\s/?#@]+@\")\n    query_name = re.compile(r\"[?&]([A-Za-z0-9_.-]+)=[^&#\\s]\")\n\n    def secret_name(name):\n        parts = [part.lower() for part in name_parts.findall(name)]\n        if any(part in secret_words or part.endswith(secret_endings) for part in parts):\n            return True\n        return any(pair in secret_pairs for pair in zip(parts, parts[1:]))\n\n    def secret_string(name, text):\n        if secret_name(name):\n            return True\n        # The text of a string of up to 10,000 characters: a longer one is listed by its length alone.\n        if len(text) > 10_000:\n            return False\n        if secret_prefix.search(text) or url_password.search(text):\n            return True\n        if any(secret_name(key) for key in query_name.findall(text)):\n            return True\n        return any(\n            len(run) >= 32 or (re.search(\"[A-Z]\", run) and re.search(\"[a-z]\", run) and re.search(\"[0-9]\", run))\n            for run in long_run.findall(text)\n        )\n\n    def type_name(value):\n        cls = type(value)\n        return f\"{cls.__module__}.{cls.__qualname__}\"\n\n    def clean(value):\n        if value is None:\n            return None\n        if isinstance(value, bool):\n            return value\n        if isinstance(value, int):\n            return value\n        try:\n            as_float = float(value)\n        except (TypeError, ValueError):\n            return str(value)\n        if math.isnan(as_float):\n            return None\n        # Six significant figures: a fixed number of decimals made 1e-7 and 4e-5 read 0.\n        # The view formats a number for display (src/model/numbers.ts).\n        short = float(f\"{as_float:.6g}\")\n        return int(short) if short.is_integer() and abs(short) < 2**53 else short\n\n    def is_ordered(series):\n        # A pandas categorical marked ordered, and a polars Enum.\n        try:\n            return bool(nw.is_ordered_categorical(series))\n        except Exception:\n            return False\n\n    def column_tag(label, dtype, n_unique, rows, ordered):\n        lowered = str(label).lower()\n        if isinstance(dtype, nw.Boolean):\n            return \"bool\"\n        if lowered == \"id\" or lowered.endswith(\"_id\"):\n            return \"id\"\n        if dtype.is_integer():\n            return \"int\"\n        if dtype.is_numeric():\n            return \"num\"\n        if dtype.is_temporal():\n            return \"date\"\n        if isinstance(dtype, (nw.String, nw.Categorical, nw.Enum)):\n            if ordered:\n                return \"ord\"\n            if n_unique is not None and rows and n_unique > 50 and n_unique > 0.5 * rows:\n                return \"text\"\n            return \"cat\"\n        return \"other\"\n\n    def column_kind(tag, n_unique):\n        if tag == \"bool\" or (n_unique == 2 and tag in (\"int\", \"num\", \"cat\", \"ord\")):\n            return \"binary\"\n        return {\n            \"int\": \"numeric\",\n            \"num\": \"numeric\",\n            \"date\": \"datetime\",\n            \"cat\": \"categorical\",\n            \"ord\": \"categorical\",\n            \"id\": \"id\",\n            \"text\": \"text\",\n        }.get(tag, \"other\")\n\n    def column_entry(label, dtype, stats):\n        \"\"\"One column of the Contents list, from precomputed statistics.\"\"\"\n        entry = {\"label\": str(label), \"dtype\": str(dtype), \"missing\": stats.get(\"missing\", 0)}\n        n_unique = stats.get(\"unique\")\n        tag = column_tag(label, dtype, n_unique, stats.get(\"rows\"), stats.get(\"ordered\", False))\n        entry[\"tag\"] = tag\n        entry[\"kind\"] = column_kind(tag, n_unique)\n        if n_unique is not None:\n            entry[\"unique\"] = n_unique\n        for key in (\"min\", \"max\", \"levels\"):\n            if stats.get(key) is not None:\n                entry[key] = stats[key]\n        if entry[\"tag\"] not in (\"int\", \"num\", \"date\"):\n            entry.pop(\"min\", None)\n            entry.pop(\"max\", None)\n        return entry\n\n    def describe_series(label, series, detailed):\n        rows = len(series)\n        stats = {\"rows\": rows, \"missing\": int(series.null_count()), \"ordered\": is_ordered(series)}\n        if detailed:\n            try:\n                # n_unique counts a missing value as one more level.\n                stats[\"unique\"] = int(series.n_unique()) - (1 if stats[\"missing\"] else 0)\n            except Exception:  # unhashable values, such as lists\n                pass\n            try:\n                if series.dtype.is_numeric() or series.dtype.is_temporal():\n                    stats[\"min\"], stats[\"max\"] = clean(series.min()), clean(series.max())\n            except Exception:\n                pass\n            if stats.get(\"unique\") is not None and stats[\"unique\"] <= 6:\n                stats[\"levels\"] = levels_of(nw.to_native(series), series)\n        return column_entry(label, series.dtype, stats)\n\n    def levels_of(native, series):\n        try:\n            categories = getattr(getattr(native, \"cat\", None), \"categories\", None)\n            if categories is not None:\n                return [str(v) for v in list(categories)][:6]\n            return [str(v) for v in sorted(series.drop_nulls().unique().to_list(), key=str)][:6]\n        except Exception:\n            return None\n\n    def pandas_stats(native, labels, detailed):\n        \"\"\"Column statistics for a pandas frame, with one vectorised call per statistic.\n\n        narwhals builds one expression per column, which takes seconds on a\n        frame with thousands of columns.\n        \"\"\"\n        import numpy as np\n        import pandas as pd\n\n        frame = native[labels]\n        rows = len(frame)\n        missing = frame.isna().sum()\n        stats = {label: {\"rows\": rows, \"missing\": int(missing[label])} for label in labels}\n        dtypes = frame.dtypes\n        for label in labels:\n            stats[label][\"ordered\"] = bool(getattr(dtypes[label], \"ordered\", False))\n        if not detailed:\n            return stats\n        numeric = [\n            label for label in labels\n            if pd.api.types.is_numeric_dtype(dtypes[label]) and not pd.api.types.is_bool_dtype(dtypes[label])\n        ]\n        if numeric:\n            values = frame[numeric].to_numpy(dtype=float, na_value=np.nan)\n            ordered_values = np.sort(values, axis=0)\n            valid = ~np.isnan(ordered_values)\n            changes = (np.diff(ordered_values, axis=0) != 0) & valid[1:]\n            distinct = changes.sum(axis=0) + valid.any(axis=0)\n            with np.errstate(all=\"ignore\"):\n                lows = np.nanmin(np.where(valid.any(axis=0), values, 0), axis=0) if rows else []\n                highs = np.nanmax(np.where(valid.any(axis=0), values, 0), axis=0) if rows else []\n            for index, label in enumerate(numeric):\n                stats[label][\"unique\"] = int(distinct[index])\n                if valid[:, index].any():\n                    stats[label][\"min\"] = clean(lows[index])\n                    stats[label][\"max\"] = clean(highs[index])\n        for label in labels:\n            if label in numeric:\n                continue\n            series = frame[label]\n            try:\n                stats[label][\"unique\"] = int(series.nunique(dropna=True))\n            except TypeError:  # unhashable values, such as lists\n                continue\n            if pd.api.types.is_datetime64_any_dtype(series):\n                stats[label][\"min\"], stats[label][\"max\"] = clean(series.min()), clean(series.max())\n            if stats[label][\"unique\"] <= 6:\n                categories = getattr(getattr(series, \"cat\", None), \"categories\", None)\n                values = list(categories) if categories is not None else sorted(series.dropna().unique().tolist(), key=str)\n                stats[label][\"levels\"] = [str(v) for v in values][:6]\n        return stats\n\n    def narwhals_stats(frame, labels, detailed):\n        stats = {}\n        for label in labels:\n            series = frame.get_column(label)\n            entry = {\"rows\": len(series), \"missing\": int(series.null_count()), \"ordered\": is_ordered(series)}\n            if detailed:\n                try:\n                    entry[\"unique\"] = int(series.n_unique()) - (1 if entry[\"missing\"] else 0)\n                except Exception:\n                    pass\n                try:\n                    if series.dtype.is_numeric() or series.dtype.is_temporal():\n                        entry[\"min\"], entry[\"max\"] = clean(series.min()), clean(series.max())\n                except Exception:\n                    pass\n                if entry.get(\"unique\") is not None and entry[\"unique\"] <= 6:\n                    entry[\"levels\"] = levels_of(nw.to_native(series), series)\n            stats[label] = entry\n        return stats\n\n    def frame_metadata(value, columns):\n        attrs = getattr(value, \"attrs\", None)\n        meta = attrs.get(\"whybook\") if isinstance(attrs, dict) else None\n        if not isinstance(meta, dict):\n            return None, None, None\n        present = set(map(str, columns))\n        groups = []\n        for label, names in (meta.get(\"groups\") or {}).items():\n            kept = [str(n) for n in names if str(n) in present]\n            if kept:\n                groups.append({\"label\": str(label), \"columns\": kept})\n        selection = meta.get(\"selection\")\n        return groups or None, meta.get(\"grouped_by\"), selection if isinstance(selection, dict) else None\n\n    def missing_counts(value, frame):\n        \"\"\"The missing values of each column, as bytes, over at most 16 million cells at a time.\"\"\"\n        if hasattr(value, \"isna\") and hasattr(value, \"iloc\"):\n            rows, width = value.shape\n            step = max(1, 16_000_000 // max(rows, 1))\n            if width <= step:\n                return value.isna().to_numpy().sum(axis=0).tobytes()\n            return b\"\".join(value.iloc[:, start : start + step].isna().to_numpy().sum(axis=0).tobytes() for start in range(0, width, step))\n        return repr(frame.null_count().row(0)).encode()\n\n    def fingerprint(value, frame, shape):\n        \"\"\"The frame's id, shape, column names, column types and missing counts.\n\n        A column filled or recoded in place leaves the id, the shape and the\n        names as they were: its missing count or its type tells the change.\n        On 29 September 2026 the fingerprint of the later demo's olink, 318\n        rows and 4,813 columns, took 6 ms, where the names alone took 3 ms,\n        and that of the home energy readings, 129,058 rows, 5 ms.\n        \"\"\"\n        parts = [str(id(value)), str(shape)]\n        columns = getattr(value, \"columns\", None)\n        try:\n            parts.append(str(hash(tuple(map(str, columns))) if columns is not None else 0))\n        except Exception:\n            parts.append(\"0\")\n        try:\n            # The dtype objects themselves: a str() of each takes 84 ms on olink.\n            parts.append(str(hash(tuple(value.dtypes))))\n        except Exception:\n            try:\n                parts.append(str(hash(tuple(map(str, frame.schema.values())))))\n            except Exception:\n                parts.append(\"0\")\n        try:\n            parts.append(str(hash(missing_counts(value, frame))))\n        except Exception:\n            parts.append(\"0\")\n        return \":\".join(parts)\n\n    def describe_frame(name, frame, value):\n        rows, n_columns = frame.shape\n        labels = list(frame.columns)[:max_columns]\n        detailed = rows * len(labels) <= detail_limit\n        native = nw.to_native(frame)\n        try:\n            import pandas as pd\n\n            is_pandas = isinstance(native, pd.DataFrame)\n        except ImportError:\n            is_pandas = False\n        stats = pandas_stats(native, labels, detailed) if is_pandas else narwhals_stats(frame, labels, detailed)\n        schema = frame.schema\n        columns = []\n        for label in labels:\n            try:\n                columns.append(column_entry(label, schema[label], stats[label]))\n            except Exception as error:\n                columns.append({\"label\": str(label), \"tag\": \"other\", \"kind\": \"other\", \"error\": repr(error)})\n        groups, grouped_by, selection = frame_metadata(value, labels)\n        entry = {\n            \"name\": name,\n            \"label\": name,\n            \"kind\": \"dataframe\",\n            \"type\": type_name(value),\n            \"rows\": rows,\n            \"n_columns\": n_columns,\n            \"columns\": columns,\n        }\n        if groups:\n            entry[\"groups\"] = groups\n            entry[\"grouped_by\"] = grouped_by\n        if selection:\n            entry[\"selection\"] = selection\n        return entry\n\n    def describe_model(name, value):\n        entry = {\"name\": name, \"label\": name, \"kind\": \"model\", \"type\": type_name(value)}\n        model = getattr(value, \"model\", None)\n        entry[\"model_class\"] = type(model).__name__ if model is not None else None\n        formula = getattr(model, \"formula\", None)\n        if isinstance(formula, str):\n            entry[\"formula\"] = formula\n        try:\n            entry[\"nobs\"] = int(getattr(value, \"nobs\"))\n        except Exception:\n            pass\n        converged = getattr(value, \"converged\", None)\n        if isinstance(converged, bool):\n            entry[\"converged\"] = converged\n        try:\n            params = value.params\n            ci = value.conf_int()\n            pvalues = getattr(value, \"pvalues\", None)\n            terms = []\n            for term in list(params.index)[:40]:\n                row = {\"term\": str(term), \"coef\": clean(params[term])}\n                try:\n                    row[\"lo\"] = clean(ci.loc[term].iloc[0])\n                    row[\"hi\"] = clean(ci.loc[term].iloc[1])\n                except Exception:\n                    pass\n                if pvalues is not None:\n                    try:\n                        row[\"p\"] = clean(pvalues[term])\n                    except Exception:\n                        pass\n                terms.append(row)\n            entry[\"terms\"] = terms\n        except Exception as error:\n            entry[\"error\"] = repr(error)\n        return entry\n\n    user_modules = []\n    for module in list(sys.modules.values()):\n        path = getattr(module, \"__file__\", None)\n        if not path or \"site-packages\" in path:\n            continue\n        path = os.path.realpath(path)\n        if path.startswith(cwd + os.sep) and path.endswith(\".py\"):\n            user_modules.append((module, path))\n\n    def constant_source(name, value):\n        for module, path in user_modules:\n            namespace = vars(module)\n            if name in namespace and type(namespace[name]) is type(value) and namespace[name] == value:\n                line = None\n                try:\n                    with open(path, encoding=\"utf-8\") as handle:\n                        for number, text in enumerate(handle, start=1):\n                            if re.match(rf\"\\s*{re.escape(name)}\\s*(:[^=]*)?=\", text):\n                                line = number\n                                break\n                except OSError:\n                    pass\n                return {\"file\": os.path.relpath(path, cwd), \"line\": line, \"module\": module.__name__}\n        return None\n\n    def describe(name, value):\n        type_ = type_name(value)\n        shape = getattr(value, \"shape\", None)\n        if nw is not None:\n            try:\n                wrapped = nw.from_native(value, eager_only=True, allow_series=True)\n            except TypeError:\n                wrapped = None\n            if isinstance(wrapped, nw.DataFrame):\n                print_ = fingerprint(value, wrapped, shape)\n                if known.get(name) == print_:\n                    return {\"name\": name, \"unchanged\": True, \"fingerprint\": print_}\n                entry = describe_frame(name, wrapped, value)\n                entry[\"fingerprint\"] = print_\n                return entry\n            if isinstance(wrapped, nw.Series):\n                entry = describe_series(name, wrapped, len(wrapped) <= detail_limit)\n                entry.update({\"name\": name, \"label\": name, \"type\": type_, \"rows\": len(wrapped)})\n                return entry\n        if hasattr(value, \"params\") and hasattr(value, \"conf_int\"):\n            return describe_model(name, value)\n        if isinstance(value, str) and secret_string(name, value):\n            return {\"name\": name, \"label\": name, \"kind\": \"constant\", \"type\": type_, \"secret\": True, \"length\": len(value)}\n        if isinstance(value, str):\n            is_scalar = len(value) <= 58\n        else:\n            is_scalar = isinstance(value, (bool, int, float, complex)) or shape == ()\n        if is_scalar:\n            text = repr(value)\n            if len(text) <= 60:\n                entry = {\"name\": name, \"label\": name, \"kind\": \"constant\", \"type\": type_, \"value\": text}\n                source = constant_source(name, value)\n                if source:\n                    entry[\"defined_in\"] = source\n                return entry\n        if isinstance(shape, tuple):\n            return {\n                \"name\": name,\n                \"label\": name,\n                \"kind\": \"array\",\n                \"type\": type_,\n                \"shape\": list(shape),\n                \"dtype\": str(getattr(value, \"dtype\", \"\")),\n            }\n        entry = {\"name\": name, \"label\": name, \"kind\": \"other\", \"type\": type_}\n        try:\n            entry[\"length\"] = len(value)\n        except Exception:\n            pass\n        return entry\n\n    shell = get_ipython()\n    hidden = set(getattr(shell, \"user_ns_hidden\", {}))\n    variables = []\n    # list() takes a snapshot: the main shell may add names while a subshell runs this.\n    for name, value in list(shell.user_ns.items()):\n        if name.startswith(\"_\") or name in hidden or isinstance(value, skipped_types):\n            continue\n        try:\n            variables.append(describe(name, value))\n        except Exception as error:\n            variables.append({\"name\": name, \"label\": name, \"kind\": \"other\", \"type\": type_name(value), \"error\": repr(error)})\n\n    packages = {}\n    for module, distribution in packages_to_report:\n        if module in sys.modules or importlib.util.find_spec(module) is not None:\n            try:\n                packages[module] = importlib.metadata.version(distribution)\n            except importlib.metadata.PackageNotFoundError:\n                packages[module] = None\n\n    display(\n        {\n            \"application/vnd.whybook.result+json\": {\n                \"variables\": variables,\n                \"packages\": packages,\n                \"python\": sys.version.split()[0],\n                \"cwd\": cwd,\n            }\n        },\n        raw=True,\n    )\n";

export const kernelFacts = "\"\"\"What a kernel has, for an agent that writes cells in it: the language's version, whether it reads parquet, and its packages.\n\nAn agent that answers in a second notebook (design iteration 1.69) reads this\nwhen the notebook opens, so that it writes code with the packages there are\nand says which are missing. It installs nothing.\n\nThe frontend bundle holds the text of this file and runs it in the kernel, so\nit must not import the whybook package.\n\"\"\"\n\n\ndef _whybook_kernel_facts(args):\n    import importlib.metadata\n    import importlib.util\n    import sys\n\n    from IPython.display import display\n\n    # The packages of an analysis, by the name that imports them.\n    modules = [\n        \"pandas\",\n        \"numpy\",\n        \"scipy\",\n        \"statsmodels\",\n        \"sklearn\",\n        \"polars\",\n        \"pyarrow\",\n        \"fastparquet\",\n        \"patsy\",\n        \"matplotlib\",\n        \"seaborn\",\n        \"plotnine\",\n        \"lifelines\",\n        \"linearmodels\",\n        \"pingouin\",\n        \"pymc\",\n    ]\n    distributions = {\"sklearn\": \"scikit-learn\"}\n    packages = {}\n    for module in modules:\n        if module in sys.modules or importlib.util.find_spec(module) is not None:\n            try:\n                packages[module] = importlib.metadata.version(distributions.get(module, module))\n            except importlib.metadata.PackageNotFoundError:\n                packages[module] = None\n    # pandas reads parquet through pyarrow or fastparquet; polars reads it itself.\n    parquet = any(module in packages for module in (\"pyarrow\", \"fastparquet\", \"polars\"))\n    display(\n        {\n            \"application/vnd.whybook.result+json\": {\n                \"language\": f\"Python {sys.version.split()[0]}\",\n                \"parquet\": parquet,\n                \"packages\": packages,\n            }\n        },\n        raw=True,\n    )\n";

export const plotHooks = "\"\"\"Hooks that add what the view needs to the outputs of plotting libraries.\n\nThe view runs this in each Python kernel before it runs a cell there, and again\nafter a restart. A second run changes nothing: the hooks keep their state on the\nshell, away from the user's namespace. ``{\"uninstall\": true}`` removes them all.\n\nEach library has one hook, and each hook registers inside its own try/except. A\nhook that cannot register (the library is too old, or another hook already holds\nthe place this one needs) is skipped, and the library's outputs stay as the\nlibrary ships them. A hook that raises while an output is displayed removes\nitself for that library and adds nothing to that output, so IPython shows the\noutput as the library ships it. Neither case prints anything in the cell.\n\nmatplotlib: the display bundle of a figure drawn as a PNG gets one more entry,\n``application/vnd.whybook.axes+json``. For each Axes it gives the box of the Axes in\nthe PNG (in the PNG's pixels, from the top left), the limits and scales of its\naxes, their labels, and the columns and the frame that the labels name when a\ncheap check tells. The box is read during the draw that makes the PNG, so it\nfollows ``bbox_inches=\"tight\"`` and its pad, the dpi and the retina factor, and\nthe figure is not drawn once more. pandas' ``.plot`` and seaborn draw on Axes,\nso their figures get the same entry.\n\npandas: ``DataFrame.plot`` notes on each Axes it returns the frame it plotted\nand the columns it put on x and y, so that the matplotlib hook names the frame.\n\nninejs: a chart that ``ninejs.interactive`` makes gets the same entry as a\nmatplotlib figure, for the figure it drew as SVG, in the SVG's points: its\nAxes and their limits, and the frame and the two columns whose values are the\npoints it draws, in order, when exactly one frame of the namespace has them.\nThe printer is registered by the name of the chart's class, so it applies from\nthe first chart, also in the cell that imports ninejs. A chart the reader can\nzoom (``zoomable=True``) gets none, since a box on it would no longer map to\nthe figure.\n\nPlotly Express: each figure it makes gets ``layout.meta[\"whybook\"]``, with the name\nof the frame it plotted and the columns on x, y and colour, which the view\nreads in place of the axis titles. The hooks of pandas and Plotly Express wait\nfor their library: they register after the first cell that imports it.\n\nThe view's own requests: the view sends this program and its other programs,\nsuch as the listing of the variables and the analysis of the cells, as silent\nrequests to a subshell, which runs them in a thread of its own while a cell\nmay run in the main shell. IPython calls the pre_execute and post_execute\ncallbacks of every request, silent ones too, in the thread that runs it.\nmatplotlib's inline backend flushes its figures in a post_execute callback: it\nshows every figure that pyplot holds open, in the output of that request, and\ncloses them all. A request of the view that ended while a cell drew in the\nmain shell showed that cell's figure in the view's request, which the view\ndoes not show, and closed it: the cell ended with no figure. So the\npre_execute and post_execute callbacks do not run for a silent request in a\nsubshell. This stays when a hook removes itself, and goes with\n``{\"uninstall\": true}``.\n\nThe frontend bundle holds the text of this file and runs it in the kernel, so it\nmust not import the whybook package.\n\"\"\"\n\n\ndef _whybook_plot_hooks(args):\n    import math\n    import re\n    import sys\n    import threading\n    import weakref\n\n    from IPython import get_ipython\n    from IPython.display import display\n\n    result_mime = \"application/vnd.whybook.result+json\"\n    axes_mime = \"application/vnd.whybook.axes+json\"\n    # Version 2 runs no pre_execute and post_execute callbacks for the view's\n    # requests: a kernel that has version 1 gets the hooks again.\n    version = 2\n\n    shell = get_ipython()\n    state = getattr(shell, \"_whybook_plot_hooks\", None)\n\n    def report(hooks):\n        return {\"version\": version, \"hooks\": {name: {\"state\": hook[\"state\"], \"reason\": hook[\"reason\"]} for name, hook in hooks.items()}}\n\n    if state is not None and (args.get(\"uninstall\") or state[\"version\"] != version):\n        # An older version of the hooks, or a request to remove them.\n        for hook in state[\"hooks\"].values():\n            if hook[\"remove\"] is not None:\n                try:\n                    hook[\"remove\"]()\n                except Exception:\n                    pass\n        if state.get(\"quiet\") is not None:\n            try:\n                state[\"quiet\"]()\n            except Exception:\n                pass\n        try:\n            shell.events.unregister(\"post_run_cell\", state[\"pending\"])\n        except ValueError:\n            pass\n        del shell._whybook_plot_hooks\n        state = None\n    if args.get(\"uninstall\"):\n        display({result_mime: report({})}, raw=True)\n        return\n    if state is not None:\n        state[\"pending\"]()\n        display({result_mime: report(state[\"hooks\"])}, raw=True)\n        return\n\n    # Axes that pandas plotted, with the frame and the columns: the pandas hook\n    # writes them, and the matplotlib hook reads them.\n    notes = weakref.WeakKeyDictionary()\n    state = {\"version\": version, \"hooks\": {}, \"notes\": notes, \"pending\": None, \"quiet\": None}\n    # Cells in subshells run in threads of their own, and each runs the hooks\n    # of newly imported libraries after it.\n    lock = threading.Lock()\n\n    def describe_error(error):\n        return f\"{type(error).__name__}: {error}\"\n\n    def fail(name, error):\n        \"\"\"Remove the hook of a library after it raised while an output was displayed.\"\"\"\n        hook = state[\"hooks\"].get(name)\n        if hook is None or hook[\"state\"] != \"on\":\n            return\n        hook[\"state\"] = \"failed\"\n        hook[\"reason\"] = describe_error(error)\n        remove, hook[\"remove\"] = hook[\"remove\"], None\n        try:\n            remove()\n        except Exception:\n            pass\n\n    def register(name, install):\n        \"\"\"Register one library's hook; a hook that raises is skipped and leaves nothing behind.\"\"\"\n        with lock:\n            hook = state[\"hooks\"].setdefault(name, {\"state\": \"waiting\", \"reason\": None, \"remove\": None})\n            if hook[\"state\"] != \"waiting\":\n                return\n            try:\n                remove = install()\n            except Exception as error:\n                hook[\"state\"] = \"skipped\"\n                hook[\"reason\"] = describe_error(error)\n                return\n            if remove is not None:\n                hook[\"state\"] = \"on\"\n                hook[\"remove\"] = remove\n\n    # The view's own requests.\n\n    def quiet_request():\n        \"\"\"Whether this thread runs a silent request in a subshell, as the view's programs are.\"\"\"\n        try:\n            parent = shell.get_parent()\n            header = parent.get(\"header\") or {}\n            content = parent.get(\"content\") or {}\n        except Exception:\n            # A shell outside a kernel has no request.\n            return False\n        return header.get(\"msg_type\") == \"execute_request\" and bool(header.get(\"subshell_id\")) and bool(content.get(\"silent\"))\n\n    def keep_quiet():\n        \"\"\"Run no pre_execute and post_execute callbacks for a silent request in a subshell.\n\n        A subshell runs its requests in a thread of its own, while a cell may\n        run in the main shell, and the callbacks work on the whole kernel:\n        matplotlib's inline backend shows and closes every open figure.\n        \"\"\"\n        events = shell.events\n        own = \"trigger\" in vars(events)\n        shipped = events.trigger\n\n        def trigger(event, *args, **kwargs):\n            if event in (\"pre_execute\", \"post_execute\") and quiet_request():\n                return None\n            return shipped(event, *args, **kwargs)\n\n        events.trigger = trigger\n\n        def remove():\n            if vars(events).get(\"trigger\") is trigger:\n                if own:\n                    events.trigger = shipped\n                else:\n                    del events.trigger\n\n        return remove\n\n    # What the hooks share: the frames of the user's namespace, found cheaply.\n\n    def name_of(value):\n        for name, candidate in list(shell.user_ns.items()):\n            if candidate is value and not name.startswith(\"_\"):\n                return name\n        return None\n\n    def frames_in_namespace():\n        pandas = sys.modules.get(\"pandas\")\n        if pandas is None:\n            return []\n        frame_type = pandas.DataFrame\n        return [(name, value) for name, value in list(shell.user_ns.items()) if not name.startswith(\"_\") and isinstance(value, frame_type)]\n\n    def is_column(frame, label):\n        if not isinstance(label, str) or not label:\n            return False\n        try:\n            return bool(label in frame.columns)\n        except Exception:\n            return False\n\n    # matplotlib.\n\n    def check_matplotlib():\n        import matplotlib\n        from matplotlib.backend_bases import FigureCanvasBase\n        from matplotlib.figure import Figure\n\n        release = tuple(int(part) for part in re.findall(r\"\\d+\", str(matplotlib.__version__))[:2])\n        if release < (3, 6):\n            raise RuntimeError(f\"matplotlib {matplotlib.__version__} is older than 3.6\")\n        if not isinstance(vars(FigureCanvasBase).get(\"callbacks\"), property):\n            # Callbacks kept on each canvas do not reach the canvas that saves the PNG.\n            raise RuntimeError(\"the canvas of this matplotlib keeps its own callbacks\")\n        if hasattr(Figure, \"_repr_mimebundle_\"):\n            # The hook's printer would take the place of the figure's own.\n            raise RuntimeError(\"matplotlib figures have a _repr_mimebundle_ of their own\")\n\n    def figure_printer(bundles):\n        \"\"\"The mime-bundle printer registered for matplotlib figures, if any.\"\"\"\n        printer = bundles.deferred_printers.get((\"matplotlib.figure\", \"Figure\"))\n        if printer is not None:\n            return printer\n        for cls, printer in list(bundles.type_printers.items()):\n            if (getattr(cls, \"__module__\", None), getattr(cls, \"__name__\", None)) == (\"matplotlib.figure\", \"Figure\"):\n                return printer\n        return None\n\n    def count_marks(ax):\n        \"\"\"The points a scatter draws, or else the points of its lines.\"\"\"\n        count = 0\n        for collection in ax.collections:\n            if type(collection).__name__ == \"PathCollection\":\n                count += len(collection.get_offsets())\n        if not count:\n            for line in ax.lines:\n                count += len(line.get_xdata())\n        return count or None\n\n    def columns_of(ax, xlabel, ylabel, marks, frames):\n        \"\"\"The frame and the columns on x and y: from the pandas note, or else from the labels.\"\"\"\n        note = notes.get(ax)\n        if note is not None:\n            frame = note[\"frame\"]()\n            name = name_of(frame) if frame is not None else None\n            if name is not None:\n                if note[\"kind\"] in (\"bar\", \"barh\", \"box\", \"pie\"):\n                    # Bars and boxes stand at positions, not at values of a column.\n                    return name, None, None\n                along = note[\"kind\"] in (\"line\", \"scatter\", \"area\")\n\n                def pick(preferred, label):\n                    if along and is_column(frame, preferred):\n                        return preferred\n                    return label if is_column(frame, label) else None\n\n                return name, pick(note[\"x\"], xlabel), pick(note[\"y\"], ylabel)\n        having_x = [(name, frame) for name, frame in frames if is_column(frame, xlabel)]\n        if not having_x:\n            return None, None, None\n        having_both = [(name, frame) for name, frame in having_x if is_column(frame, ylabel)]\n        candidates = having_both or having_x\n        if len(candidates) == 1:\n            frame = candidates[0][0]\n        else:\n            # Several frames have the columns: the one with a row per mark, if only one has.\n            same = [name for name, value in candidates if marks is not None and len(value) == marks]\n            frame = same[0] if len(same) == 1 else None\n        return frame, xlabel, ylabel if having_both else None\n\n    def kind_of(ax):\n        \"\"\"What the Axes draws: the kind of a pandas plot, or else scatter, bar or line.\"\"\"\n        note = notes.get(ax)\n        if note is not None and note.get(\"kind\"):\n            return note[\"kind\"]\n        if any(type(collection).__name__ == \"PathCollection\" for collection in ax.collections):\n            return \"scatter\"\n        if ax.patches and all(type(patch).__name__ == \"Rectangle\" for patch in ax.patches):\n            return \"bar\"\n        if ax.lines:\n            return \"line\"\n        return None\n\n    def describe_axes(ax, box, frames):\n        \"\"\"One Axes of the figure, or None when a range of its pixels is not a range of values.\"\"\"\n        if getattr(ax, \"name\", None) != \"rectilinear\" or not ax.get_visible() or hasattr(ax, \"_colorbar\"):\n            return None\n        scales = (ax.get_xscale(), ax.get_yscale())\n        if any(scale not in (\"linear\", \"log\") for scale in scales):\n            return None\n        if ax.xaxis.have_units() or ax.yaxis.have_units():\n            # Dates or categories.\n            return None\n        xlim, ylim = ax.get_xlim(), ax.get_ylim()\n        if not all(math.isfinite(value) for value in (*xlim, *ylim)):\n            return None\n        xlabel, ylabel = str(ax.get_xlabel()), str(ax.get_ylabel())\n        marks = count_marks(ax)\n        frame, xcolumn, ycolumn = columns_of(ax, xlabel, ylabel, marks, frames)\n        return {\n            \"box\": [round(float(value), 2) for value in box],\n            \"x\": {\"limits\": [float(xlim[0]), float(xlim[1])], \"scale\": scales[0], \"label\": xlabel, \"column\": xcolumn},\n            \"y\": {\"limits\": [float(ylim[0]), float(ylim[1])], \"scale\": scales[1], \"label\": ylabel, \"column\": ycolumn},\n            \"title\": str(ax.get_title()),\n            \"frame\": frame,\n            \"marks\": marks,\n            \"kind\": kind_of(ax),\n        }\n\n    def install_matplotlib():\n        from IPython.core.formatters import BaseFormatter\n        from traitlets import ObjectName, Unicode\n\n        formatter = shell.display_formatter\n        bundles = formatter.mimebundle_formatter\n        if axes_mime in formatter.formatters:\n            raise RuntimeError(f\"another hook already adds {axes_mime}\")\n        if figure_printer(bundles) is not None:\n            raise RuntimeError(\"another printer is registered for matplotlib figures\")\n        checked = []\n        if \"matplotlib.figure\" in sys.modules:\n            check_matplotlib()\n            checked.append(True)\n        # Per figure being displayed, and per thread that displays it: the draw\n        # it was last drawn with. A cell in a subshell and one in the main shell\n        # can show one figure at the same time, each drawing its own PNG.\n        captures = weakref.WeakKeyDictionary()\n\n        def on_draw(event, capture, raster):\n            # A draw callback that raised would stop the PNG, so it keeps the error.\n            try:\n                if threading.get_ident() != capture[\"thread\"]:\n                    # Another thread draws the figure for an output of its own.\n                    return\n                renderer = event.renderer\n                if not isinstance(renderer, raster):\n                    return\n                height = int(renderer.height)\n                boxes = []\n                for ax in event.canvas.figure.axes:\n                    left, bottom, right, top = ax.bbox.extents\n                    boxes.append((ax, (left, height - top, right, height - bottom)))\n                # A tight box draws twice, and the last draw is the one saved.\n                capture[\"draw\"] = {\"width\": int(renderer.width), \"height\": height, \"dpi\": float(renderer.dpi), \"boxes\": boxes}\n            except Exception as error:\n                capture[\"error\"] = error\n\n        def before(figure):\n            # IPython calls mime-bundle printers first, then the PNG formatter:\n            # the callback sees the draw that makes the PNG.\n            try:\n                if not checked:\n                    check_matplotlib()\n                    checked.append(True)\n                from matplotlib.backends.backend_agg import RendererAgg\n\n                thread = threading.get_ident()\n                mine = captures.setdefault(figure, {})\n                old = mine.pop(thread, None)\n                if old is not None:\n                    figure.canvas.mpl_disconnect(old[\"cid\"])\n                capture = {\"dpi\": float(figure.dpi), \"draw\": None, \"error\": None, \"cid\": None, \"thread\": thread}\n                capture[\"cid\"] = figure.canvas.mpl_connect(\"draw_event\", lambda event: on_draw(event, capture, RendererAgg))\n                mine[thread] = capture\n            except Exception as error:\n                fail(\"matplotlib\", error)\n            return None\n\n        def after(obj):\n            # Called for every object displayed, so anything but a figure goes quickly.\n            figure_module = sys.modules.get(\"matplotlib.figure\")\n            try:\n                if figure_module is None or not isinstance(obj, figure_module.Figure):\n                    return None\n            except Exception:\n                return None\n            mine = captures.get(obj)\n            capture = mine.pop(threading.get_ident(), None) if mine is not None else None\n            if capture is None:\n                return None\n            try:\n                obj.canvas.mpl_disconnect(capture[\"cid\"])\n                if capture[\"error\"] is not None:\n                    raise capture[\"error\"]\n                draw = capture[\"draw\"]\n                if draw is None:\n                    # No PNG or JPEG was drawn: an SVG or PDF figure.\n                    return None\n                frames = frames_in_namespace()\n                axes = [entry for entry in (describe_axes(ax, box, frames) for ax, box in draw[\"boxes\"]) if entry is not None]\n                if not axes:\n                    return None\n                return {\n                    \"version\": 1,\n                    \"library\": \"matplotlib\",\n                    \"image\": {\"width\": draw[\"width\"], \"height\": draw[\"height\"], \"scale\": round(draw[\"dpi\"] / capture[\"dpi\"], 3)},\n                    \"axes\": axes,\n                }\n            except Exception as error:\n                fail(\"matplotlib\", error)\n                return None\n\n        class AxesFormatter(BaseFormatter):\n            \"\"\"The geometry of a figure's Axes, after its PNG was drawn.\"\"\"\n\n            format_type = Unicode(axes_mime)\n            print_method = ObjectName(\"_repr_whybook_axes_\")\n\n            def __call__(self, obj):\n                return after(obj) if self.enabled else None\n\n        added = AxesFormatter(parent=formatter)\n        bundles.for_type_by_name(\"matplotlib.figure\", \"Figure\", before)\n        # IPython loops over this dict while it formats an object, maybe in\n        # another thread: a new dict takes its place, and the loop goes on\n        # over the old one. A key added or deleted in place would stop it.\n        try:\n            formatter.formatters = {**formatter.formatters, axes_mime: added}\n        except Exception:\n            bundles.pop(\"matplotlib.figure.Figure\", None)\n            raise\n\n        def remove():\n            kept = list(formatter.formatters.items())\n            if any(value is added for _, value in kept):\n                formatter.formatters = {key: value for key, value in kept if value is not added}\n            if figure_printer(bundles) is before:\n                bundles.pop(\"matplotlib.figure.Figure\", None)\n            try:\n                for figure, mine in list(captures.items()):\n                    for capture in list(mine.values()):\n                        figure.canvas.mpl_disconnect(capture[\"cid\"])\n            except Exception:\n                pass\n            captures.clear()\n\n        return remove\n\n    # pandas.\n\n    def note_plot(accessor, args, kwargs, result):\n        frame = accessor._parent\n        if not isinstance(frame, sys.modules[\"pandas\"].DataFrame):\n            return\n        # DataFrame.plot takes x, y and kind in this order.\n        x = kwargs.get(\"x\", args[0] if len(args) > 0 else None)\n        y = kwargs.get(\"y\", args[1] if len(args) > 1 else None)\n        kind = kwargs.get(\"kind\", args[2] if len(args) > 2 else \"line\")\n        if hasattr(result, \"get_xlim\"):\n            axes = [result]\n        elif hasattr(result, \"flat\"):\n            axes = list(result.flat)\n        else:\n            axes = list(result) if isinstance(result, (list, tuple)) else []\n        reference = weakref.ref(frame)\n        for ax in axes:\n            if hasattr(ax, \"get_xlim\"):\n                notes[ax] = {\n                    \"frame\": reference,\n                    \"x\": x if isinstance(x, str) else None,\n                    \"y\": y if isinstance(y, str) else None,\n                    \"kind\": kind if isinstance(kind, str) else None,\n                }\n\n    def install_pandas():\n        core = sys.modules.get(\"pandas.plotting._core\")\n        if core is None:\n            # pandas is not imported yet: the hook registers after a later cell.\n            return None\n        import functools\n\n        accessor = core.PlotAccessor\n        original = vars(accessor).get(\"__call__\")\n        if not callable(original):\n            raise RuntimeError(\"pandas' plot accessor has no __call__ of its own\")\n        if getattr(original, \"_whybook_plot_hooks\", False):\n            raise RuntimeError(\"pandas' plot accessor is already wrapped\")\n\n        @functools.wraps(original)\n        def plot(self, *args, **kwargs):\n            result = original(self, *args, **kwargs)\n            try:\n                note_plot(self, args, kwargs, result)\n            except Exception as error:\n                fail(\"pandas\", error)\n            return result\n\n        plot._whybook_plot_hooks = True\n        accessor.__call__ = plot\n\n        def remove():\n            if vars(accessor).get(\"__call__\") is plot:\n                accessor.__call__ = original\n            notes.clear()\n\n        return remove\n\n    # Plotly Express.\n\n    def plotly_note(args):\n        \"\"\"The frame and the columns of a Plotly Express call, before Plotly builds a frame of its own.\"\"\"\n        pandas = sys.modules.get(\"pandas\")\n        frame = args.get(\"data_frame\") if isinstance(args, dict) else None\n        if pandas is None or not isinstance(frame, pandas.DataFrame):\n            return None\n        note = {channel: args[channel] for channel in (\"x\", \"y\", \"color\") if is_column(frame, args.get(channel))}\n        name = name_of(frame)\n        if name is not None:\n            note[\"frame\"] = name\n        return note or None\n\n    def install_plotly():\n        chart_types = sys.modules.get(\"plotly.express._chart_types\")\n        if chart_types is None:\n            # Plotly Express is not imported yet: the hook registers after a later cell.\n            return None\n        import functools\n        import inspect\n\n        original = vars(chart_types).get(\"make_figure\")\n        if not callable(original):\n            raise RuntimeError(\"plotly.express has no make_figure\")\n        if getattr(original, \"_whybook_plot_hooks\", False):\n            raise RuntimeError(\"plotly.express is already wrapped\")\n        taken = inspect.signature(original).parameters.get(\"args\")\n        if taken is None or taken.kind not in (taken.POSITIONAL_OR_KEYWORD, taken.KEYWORD_ONLY):\n            raise RuntimeError(\"plotly.express's make_figure takes no args\")\n\n        @functools.wraps(original)\n        def make_figure(*positional, **keywords):\n            note = None\n            try:\n                note = plotly_note(keywords[\"args\"] if \"args\" in keywords else positional[0])\n            except Exception as error:\n                fail(\"plotly\", error)\n            figure = original(*positional, **keywords)\n            if note is not None:\n                try:\n                    meta = figure.layout.meta\n                    if meta is None or isinstance(meta, dict):\n                        # One assignment: a value Plotly refuses leaves the figure as it was.\n                        figure.layout.meta = {**(meta or {}), \"whybook\": note}\n                except Exception as error:\n                    fail(\"plotly\", error)\n            return figure\n\n        make_figure._whybook_plot_hooks = True\n        chart_types.make_figure = make_figure\n\n        def remove():\n            if vars(chart_types).get(\"make_figure\") is make_figure:\n                chart_types.make_figure = original\n\n        return remove\n\n    # ninejs.\n\n    def plotted_frame(ax, frames):\n        \"\"\"The one frame and the two columns whose rows are the points of an Axes, in their order, or None.\"\"\"\n        numpy = sys.modules.get(\"numpy\")\n        offsets = next((collection.get_offsets() for collection in ax.collections if type(collection).__name__ == \"PathCollection\"), None)\n        if numpy is None or offsets is None or not len(offsets):\n            return None\n        points = numpy.asarray(offsets, dtype=float)\n        found = []\n        for name, frame in frames:\n            if len(frame) != len(points):\n                continue\n            numeric = [column for column in list(frame.columns)[:200] if isinstance(column, str) and frame[column].dtype.kind in \"iuf\"]\n\n            def same(column, along):\n                return bool(numpy.allclose(frame[column].to_numpy(dtype=float), points[:, along], equal_nan=True))\n\n            xs = [column for column in numeric if same(column, 0)]\n            ys = [column for column in numeric if same(column, 1)] if xs else []\n            found.extend((frame, x, y) for x in xs for y in ys)\n            if len(found) > 1:\n                # Two frames, or two columns, with the same values: the view cannot tell which.\n                return None\n        return found[0] if found else None\n\n    def ninejs_payload(chart):\n        \"\"\"The Axes of a ninejs chart in the units of its SVG, or None when a box on the chart cannot map to them.\"\"\"\n        plot = getattr(chart, \"plot\", None)\n        figure = getattr(chart, \"fig\", None)\n        if plot is None or figure is None or not hasattr(figure, \"get_figwidth\"):\n            raise RuntimeError(\"this ninejs keeps no plot or figure on its charts\")\n        if getattr(plot, \"zoomable\", False):\n            # The reader can zoom and pan the chart: a box would no longer map to the figure.\n            return None\n        # matplotlib writes an SVG in points, 72 to the inch.\n        width = float(figure.get_figwidth()) * 72\n        height = float(figure.get_figheight()) * 72\n        frames = frames_in_namespace()\n        axes = []\n        for ax in figure.axes:\n            if ax not in notes:\n                # plotnine keeps no link from its figure to its data: the points name the frame.\n                match = plotted_frame(ax, frames)\n                if match is not None:\n                    frame, x, y = match\n                    notes[ax] = {\"frame\": weakref.ref(frame), \"x\": x, \"y\": y, \"kind\": \"scatter\"}\n            left, bottom, right, top = ax.get_position().extents\n            box = (left * width, (1 - top) * height, right * width, (1 - bottom) * height)\n            entry = describe_axes(ax, box, frames)\n            if entry is not None:\n                axes.append(entry)\n        if not axes:\n            return None\n        return {\"version\": 1, \"library\": \"ninejs\", \"image\": {\"width\": round(width, 3), \"height\": round(height, 3), \"scale\": 1}, \"axes\": axes}\n\n    def ninejs_printer(bundles):\n        \"\"\"The mime-bundle printer registered for ninejs charts, if any.\"\"\"\n        printer = bundles.deferred_printers.get((\"ninejs.main\", \"interactive\"))\n        if printer is not None:\n            return printer\n        for cls, printer in list(bundles.type_printers.items()):\n            if (getattr(cls, \"__module__\", None), getattr(cls, \"__name__\", None)) == (\"ninejs.main\", \"interactive\"):\n                return printer\n        return None\n\n    def install_ninejs():\n        bundles = shell.display_formatter.mimebundle_formatter\n        if ninejs_printer(bundles) is not None:\n            raise RuntimeError(\"another printer is registered for ninejs charts\")\n\n        def bundle(chart):\n            # Only the Axes: IPython takes the HTML from the chart's own repr.\n            try:\n                payload = ninejs_payload(chart)\n            except Exception as error:\n                fail(\"ninejs\", error)\n                return None\n            return {axes_mime: payload} if payload else None\n\n        # By name: it applies from the first chart, also in the cell that imports ninejs.\n        bundles.for_type_by_name(\"ninejs.main\", \"interactive\", bundle)\n\n        def remove():\n            if bundles.deferred_printers.get((\"ninejs.main\", \"interactive\")) is bundle:\n                del bundles.deferred_printers[(\"ninejs.main\", \"interactive\")]\n            for cls, printer in list(bundles.type_printers.items()):\n                if printer is bundle:\n                    bundles.pop(cls, None)\n\n        return remove\n\n    installers = {\"matplotlib\": install_matplotlib, \"pandas\": install_pandas, \"plotly\": install_plotly, \"ninejs\": install_ninejs}\n\n    def pending(result=None):\n        # After each cell: the hooks of libraries imported since.\n        try:\n            for name, install in installers.items():\n                register(name, install)\n        except Exception:\n            pass\n\n    state[\"pending\"] = pending\n    try:\n        state[\"quiet\"] = keep_quiet()\n    except Exception:\n        pass\n    shell._whybook_plot_hooks = state\n    pending()\n    shell.events.register(\"post_run_cell\", pending)\n    display({result_mime: report(state[\"hooks\"])}, raw=True)\n";

export const regionSummary = "\"\"\"The rows behind a region of a whybook plot, and one line on what differs there.\n\nThe frontend bundle holds the text of this file and runs it in the kernel, so\nit must not import the whybook package.\n\"\"\"\n\n\ndef _whybook_region_summary(args):\n    from IPython import get_ipython\n    from IPython.display import display\n\n    ns = get_ipython().user_ns\n    frame = ns.get(args[\"frame\"])\n    if frame is None:\n        display({\"application/vnd.whybook.result+json\": {\"error\": f\"no variable named {args['frame']}\"}}, raw=True)\n        return\n    if not hasattr(frame, \"loc\"):\n        import narwhals as nw\n\n        frame = nw.from_native(frame, eager_only=True).to_pandas()\n    x, values = args[\"x\"], args.get(\"values\")\n    y, by, unit = args.get(\"y\"), args.get(\"by\"), args.get(\"unit\")\n\n    def between(column, low, high):\n        \"\"\"The rows of a column from low to high, and the range in words.\n\n        A plot sends a date as the milliseconds since 1970 of its time on the\n        frame's clock (whybook/plots.py): a column of dates, or of Python\n        dates, compares with those times in its own time zone.\n        \"\"\"\n        import datetime\n\n        import pandas as pd\n\n        series = frame[column]\n        if series.dtype == object:\n            present = series.dropna()\n            if len(present) and all(isinstance(item, datetime.date) for item in present.head(100)):\n                series = pd.to_datetime(series)\n        if pd.api.types.is_datetime64_any_dtype(series):\n            low, high = (pd.Timestamp(round(bound), unit=\"ms\") for bound in (low, high))\n            words = [str(stamp.date()) if stamp == stamp.normalize() else str(stamp) for stamp in (low, high)]\n            if series.dt.tz is not None:\n                low, high = (\n                    stamp.tz_localize(series.dt.tz, ambiguous=False, nonexistent=\"shift_forward\") for stamp in (low, high)\n                )\n        else:\n            words = [low, high]\n        return (series >= low) & (series <= high), f\"{words[0]} <= {column} <= {words[1]}\"\n\n    if values is not None:\n        # Bars: a bar is a level of x, and its label is the level as text.\n        wanted = [str(value) for value in values]\n        mask = frame[x].astype(str).isin(wanted)\n        where = f\"{x} = {wanted[0]}\" if len(wanted) == 1 else f\"{x} in {', '.join(wanted[:-1])} and {wanted[-1]}\"\n    else:\n        mask, where = between(x, args[\"x0\"], args[\"x1\"])\n        if args.get(\"y0\") is not None and y in frame.columns:\n            # A box on a chart of another library also bounds y.\n            inside_y, where_y = between(y, args[\"y0\"], args[\"y1\"])\n            mask &= inside_y\n            where += f\" and {where_y}\"\n    inside, outside = frame[mask], frame[~mask]\n    result = {\"rows\": int(len(inside)), \"total_rows\": int(len(frame)), \"where\": where}\n    if unit and unit in frame.columns:\n        result[\"unit\"] = unit\n        result[\"units\"] = int(inside[unit].nunique())\n    sentences = []\n    groups = []\n    if by and by in frame.columns and len(inside):\n        for level, part in inside.groupby(by, observed=True):\n            overall = float((frame[by] == level).mean())\n            entry = {\n                \"name\": str(level),\n                \"rows\": int(len(part)),\n                \"share\": round(len(part) / len(inside), 3),\n                \"share_overall\": round(overall, 3),\n            }\n            if y and y in frame.columns:\n                entry[\"mean\"] = round(float(part[y].mean()), 3)\n            groups.append(entry)\n        if y and len(groups) >= 2 and \"mean\" in groups[0]:\n            first, second = groups[0], groups[1]\n            inside_gap = first[\"mean\"] - second[\"mean\"]\n            outside_means = outside.groupby(by, observed=True)[y].mean()\n            if first[\"name\"] in outside_means.index.astype(str) and second[\"name\"] in outside_means.index.astype(str):\n                means = {str(k): float(v) for k, v in outside_means.items()}\n                outside_gap = means[first[\"name\"]] - means[second[\"name\"]]\n                if abs(inside_gap) > 1.5 * abs(outside_gap) and abs(inside_gap) > 0.2:\n                    sentences.append(\n                        f\"The groups diverge here: {first['name']} minus {second['name']} is {inside_gap:+.2f}, against {outside_gap:+.2f} elsewhere.\"\n                    )\n                else:\n                    sentences.append(f\"{first['name']} minus {second['name']} is {inside_gap:+.2f} here and {outside_gap:+.2f} elsewhere.\")\n        for entry in groups:\n            if entry[\"share_overall\"]:\n                change = entry[\"share\"] / entry[\"share_overall\"] - 1\n                if change < -0.08:\n                    sentences.append(f\"{by} {entry['name']} has {abs(change):.0%} fewer rows here than overall.\")\n    if values is not None and y and y in frame.columns and len(inside) and len(outside) and not groups:\n        try:\n            here, elsewhere = float(inside[y].mean()), float(outside[y].mean())\n        except (TypeError, ValueError):\n            pass\n        else:\n            rest = outside[x].astype(str).unique()\n            where_else = f\"in {x} {rest[0]}\" if len(rest) == 1 else \"in the other bars\"\n            sentences.append(f\"Mean {y} is {here:.3g} here and {elsewhere:.3g} {where_else}.\")\n    result[\"groups\"] = groups\n    found = f\"have {where}\" if values is not None else \"fall in this range\"\n    result[\"seen\"] = \" \".join(sentences[:2]) or f\"{len(inside)} of {len(frame)} rows {found}.\"\n    display({\"application/vnd.whybook.result+json\": result}, raw=True)\n";

export const tableRows = "\"\"\"The rows of a frame behind rows picked in a table, and what sets them apart.\n\nA pandas table labels its rows with the frame's index, or with the values of\nsome of its columns, as after a groupby or a set_index. The labels come as the\ntable writes them, as text, and each is read back as a value of its level: \"3\"\nis 3 in an integer index, \"0.500000\" is 0.5, \"2024-01-01\" is a date.\n\nA polars table writes no row labels. Its rows are found by their place in the\nframe, from 0 (``positions``), or by the values of key columns as the table\nwrites them: \"A\" in double quotes, null, true, 0.333333. That path uses\nnarwhals and needs neither pandas nor numpy, and its mask is polars code.\n\nThe frontend bundle holds the text of this file and runs it in the kernel, so\nit must not import the whybook package.\n\"\"\"\n\n\ndef _whybook_table_rows(args):\n    import math\n\n    from IPython import get_ipython\n    from IPython.display import display\n\n    def done(result):\n        display({\"application/vnd.whybook.result+json\": result}, raw=True)\n\n    name = args[\"frame\"]\n    namespace = get_ipython().user_ns\n    frame = namespace.get(name)\n    if frame is None:\n        done({\"error\": f\"no variable named {name}\", \"missing\": True})\n        return\n\n    def by_place_or_value():\n        \"\"\"Rows of a polars frame: by their place, or by the values of key columns.\"\"\"\n        import datetime\n\n        try:\n            import narwhals.stable.v2 as nw\n        except ImportError:\n            try:\n                import narwhals as nw\n            except ImportError:\n                done({\"error\": \"narwhals is not installed in the kernel\"})\n                return\n        try:\n            df = nw.from_native(frame, eager_only=True)\n        except TypeError:\n            done({\"error\": f\"{name} is not a data frame\"})\n            return\n        polars = df.implementation.is_polars()\n        schema = df.schema\n        keys = [str(key) for key in args.get(\"keys\") or []]\n        picks = [[str(label) for label in pick] for pick in args.get(\"labels\") or [] if pick]\n        unit = args.get(\"unit\")\n        # Without keys a row is its place: polars writes no row labels.\n        by_place = bool(args.get(\"positions\")) or not keys\n        if not by_place:\n            absent = [key for key in keys if key not in schema]\n            if absent:\n                done({\"error\": f\"{name} has no column {absent[0]}\"})\n                return\n        depth = 1 if by_place else len(keys)\n        if not picks or max(len(pick) for pick in picks) > depth:\n            done({\"error\": f\"the labels do not fit the rows of {name}\"})\n            return\n        height = len(df)\n        place = nw.generate_temporary_column_name(8, df.columns)\n        places = df.with_row_index(place).get_column(place)\n        nothing = places < 0\n\n        def unquoted(text):\n            \"\"\"A string as polars writes it: in double quotes, cut after 30 characters with an ellipsis.\"\"\"\n            if len(text) >= 2 and text[0] == '\"' and text[-1] == '\"':\n                return text[1:-1], False\n            if len(text) >= 2 and text[0] == '\"' and text[-1] == \"\\u2026\":\n                return text[1:-1], True\n            return text, False\n\n        def shown(text):\n            return unquoted(text)[0] + (\"\\u2026\" if unquoted(text)[1] else \"\")\n\n        def close(values, text):\n            \"\"\"Floats that polars writes as this text: 0.333333, 12.0, 1.0000e7.\"\"\"\n            target = float(text)\n            if math.isinf(target):\n                return (values == target).fill_null(False)\n            mantissa, _, exponent = text.lower().partition(\"e\")\n            decimals = len(mantissa.partition(\".\")[2])\n            tolerance = 0.5 * 10 ** (int(exponent or 0) - decimals)\n            return values.is_between(target - tolerance, target + tolerance).fill_null(False)\n\n        def matches(level, text):\n            \"\"\"The rows whose value at this level the table writes as this text; None when it is no value of the level.\"\"\"\n            if by_place:\n                try:\n                    return places == int(text.replace(\"_\", \"\"))\n                except ValueError:\n                    return None\n            return written_as(keys[level], text)\n\n        def written_as(column, text):\n            \"\"\"The rows whose value in this column polars writes as this text; None when the view cannot read it.\"\"\"\n            values = df.get_column(column)\n            dtype = schema[column]\n            if text == \"null\":\n                return values.is_null()\n            try:\n                if dtype.is_float() and text == \"NaN\":\n                    return values.is_nan().fill_null(False)\n                if dtype == nw.Boolean:\n                    if text.lower() not in (\"true\", \"false\"):\n                        return None\n                    return (values == (text.lower() == \"true\")).fill_null(False)\n                if dtype.is_integer():\n                    return (values == int(text.replace(\"_\", \"\"))).fill_null(False)\n                if dtype.is_float():\n                    return close(values, text)\n                if isinstance(dtype, nw.Datetime):\n                    stamp = text\n                    if dtype.time_zone is not None:\n                        # polars writes the zone's abbreviation after the time: 2024-01-02 00:00:00 CET.\n                        stamp = \" \".join(text.split(\" \")[:2])\n                        values = values.dt.replace_time_zone(None)\n                    return (values == datetime.datetime.fromisoformat(stamp)).fill_null(False)\n                if isinstance(dtype, nw.Date):\n                    return (values == datetime.date.fromisoformat(text)).fill_null(False)\n                if isinstance(dtype, (nw.String, nw.Categorical, nw.Enum)):\n                    value, cut = unquoted(text)\n                    strings = values.cast(nw.String)\n                    if cut:\n                        return strings.str.starts_with(value).fill_null(False)\n                    return (strings == value).fill_null(False)\n                return (values.cast(nw.String) == text).fill_null(False)\n            except Exception:\n                return None\n\n        # A row found by its place must still hold what the table shows: a\n        # later cell can sort or change the frame since the table was drawn.\n        if by_place:\n            for pick, cells in zip(picks, args.get(\"cells\") or []):\n                try:\n                    at = int(pick[0].replace(\"_\", \"\"))\n                except ValueError:\n                    continue\n                if not 0 <= at < height:\n                    continue\n                for column, text in (cells or {}).items():\n                    dtype = schema.get(column)\n                    # Only the types the view reads back exactly.\n                    exact = dtype is not None and (\n                        dtype.is_integer()\n                        or dtype.is_float()\n                        or dtype == nw.Boolean\n                        or isinstance(dtype, (nw.String, nw.Categorical, nw.Enum, nw.Date, nw.Datetime))\n                    )\n                    if not exact:\n                        continue\n                    rows = written_as(column, text)\n                    if rows is not None and not rows[at]:\n                        done({\"error\": f\"{name} changed after the table was shown: its row {at} does not hold what the table shows. Run the cell again to ask about these rows.\"})\n                        return\n\n        # A pick has a label for each level, down to the level clicked. A label\n        # must read as one value of its level: a string cut short, or a float\n        # rounded, that fits two values says so rather than mixing their rows.\n        picked = []\n        for pick in picks:\n            rows = ~nothing\n            for level, text in enumerate(pick):\n                found = matches(level, text)\n                if found is None:\n                    found = nothing\n                elif not by_place and found.any():\n                    kept = df.get_column(keys[level]).filter(found)\n                    if kept.n_unique() > 1:\n                        done({\"error\": f\"more than one value of {keys[level]} in {name} reads as {shown(text)}: the table shows it cut or rounded\"})\n                        return\n                rows = rows & found\n            picked.append(rows)\n        mask = picked[0]\n        for rows in picked[1:]:\n            mask = mask | rows\n        single = all(len(pick) == 1 for pick in picks)\n\n        def listed(texts):\n            return texts[0] if len(texts) == 1 else f\"{', '.join(texts[:-1])} and {texts[-1]}\"\n\n        def literal(value, zone=None):\n            \"\"\"The value as polars code, or None when a literal cannot write it.\"\"\"\n            if isinstance(value, (bool, int)):\n                return repr(value)\n            if isinstance(value, float):\n                if math.isnan(value):\n                    return None\n                return repr(value) if math.isfinite(value) else f\"float({str(value)!r})\"\n            if isinstance(value, str):\n                return repr(value)\n            if isinstance(value, datetime.datetime):\n                # The time as the zone of the column reads it, as polars gives it back.\n                parts = [value.year, value.month, value.day, value.hour, value.minute, value.second, value.microsecond]\n                while len(parts) > 3 and not parts[-1]:\n                    parts.pop()\n                written = \", \".join(map(str, parts))\n                if value.tzinfo is None:\n                    return f\"pl.datetime({written})\"\n                return f\"pl.datetime({written}, time_zone={zone!r})\" if zone else None\n            if isinstance(value, datetime.date):\n                return f\"pl.date({value.year}, {value.month}, {value.day})\"\n            return None\n\n        def condition(level, texts, rows):\n            \"\"\"polars code for the rows whose value at this level is one of these texts.\"\"\"\n            if by_place:\n                return f\"pl.int_range(pl.len()).is_in([{', '.join(str(int(text.replace('_', ''))) for text in texts)}])\"\n            key = keys[level]\n            column = f\"pl.col({key!r})\"\n            values = df.get_column(key).filter(rows)\n            dtype = schema[key]\n            nulls = bool(values.is_null().any())\n            nans = dtype.is_float() and bool(values.is_nan().fill_null(False).any())\n            found = [value for value in values.drop_nulls().unique(maintain_order=True).to_list() if not (isinstance(value, float) and math.isnan(value))]\n            written = [literal(value, getattr(dtype, \"time_zone\", None)) for value in found]\n            tests = []\n            if found:\n                if not all(written):\n                    return None\n                tests.append(f\"{column} == {written[0]}\" if len(written) == 1 else f\"{column}.is_in([{', '.join(written)}])\")\n            if nulls:\n                tests.append(f\"{column}.is_null()\")\n            if nans:\n                tests.append(f\"{column}.is_nan()\")\n            if not tests:\n                return None\n            return tests[0] if len(tests) == 1 else \" | \".join(f\"({test})\" for test in tests)\n\n        mask_code = None\n        if polars:\n            if single:\n                texts = list(dict.fromkeys(pick[0] for pick in picks))\n                mask_code = condition(0, texts, mask)\n            else:\n                tests = []\n                for pick, rows in zip(picks, picked):\n                    parts = [condition(level, [text], rows) for level, text in enumerate(pick)]\n                    if not all(parts):\n                        tests = None\n                        break\n                    tests.append(\" & \".join(f\"({part})\" for part in parts) if len(parts) > 1 else parts[0])\n                if tests:\n                    mask_code = \" | \".join(f\"({test})\" for test in tests) if len(tests) > 1 else tests[0]\n            if mask_code is not None:\n                try:\n                    # The code must pick the same rows, or the questions offer none.\n                    import polars as pl\n\n                    native = nw.to_native(df)\n                    got = native.select(eval(mask_code, {\"pl\": pl}).alias(place)).to_series().fill_null(False)\n                    same = len(got) == height and bool((got == nw.to_native(mask)).all())\n                except Exception:\n                    same = False\n                if not same:\n                    mask_code = None\n\n        if by_place:\n            numbers_shown = list(dict.fromkeys(str(int(pick[0].replace(\"_\", \"\"))) if pick[0].replace(\"_\", \"\").isdigit() else pick[0] for pick in picks))\n            shortened = numbers_shown if len(numbers_shown) <= 4 else numbers_shown[:3] + [f\"{len(numbers_shown) - 3} more\"]\n            where = f\"row {numbers_shown[0]}\" if len(numbers_shown) == 1 else f\"rows {listed(shortened)}\"\n        elif single:\n            texts = [shown(text) for text in dict.fromkeys(pick[0] for pick in picks)]\n            shortened = texts if len(texts) <= 4 else texts[:3] + [f\"{len(texts) - 3} more\"]\n            where = f\"{keys[0]} = {texts[0]}\" if len(texts) == 1 else f\"{keys[0]} in {listed(shortened)}\"\n        elif len(picks) == 1:\n            where = \" and \".join(f\"{keys[level]} = {shown(text)}\" for level, text in enumerate(picks[0]))\n        else:\n            depth = max(len(pick) for pick in picks)\n            where = f\"{len(picks)} labels of {listed(keys[:depth])}\"\n\n        count = int(mask.sum())\n        others = height - count\n        result = {\n            \"rows\": count,\n            \"total_rows\": height,\n            \"where\": where,\n            \"mask\": mask_code,\n            \"positions\": by_place,\n            \"library\": \"polars\" if polars else str(df.implementation),\n        }\n        if unit and unit in schema:\n            result[\"unit\"] = unit\n            result[\"units\"] = int(df.get_column(unit).filter(mask).drop_nulls().n_unique())\n        differences = []\n        skip = set(keys) | ({unit} if unit else set())\n        numbers = [column for column, dtype in schema.items() if dtype.is_numeric() and column not in skip]\n        if count and others:\n            inside, outside = df.filter(mask), df.filter(~mask)\n            if numbers:\n                # A NaN counts as missing, as pandas counts it.\n                cleaned = [nw.col(column).fill_nan(None) if schema[column].is_float() else nw.col(column) for column in numbers]\n                means_in = inside.select([expression.mean() for expression in cleaned]).row(0)\n                means_out = outside.select([expression.mean() for expression in cleaned]).row(0)\n                spreads = df.select([expression.std() for expression in cleaned]).row(0)\n                gaps = []\n                for column, here, there, spread in zip(numbers, means_in, means_out, spreads):\n                    try:\n                        here, there, spread = float(here), float(there), float(spread)\n                        gap = (here - there) / spread\n                    except (TypeError, ValueError, ZeroDivisionError):\n                        continue\n                    if math.isfinite(gap):\n                        gaps.append((column, here, there, gap))\n                gaps.sort(key=lambda entry: abs(entry[3]), reverse=True)\n                for column, here, there, gap in gaps[:2]:\n                    if abs(gap) < 0.5:\n                        break\n                    differences.append(\n                        {\"column\": str(column), \"kind\": \"number\", \"inside\": float(here), \"outside\": float(there), \"gap\": round(float(gap), 2)}\n                    )\n            levelled = []\n            for column in [c for c in df.columns if c not in skip and c not in numbers][:300]:\n                try:\n                    distinct = df.get_column(column).drop_nulls().n_unique()\n                    if distinct > 20 or distinct < 2:\n                        continue\n                    # A missing value and an empty text get a name of their own.\n                    if isinstance(schema[column], nw.Datetime):\n                        text = nw.col(column).dt.to_string(\"%Y-%m-%d %H:%M:%S\")\n                    else:\n                        text = nw.col(column).cast(nw.String).str.strip_chars()\n                    label = nw.when(text == \"\").then(nw.lit(\"empty\")).otherwise(text).fill_null(\"missing\").alias(place)\n                    shares = []\n                    for part in (inside, outside):\n                        counted = part.select(label).get_column(place).value_counts(normalize=True, name=\"share\")\n                        shares.append(dict(zip(counted.get_column(place).to_list(), counted.get_column(\"share\").to_list())))\n                except Exception:\n                    continue\n                here, there = shares\n                gap = {level: here.get(level, 0.0) - there.get(level, 0.0) for level in sorted(set(here) | set(there), key=str)}\n                if not gap:\n                    continue\n                highest = max(gap, key=gap.get)\n                lowest = min(gap, key=gap.get)\n                # The level these rows have more of, else the one they lack.\n                level = highest if gap[highest] >= abs(gap[lowest]) else lowest\n                if abs(gap[level]) >= 0.2:\n                    levelled.append(\n                        {\n                            \"column\": str(column),\n                            \"kind\": \"level\",\n                            \"level\": str(level),\n                            \"inside\": float(here.get(level, 0.0)),\n                            \"outside\": float(there.get(level, 0.0)),\n                            \"gap\": round(float(gap[level]), 2),\n                        }\n                    )\n            levelled.sort(key=lambda entry: abs(entry[\"gap\"]), reverse=True)\n            differences = (differences + levelled)[:3]\n        result[\"differences\"] = differences\n\n        def number(value):\n            return f\"{value:,.0f}\" if abs(value) >= 1000 else f\"{value:.3g}\"\n\n        def said(entry):\n            column, inside, outside = entry[\"column\"], entry[\"inside\"], entry[\"outside\"]\n            if entry[\"kind\"] == \"number\":\n                if count == 1:\n                    return f\"{column} {number(inside)} against a mean of {number(outside)}\"\n                return f\"mean {column} {number(inside)} against {number(outside)}\"\n            if count == 1:\n                return f\"{column} {entry['level']}, as in {outside:.0%} of the others\"\n            return f\"{column} {entry['level']} in {inside:.0%} against {outside:.0%}\"\n\n        if count == 0:\n            result[\"seen\"] = f\"{name} has no {where}.\" if by_place else f\"No row of {name} has {where}.\"\n        elif others == 0:\n            result[\"seen\"] = f\"These are all the rows of {name}.\"\n        elif differences:\n            result[\"seen\"] = f\"Compared with the other {others:,} rows: {'; '.join(said(entry) for entry in differences)}.\"\n        else:\n            result[\"seen\"] = f\"No column of {name} differs much between these {count:,} rows and the other {others:,}.\"\n        done(result)\n\n    try:\n        import pandas as pd\n    except ImportError:\n        pd = None\n    if pd is None or args.get(\"positions\") or type(frame).__module__.split(\".\")[0] == \"polars\":\n        by_place_or_value()\n        return\n    import numpy as np\n\n    if not isinstance(frame, pd.DataFrame):\n        try:\n            import narwhals as nw\n\n            frame = nw.from_native(frame, eager_only=True).to_pandas()\n        except Exception:\n            done({\"error\": f\"{name} is not a data frame\"})\n            return\n    keys = args.get(\"keys\") or []\n    picks = [[str(label) for label in pick] for pick in args.get(\"labels\") or [] if pick]\n    unit = args.get(\"unit\")\n    absent = [key for key in keys if key not in frame.columns]\n    if absent:\n        done({\"error\": f\"{name} has no column {absent[0]}\"})\n        return\n    if keys:\n        levels = [(key, pd.Index(frame[key]), f\"{name}[{key!r}]\") for key in keys]\n    else:\n        index = frame.index\n        levels = [\n            (\n                index.names[i],\n                index.get_level_values(i),\n                f\"{name}.index\" if index.nlevels == 1 else f\"{name}.index.get_level_values({i})\",\n            )\n            for i in range(index.nlevels)\n        ]\n    if not picks or max(len(pick) for pick in picks) > len(levels):\n        done({\"error\": f\"the labels do not fit the rows of {name}\"})\n        return\n\n    missing_text = {\"NaN\", \"nan\", \"None\", \"NaT\", \"<NA>\"}\n    as_text = {}\n\n    def matches(position, text):\n        \"\"\"Which rows have a value at this level that a table writes as this text.\"\"\"\n        values = levels[position][1]\n        if text in missing_text:\n            return np.asarray(values.isna())\n        dtype = values.dtype\n        try:\n            if pd.api.types.is_bool_dtype(dtype):\n                if text not in (\"True\", \"False\"):\n                    return np.zeros(len(values), dtype=bool)\n                return np.asarray(values == (text == \"True\"))\n            if pd.api.types.is_integer_dtype(dtype):\n                return np.asarray(values == int(text))\n            if pd.api.types.is_float_dtype(dtype):\n                # A table writes six decimals: 1/3 is 0.333333.\n                return np.isclose(values.to_numpy(dtype=float), float(text), rtol=5e-6, atol=0)\n            if pd.api.types.is_datetime64_any_dtype(dtype):\n                moment = pd.Timestamp(text)\n                zone = getattr(dtype, \"tz\", None)\n                if zone is not None and moment.tz is None:\n                    moment = moment.tz_localize(zone)\n                return np.asarray(values == moment)\n        except (ValueError, TypeError, OverflowError):\n            return np.zeros(len(values), dtype=bool)\n        if position not in as_text:\n            as_text[position] = np.asarray(values.astype(str).str.strip())\n        return as_text[position] == text\n\n    def literal(value):\n        \"\"\"The value as Python code, or None when a literal cannot write it.\"\"\"\n        if isinstance(value, (bool, np.bool_)):\n            return repr(bool(value))\n        if isinstance(value, (int, np.integer)):\n            return repr(int(value))\n        if isinstance(value, (float, np.floating)):\n            return None if math.isnan(value) else repr(float(value))\n        if isinstance(value, str):\n            return repr(value)\n        if isinstance(value, pd.Timestamp) and value.tz is None:\n            return f\"pd.Timestamp({str(value)!r})\"\n        return None\n\n    def condition(position, texts, rows):\n        \"\"\"Code for the rows whose value at this level is one of these texts.\"\"\"\n        values, code = levels[position][1], levels[position][2]\n        missing = any(text in missing_text for text in texts)\n        found = [value for value in pd.unique(values[rows]) if not pd.isna(value)]\n        written = [literal(value) for value in found]\n        if found and all(written):\n            test = f\"{code} == {written[0]}\" if len(written) == 1 else f\"{code}.isin([{', '.join(written)}])\"\n        else:\n            shown = [text for text in texts if text not in missing_text]\n            test = f\"{code}.astype(str).isin({shown!r})\" if shown else None\n        if missing:\n            test = f\"{code}.isna()\" if test is None else f\"({test}) | {code}.isna()\"\n        return test or \"False\"\n\n    # A pick has a label for each level, down to the level clicked: [\"A\"] for\n    # the outer label of a group, [\"A\", \"3\"] for one row under it.\n    picked = []\n    for pick in picks:\n        rows = np.ones(len(frame), dtype=bool)\n        for position, text in enumerate(pick):\n            rows &= matches(position, text)\n        picked.append(rows)\n    mask = np.logical_or.reduce(picked)\n    single = all(len(pick) == 1 for pick in picks)\n    if single:\n        texts = list(dict.fromkeys(pick[0] for pick in picks))\n        mask_code = condition(0, texts, mask)\n    else:\n        tests = []\n        for pick, rows in zip(picks, picked):\n            parts = [condition(position, [text], rows) for position, text in enumerate(pick)]\n            tests.append(\" & \".join(f\"({part})\" for part in parts) if len(parts) > 1 else parts[0])\n        mask_code = \" | \".join(f\"({test})\" for test in tests) if len(tests) > 1 else tests[0]\n    try:\n        # The code must pick the same rows, or the questions offer none.\n        same = np.array_equal(np.asarray(eval(mask_code, {**namespace, \"pd\": pd}), dtype=bool), mask)\n    except Exception:\n        same = False\n    if not same:\n        mask_code = None\n\n    def level_name(position):\n        return str(levels[position][0]) if levels[position][0] is not None else \"index\"\n\n    def listed(texts):\n        return texts[0] if len(texts) == 1 else f\"{', '.join(texts[:-1])} and {texts[-1]}\"\n\n    if single:\n        texts = list(dict.fromkeys(pick[0] for pick in picks))\n        shown = texts if len(texts) <= 4 else texts[:3] + [f\"{len(texts) - 3} more\"]\n        where = f\"{level_name(0)} = {texts[0]}\" if len(texts) == 1 else f\"{level_name(0)} in {listed(shown)}\"\n    elif len(picks) == 1:\n        where = \" and \".join(f\"{level_name(position)} = {text}\" for position, text in enumerate(picks[0]))\n    else:\n        depth = max(len(pick) for pick in picks)\n        where = f\"{len(picks)} labels of {listed([level_name(position) for position in range(depth)])}\"\n\n    count, total = int(mask.sum()), len(frame)\n    others = total - count\n    result = {\"rows\": count, \"total_rows\": total, \"where\": where, \"mask\": mask_code}\n    if unit and unit in frame.columns:\n        result[\"unit\"] = unit\n        result[\"units\"] = int(frame.loc[mask, unit].nunique())\n    differences = []\n    if count and others:\n        skip = set(keys) | ({unit} if unit else set())\n        numbers = frame.select_dtypes(\"number\")\n        numbers = numbers[[column for column in numbers.columns if column not in skip]]\n        if numbers.shape[1]:\n            inside, outside = numbers[mask].mean(), numbers[~mask].mean()\n            gaps = ((inside - outside) / numbers.std()).replace([np.inf, -np.inf], np.nan).dropna()\n            for column in gaps.abs().sort_values(ascending=False).index[:2]:\n                if abs(gaps[column]) < 0.5:\n                    break\n                differences.append(\n                    {\n                        \"column\": str(column),\n                        \"kind\": \"number\",\n                        \"inside\": float(inside[column]),\n                        \"outside\": float(outside[column]),\n                        \"gap\": round(float(gaps[column]), 2),\n                    }\n                )\n        levelled = []\n        for column in [c for c in frame.columns if c not in skip and c not in numbers.columns][:300]:\n            series = frame[column]\n            try:\n                distinct = series.nunique()\n                if distinct > 20 or distinct < 2:\n                    continue\n                # A missing value and an empty text get a name of their own.\n                text = series.astype(str).str.strip()\n                text = text.mask(series.isna(), \"missing\").mask(text == \"\", \"empty\")\n                here = text[mask].value_counts(normalize=True)\n                there = text[~mask].value_counts(normalize=True)\n            except TypeError:\n                continue\n            gap = here.sub(there, fill_value=0)\n            # The level these rows have more of, else the one they lack.\n            level = gap.idxmax() if gap.max() >= abs(gap.min()) else gap.idxmin()\n            if abs(gap[level]) >= 0.2:\n                levelled.append(\n                    {\n                        \"column\": str(column),\n                        \"kind\": \"level\",\n                        \"level\": str(level),\n                        \"inside\": float(here.get(level, 0.0)),\n                        \"outside\": float(there.get(level, 0.0)),\n                        \"gap\": round(float(gap[level]), 2),\n                    }\n                )\n        levelled.sort(key=lambda entry: abs(entry[\"gap\"]), reverse=True)\n        differences = (differences + levelled)[:3]\n    result[\"differences\"] = differences\n\n    def number(value):\n        return f\"{value:,.0f}\" if abs(value) >= 1000 else f\"{value:.3g}\"\n\n    def said(entry):\n        column, inside, outside = entry[\"column\"], entry[\"inside\"], entry[\"outside\"]\n        if entry[\"kind\"] == \"number\":\n            if count == 1:\n                return f\"{column} {number(inside)} against a mean of {number(outside)}\"\n            return f\"mean {column} {number(inside)} against {number(outside)}\"\n        if count == 1:\n            return f\"{column} {entry['level']}, as in {outside:.0%} of the others\"\n        return f\"{column} {entry['level']} in {inside:.0%} against {outside:.0%}\"\n\n    if count == 0:\n        result[\"seen\"] = f\"No row of {name} has {where}.\"\n    elif others == 0:\n        result[\"seen\"] = f\"These are all the rows of {name}.\"\n    elif differences:\n        result[\"seen\"] = f\"Compared with the other {others:,} rows: {'; '.join(said(entry) for entry in differences)}.\"\n    else:\n        result[\"seen\"] = f\"No column of {name} differs much between these {count:,} rows and the other {others:,}.\"\n    done(result)\n";

export const writeFrames = "\"\"\"Write data frames of the kernel to files that a notebook of another kernel reads.\n\nAn agent that answers a question in a second notebook (design iteration 1.69)\nmoves the data as files: the analyst's kernel writes the frames that the\ncells to port read, into a folder beside the notebooks, and the second\nnotebook reads them. Parquet keeps each column's type; it needs pyarrow or\nfastparquet here for a pandas frame, and a reader in the other kernel. CSV\nneeds neither. ``args[\"format\"]`` is \"parquet\" when the other kernel reads\nparquet; a frame that cannot go as parquet here goes as CSV.\n\nA pandas frame whose index holds data, such as the keys of a groupby, keeps\nit as columns; an index of the rows' places, as after a filter, stays out.\nColumns under two levels of headers join their names with \"_\".\n\nThe result gives each file's path from the kernel's folder, its format, its\nsize and its columns, and whether a file of that name was there before.\n\nThe frontend bundle holds the text of this file and runs it in the kernel, so\nit must not import the whybook package.\n\"\"\"\n\n\ndef _whybook_write_frames(args):\n    import os\n\n    from IPython import get_ipython\n    from IPython.display import display\n\n    namespace = get_ipython().user_ns\n    folder = str(args.get(\"folder\") or \"from_python\")\n    wanted = \"parquet\" if args.get(\"format\") == \"parquet\" else \"csv\"\n    files = []\n    errors = []\n\n    def columns_of(names, types):\n        return [{\"name\": str(name), \"type\": str(kind)} for name, kind in list(zip(names, types))[:200]]\n\n    def write_pandas(frame, name):\n        import pandas as pd\n\n        if isinstance(frame, pd.Series):\n            frame = frame.to_frame(name=frame.name if frame.name is not None else name)\n        # An index without a name and of whole numbers holds the rows' places,\n        # as after a filter: it stays out. A named index, such as the keys of\n        # a groupby, or one of labels, goes into columns.\n        index = frame.index\n        named = any(level is not None for level in index.names)\n        if named or not pd.api.types.is_integer_dtype(index.dtype):\n            frame = frame.reset_index()\n        if isinstance(frame.columns, pd.MultiIndex):\n            frame = frame.copy()\n            frame.columns = [\"_\".join(str(part) for part in column if str(part)) for column in frame.columns]\n        written = None\n        if wanted == \"parquet\":\n            path = os.path.join(folder, f\"{name}.parquet\")\n            existed = os.path.exists(path)\n            try:\n                frame.to_parquet(path, index=False)\n                written = (\"parquet\", path, existed)\n            except Exception:  # noqa: BLE001  no engine here, or a column that parquet cannot hold: CSV then\n                if not existed and os.path.exists(path):\n                    os.remove(path)\n        if written is None:\n            path = os.path.join(folder, f\"{name}.csv\")\n            existed = os.path.exists(path)\n            frame.to_csv(path, index=False)\n            written = (\"csv\", path, existed)\n        format_, path, existed = written\n        return format_, path, existed, int(frame.shape[0]), columns_of(frame.columns, frame.dtypes)\n\n    def write_polars(frame, name):\n        written = None\n        if wanted == \"parquet\":\n            path = os.path.join(folder, f\"{name}.parquet\")\n            existed = os.path.exists(path)\n            try:\n                frame.write_parquet(path)\n                written = (\"parquet\", path, existed)\n            except Exception:  # noqa: BLE001  CSV then\n                if not existed and os.path.exists(path):\n                    os.remove(path)\n        if written is None:\n            path = os.path.join(folder, f\"{name}.csv\")\n            existed = os.path.exists(path)\n            frame.write_csv(path)\n            written = (\"csv\", path, existed)\n        format_, path, existed = written\n        return format_, path, existed, int(frame.height), columns_of(frame.columns, frame.dtypes)\n\n    for name in [str(item) for item in args.get(\"frames\") or []]:\n        if not name.isidentifier() or name not in namespace:\n            errors.append({\"frame\": name, \"error\": f\"no variable named {name}\"})\n            continue\n        frame = namespace[name]\n        library = type(frame).__module__.split(\".\")[0]\n        try:\n            os.makedirs(folder, exist_ok=True)\n            if library == \"pandas\" and hasattr(frame, \"to_csv\"):\n                found = write_pandas(frame, name)\n            elif library == \"polars\" and hasattr(frame, \"write_csv\"):\n                found = write_polars(frame, name)\n            elif library == \"polars\" and hasattr(frame, \"collect\"):\n                errors.append({\"frame\": name, \"error\": f\"{name} is a lazy frame: collect it into a frame first\"})\n                continue\n            else:\n                errors.append({\"frame\": name, \"error\": f\"{name} is not a data frame of pandas or polars\"})\n                continue\n        except Exception as error:  # noqa: BLE001  the error goes to the agent\n            errors.append({\"frame\": name, \"error\": f\"{type(error).__name__}: {error}\"[:300]})\n            continue\n        format_, path, existed, rows, columns = found\n        files.append(\n            {\n                \"frame\": name,\n                \"path\": path.replace(os.sep, \"/\"),\n                \"format\": format_,\n                \"rows\": rows,\n                \"columns\": columns,\n                \"existed\": existed,\n            }\n        )\n\n    display({\"application/vnd.whybook.result+json\": {\"folder\": folder, \"files\": files, \"errors\": errors}}, raw=True)\n";

export const python: Record<string, string> = {
  analyze_cells: analyzeCells,
  inspect_variables: inspectVariables,
  kernel_facts: kernelFacts,
  plot_hooks: plotHooks,
  region_summary: regionSummary,
  table_rows: tableRows,
  write_frames: writeFrames
};

export const rAnalyzeCells = "# Static analysis of R cells against the kernel's global environment.\n#\n# The R version of analyze_cells.py (design iteration 1.79). For each cell:\n# the names it defines and uses, the columns of data frames it touches, its\n# formulas, and its decisions, in the message of the Python version, so that\n# the view draws the chips of an R cell as it draws those of a Python cell. A\n# decision is a value that changes the result:\n#\n# - `defaulted`: a formal of the analyst's own function, from a file of the\n#   kernel's folder that source() read, left at its default, such as\n#   `slope = \"month\"`, or the constant of the file that the default names;\n# - `library_default`: a parameter of a known R function left at a default\n#   that changes results, such as `REML = TRUE` in lme4's lmer (the table\n#   `known` below);\n# - `literal`: a value written in the cell, such as `REML = FALSE` in a call,\n#   or a constant assigned at the top level, such as `MIN_DAYS <- 14`.\n#\n# A function of the analyst's file also gives its first lines, under\n# `attachments`, as in the Python version.\n#\n# R's own parser reads the cell (`parse` and `utils::getParseData`), and no\n# code of the cell runs. Each decision of a call is keyed by that call: where\n# the cell names the function, its line from 1 and its column in UTF-8 bytes\n# from the start of the line, as the Python version counts them. Calls that\n# leave the same parameter at the same value share one decision, which lists\n# them in `calls`, each with the frame that it joins, reads or works on, in\n# one word (`target`). A decision's `function` names the function with its\n# package, `stats::t.test`, so that a name with a dot stays one name.\n#\n# The kernel holds what the cell calls: a function that the global\n# environment or an attached package defines is read for its formals, and an\n# S3 generic for the method that the class of its first argument picks. A\n# function of the table whose package is not loaded is read from the table.\n#\n# With `signatures` in the arguments (the view's setting \"Find more defaults\n# with AI\", design iteration 1.53), a cell also lists the functions of R's\n# packages that it calls, under `signatures`, as the Python version does:\n# each function's package and version, each formal that has a default, with\n# the default as code, and each call with the formals that it leaves at\n# their defaults. A default that looks like a key is left out, the\n# analyst's own functions are left out, and a cell lists at most\n# `max_signatures` functions.\n#\n# The frontend bundle holds the text of this file (scripts/embed-kernel-code.mjs),\n# runs it in the global environment, calls the function with the JSON\n# arguments and removes it again (the R adapter in src/model/languages.ts).\n# It needs jsonlite and IRdisplay, which R kernels depend on. The result goes\n# out as display data with a MIME type that output areas do not render.\n.whybook_analyze_cells <- function(args) {\n  max_decisions <- if (is.null(args$max_decisions)) 6L else as.integer(args$max_decisions)\n  read_signatures <- isTRUE(args$signatures)\n  max_signatures <- if (is.null(args$max_signatures)) 8L else as.integer(args$max_signatures)\n  global <- globalenv()\n  # jsonlite writes NA of a flag or of a text as null, and NA of a number as\n  # the text \"NA\": a number that may be missing is NA, a flag.\n\n  # A key, a token or a password is no choice to try, and its text would go\n  # into the notebook with the analysis. The server, the Python kernel code\n  # and the view hold the same rule (privacy.py says it in full,\n  # tests/data/secret_names.json holds its cases): only a string is a secret.\n  secret_words <- c(\n    \"token\", \"secret\", \"secrets\", \"password\", \"passwords\", \"passwd\", \"pwd\",\n    \"credential\", \"credentials\", \"bearer\", \"apikey\", \"auth\"\n  )\n  secret_endings <- c(\"token\", \"secret\", \"password\", \"passwd\", \"apikey\")\n  secret_pairs <- c(\"api key\", \"access key\", \"private key\", \"secret key\")\n  secret_prefix <- paste0(\n    \"(?<![A-Za-z0-9])(?:sk-|sk_live_|sk_test_|hf_|ghp_|gho_|ghu_|ghs_|ghr_|github_pat_|glpat-|xox[abpr]-|xapp-\",\n    \"|AKIA|ASIA|AIza|ya29\\\\.|eyJ|npm_|pypi-)[A-Za-z0-9_.=-]{16,}\"\n  )\n  # A password in a URL, as a connection string holds it, and a query parameter named as a secret.\n  url_password <- \"[A-Za-z][A-Za-z0-9+.-]*://[^\\\\s/?#@:]*:[^\\\\s/?#@]+@\"\n  query_name <- \"[?&][A-Za-z0-9_.-]+=[^&#\\\\s]\"\n  all_of <- function(pattern, text) regmatches(text, gregexpr(pattern, text, perl = TRUE))[[1]]\n\n  secret_name <- function(name) {\n    parts <- tolower(all_of(\"[A-Z]+(?![a-z])|[A-Z]?[a-z]+\", name))\n    if (any(parts %in% secret_words)) {\n      return(TRUE)\n    }\n    for (ending in secret_endings) {\n      if (any(endsWith(parts, ending))) {\n        return(TRUE)\n      }\n    }\n    length(parts) > 1 && any(paste(parts[-length(parts)], parts[-1]) %in% secret_pairs)\n  }\n\n  # Whether a decision holds a secret, from its name and its value as R code.\n  looks_secret <- function(name, value) {\n    text <- tryCatch(str2lang(value), error = function(e) NULL)\n    if (!is.character(text) || length(text) != 1 || is.na(text)) {\n      return(FALSE)\n    }\n    if (secret_name(name)) {\n      return(TRUE)\n    }\n    if (grepl(secret_prefix, text, perl = TRUE) || grepl(url_password, text, perl = TRUE)) {\n      return(TRUE)\n    }\n    keys <- sub(\"^[?&]([A-Za-z0-9_.-]+)=.*$\", \"\\\\1\", all_of(query_name, text), perl = TRUE)\n    if (any(vapply(keys, secret_name, logical(1)))) {\n      return(TRUE)\n    }\n    runs <- all_of(\"[A-Za-z0-9]{20,}\", text)\n    any(nchar(runs) >= 32 | (grepl(\"[A-Z]\", runs) & grepl(\"[a-z]\", runs) & grepl(\"[0-9]\", runs)))\n  }\n\n  # The two options that set defaults of R's model functions, as they are now.\n  contrasts_now <- getOption(\"contrasts\")\n  coding <- if (is.character(contrasts_now) && \"unordered\" %in% names(contrasts_now)) {\n    contrasts_now[[\"unordered\"]]\n  } else {\n    \"contr.treatment\"\n  }\n  na_now <- getOption(\"na.action\")\n  na_action <- if (is.character(na_now) && length(na_now) == 1) na_now else \"na.omit\"\n\n  # The defaults that change results, by function. `params` gives the order\n  # of the formals, for a function whose package is not loaded; `when` says\n  # whether the default matters in a call, from what the call passes. A\n  # default without a parameter, such as the sums of squares of anova, has\n  # `param` NA.\n  model_frame <- list(\n    contrasts = list(\n      value = deparse(coding),\n      note = if (coding == \"contr.treatment\") {\n        \"treatment coding: each coefficient compares a level with the first level, where SAS compares it with the last\"\n      } else {\n        \"the coding of factors that options(contrasts) sets in this session\"\n      },\n      when = function(call) call$factors\n    ),\n    na.action = list(\n      value = na_action,\n      note = \"rows with a missing value in any variable of the model are dropped\",\n      when = function(call) TRUE\n    )\n  )\n  na_strings <- list(\n    value = \"\\\"NA\\\"\",\n    note = \"only the text NA reads as missing: in a text column an empty cell stays an empty text, and a value such as n/a turns a column of numbers into text\",\n    when = function(call) TRUE\n  )\n  always <- function(call) TRUE\n  # The readers of delimited text that set header = TRUE, unlike read.table.\n  header_line <- list(\n    value = \"TRUE\",\n    note = \"the first line names the columns, and is not read as data: header = FALSE reads it as data\",\n    when = always\n  )\n  known <- list(\n    lm = list(package = \"stats\", params = c(\n      \"formula\", \"data\", \"subset\", \"weights\", \"na.action\", \"method\", \"model\",\n      \"x\", \"y\", \"qr\", \"singular.ok\", \"contrasts\", \"offset\"\n    ), defaults = model_frame),\n    glm = list(package = \"stats\", params = c(\n      \"formula\", \"family\", \"data\", \"weights\", \"subset\", \"na.action\", \"start\",\n      \"etastart\", \"mustart\", \"offset\", \"control\", \"model\", \"method\", \"x\", \"y\",\n      \"singular.ok\", \"contrasts\"\n    ), defaults = c(list(family = list(\n      value = \"gaussian\",\n      note = \"normal errors and an identity link, a linear model: a 0/1 outcome needs binomial, a count poisson\",\n      when = always\n    )), model_frame)),\n    lmer = list(package = \"lme4\", also = \"lmerTest\", params = c(\n      \"formula\", \"data\", \"REML\", \"control\", \"start\", \"verbose\", \"subset\",\n      \"weights\", \"na.action\", \"offset\", \"contrasts\", \"devFunOnly\"\n    ), defaults = c(list(REML = list(\n      value = \"TRUE\",\n      note = \"REML fit: likelihoods cannot compare models with different fixed effects\",\n      when = always\n    )), model_frame)),\n    glmer = list(package = \"lme4\", params = c(\n      \"formula\", \"data\", \"family\", \"control\", \"start\", \"verbose\", \"nAGQ\",\n      \"subset\", \"weights\", \"na.action\", \"offset\", \"contrasts\", \"mustart\",\n      \"etastart\", \"devFunOnly\"\n    ), defaults = c(list(nAGQ = list(\n      value = \"1L\",\n      note = \"Laplace approximation of the likelihood: more quadrature points, nAGQ > 1, are more accurate with one random intercept\",\n      when = always\n    )), model_frame)),\n    anova = list(package = \"stats\", params = \"object\", defaults = list(SS = list(\n      param = NA_character_,\n      value = \"Type I\",\n      note = \"sequential sums of squares: each term is tested after the terms before it, so their order changes the result; car::Anova tests Type II or III\",\n      when = function(call) call$positional == 1L\n    ))),\n    Anova = list(package = \"car\", params = \"mod\", defaults = list(type = list(\n      value = \"\\\"II\\\"\",\n      note = \"Type II tests: each term after the terms that do not contain it; Type III needs sum-to-zero contrasts\",\n      when = always\n    ))),\n    t.test = list(package = \"stats\", params = c(\n      \"x\", \"y\", \"alternative\", \"mu\", \"paired\", \"var.equal\", \"conf.level\"\n    ), defaults = list(var.equal = list(\n      value = \"FALSE\",\n      note = \"Welch's t test: the two groups may have different variances, and the degrees of freedom are not whole\",\n      when = function(call) call$two_samples\n    ))),\n    merge = list(package = \"base\", params = c(\n      \"x\", \"y\", \"by\", \"by.x\", \"by.y\", \"all\", \"all.x\", \"all.y\", \"sort\",\n      \"suffixes\", \"no.dups\", \"incomparables\"\n    ), defaults = list(all = list(\n      value = \"FALSE\",\n      note = \"rows without a match in both frames are dropped\",\n      when = function(call) !any(c(\"all.x\", \"all.y\") %in% call$passed)\n    ))),\n    cor = list(package = \"stats\", params = c(\"x\", \"y\", \"use\", \"method\"), defaults = list(method = list(\n      value = \"\\\"pearson\\\"\", note = \"linear correlation, sensitive to outliers\", when = always\n    ))),\n    cor.test = list(package = \"stats\", params = c(\"x\", \"y\"), defaults = list(method = list(\n      value = \"\\\"pearson\\\"\", note = \"linear correlation, sensitive to outliers\", when = always\n    ))),\n    quantile = list(package = \"stats\", params = c(\"x\", \"probs\", \"na.rm\", \"names\", \"type\", \"digits\"), defaults = list(type = list(\n      value = \"7\",\n      note = \"linear interpolation between the order statistics; the default of SAS is type 2, and SPSS computes type 6\",\n      when = always\n    ))),\n    p.adjust = list(package = \"stats\", params = c(\"p\", \"method\", \"n\"), defaults = list(method = list(\n      value = \"\\\"holm\\\"\",\n      note = \"Holm's correction holds the chance of any false positive; method = \\\"BH\\\" holds the share of false discoveries instead\",\n      when = always\n    ))),\n    read.csv = list(package = \"utils\", params = c(\"file\", \"header\", \"sep\", \"quote\", \"dec\", \"fill\", \"comment.char\"), defaults = list(header = header_line, na.strings = na_strings)),\n    read.csv2 = list(package = \"utils\", params = c(\"file\", \"header\", \"sep\", \"quote\", \"dec\", \"fill\", \"comment.char\"), defaults = list(header = header_line, na.strings = na_strings)),\n    read.delim = list(package = \"utils\", params = c(\"file\", \"header\", \"sep\", \"quote\", \"dec\", \"fill\", \"comment.char\"), defaults = list(header = header_line, na.strings = na_strings)),\n    read.delim2 = list(package = \"utils\", params = c(\"file\", \"header\", \"sep\", \"quote\", \"dec\", \"fill\", \"comment.char\"), defaults = list(header = header_line, na.strings = na_strings)),\n    read.table = list(package = \"utils\", params = c(\"file\", \"header\", \"sep\", \"quote\", \"dec\"), defaults = list(\n      header = list(value = \"FALSE\", note = \"the first line is read as data, not as the names of the columns\", when = always),\n      na.strings = na_strings\n    )),\n    chisq.test = list(package = \"stats\", params = c(\"x\", \"y\", \"correct\"), defaults = list(correct = list(\n      value = \"TRUE\", note = \"Yates' continuity correction on a 2 by 2 table: the p-value is larger\", when = always\n    ))),\n    prop.test = list(package = \"stats\", params = c(\"x\", \"n\", \"p\", \"alternative\", \"conf.level\", \"correct\"), defaults = list(correct = list(\n      value = \"TRUE\", note = \"Yates' continuity correction: the p-value is larger and the interval wider\", when = always\n    ))),\n    predict = list(package = \"stats\", params = \"object\", defaults = list(type = list(\n      value = \"\\\"link\\\"\",\n      note = \"predictions on the scale of the linear predictor, log odds for a logistic model: type = \\\"response\\\" gives probabilities\",\n      when = function(call) inherits(call$object, \"glm\")\n    ))),\n    table = list(package = \"base\", params = character(0), defaults = list(useNA = list(\n      value = \"\\\"no\\\"\", note = \"missing values are not counted\", when = always\n    )))\n  )\n  # Readers whose formals end in `...`, which they pass on to read.table.\n  forwards <- c(read.csv = \"read.table\", read.csv2 = \"read.table\", read.delim = \"read.table\", read.delim2 = \"read.table\")\n  # Arguments that name data rather than choose how to analyse it.\n  skipped_params <- c(\n    \"data\", \"x\", \"y\", \"X\", \"formula\", \"object\", \"subset\", \"by\", \"by.x\", \"by.y\",\n    \"newdata\", \"names\", \"labels\", \"main\", \"sub\", \"xlab\", \"ylab\", \"title\",\n    \"col\", \"sep\", \"collapse\", \"verbose\", \"quiet\", \"seed\", \"envir\", \"FUN\",\n    \"row.names\", \"col.names\", \"outcome\", \"mod\", \"group\", \"groups\"\n  )\n  # Calls whose arguments are not analysis choices: source() reads the\n  # analyst's file, as an import does in Python, and the named arguments of\n  # cbind() or data.frame() name columns.\n  skipped_functions <- c(\n    \"print\", \"cat\", \"message\", \"format\", \"formatC\", \"sprintf\", \"paste\",\n    \"paste0\", \"round\", \"signif\", \"c\", \"list\", \"length\", \"seq_len\",\n    \"seq_along\", \"seq\", \"rep\", \"nrow\", \"ncol\", \"str\", \"invisible\", \"library\",\n    \"require\", \"requireNamespace\", \"suppressMessages\", \"suppressWarnings\",\n    \"suppressPackageStartupMessages\", \"display\", \"set.seed\", \"source\", \"sys.source\",\n    \"cbind\", \"rbind\", \"data.frame\", \"expand.grid\", \"setNames\", \"structure\"\n  )\n  family_functions <- c(\n    \"binomial\", \"poisson\", \"gaussian\", \"Gamma\", \"inverse.gaussian\", \"quasi\",\n    \"quasibinomial\", \"quasipoisson\"\n  )\n  reader <- function(name) grepl(\"^(read|scan)[._]\", name) || name == \"readRDS\"\n\n  frames <- list()\n  for (name in ls(envir = global)) {\n    value <- get0(name, envir = global, inherits = FALSE)\n    if (is.data.frame(value)) {\n      frames[[name]] <- names(value)\n    }\n  }\n  is_global <- function(name) exists(name, envir = global, inherits = FALSE)\n  versions <- new.env()\n  version_of <- function(package) {\n    if (is.null(versions[[package]])) {\n      versions[[package]] <- tryCatch(as.character(utils::packageVersion(package)), error = function(e) NA_character_)\n    }\n    versions[[package]]\n  }\n\n  # The function a call runs, as the kernel holds it: from its package when\n  # the call names one and the package is loaded, else from the global\n  # environment and the attached packages. NULL when it is not there.\n  resolve <- function(name, package) {\n    found <- if (!is.na(package)) {\n      if (isNamespaceLoaded(package)) get0(name, envir = asNamespace(package), inherits = FALSE) else NULL\n    } else {\n      get0(name, envir = global, mode = \"function\")\n    }\n    if (is.function(found)) found else NULL\n  }\n  package_of <- function(fn) {\n    env <- environment(fn)\n    if (is.null(env)) \"base\" else environmentName(env)\n  }\n  formals_of <- function(fn) {\n    if (is.primitive(fn)) formals(args(fn)) else formals(fn)\n  }\n  before_dots <- function(params) {\n    at <- match(\"...\", params)\n    if (is.na(at)) params else params[seq_len(at - 1)]\n  }\n\n  # The file under the kernel's folder that defines one of the analyst's\n  # functions, as source() read it, or NA: a function that a cell defines\n  # comes from no file.\n  folder <- normalizePath(getwd(), winslash = \"/\", mustWork = FALSE)\n  file_of <- function(fn) {\n    srcfile <- attr(attr(fn, \"srcref\"), \"srcfile\")\n    name <- if (is.environment(srcfile)) srcfile$filename else NULL\n    if (!is.character(name) || length(name) != 1 || !nzchar(name)) {\n      return(NA_character_)\n    }\n    if (!grepl(\"^(/|[A-Za-z]:)\", name)) {\n      name <- file.path(if (is.character(srcfile$wd)) srcfile$wd else folder, name)\n    }\n    path <- normalizePath(name, winslash = \"/\", mustWork = FALSE)\n    if (file.exists(path) && startsWith(path, paste0(folder, \"/\"))) path else NA_character_\n  }\n  file_lines <- new.env()\n  lines_of <- function(path) {\n    if (is.null(file_lines[[path]])) {\n      file_lines[[path]] <- tryCatch(readLines(path, warn = FALSE, encoding = \"UTF-8\"), error = function(e) character(0))\n    }\n    file_lines[[path]]\n  }\n  # The line of a file that assigns a constant, and its text: REML_REPS <- 3.\n  line_of <- function(path, name) {\n    written <- lines_of(path)\n    at <- grep(paste0(\"^\\\\s*\\\\Q\", name, \"\\\\E\\\\s*(<<?-|=[^=])\"), written, perl = TRUE)[1]\n    if (is.na(at)) list(line = NA, text = NA_character_) else list(line = at, text = written[[at]])\n  }\n  # The first lines of the analyst's function, as Cell details shows the\n  # file it comes from, with the line of the constant first when they do not\n  # hold it.\n  attachment_for <- function(fn, path, relative, symbol, highlight) {\n    srcref <- attr(fn, \"srcref\")\n    written <- lines_of(path)\n    if (is.null(srcref) || !length(written)) {\n      return(NULL)\n    }\n    start <- srcref[[1]]\n    end <- min(srcref[[3]], length(written))\n    shown <- lapply(seq.int(start, min(end, start + 11L)), function(number) list(number, written[[number]]))\n    if (!is.null(highlight) && (highlight$line < start || highlight$line > min(end, start + 11L))) {\n      shown <- c(list(list(highlight$line, highlight$text), list(NA, \"\\u2026\")), shown)\n    }\n    list(\n      file = relative, symbol = symbol, start = start, end = end, lines = shown,\n      highlight = if (is.null(highlight)) list() else list(highlight$line)\n    )\n  }\n\n  # A default as code: the first of the choices of a vector of strings, as\n  # match.arg reads `c(\"two.sided\", \"less\")`; NULL for one that looks like a\n  # key, or that is too long to show.\n  default_text <- function(name, value, env) {\n    if (is.call(value) && identical(value[[1]], as.name(\"c\")) && length(value) >= 3 &&\n      all(vapply(as.list(value)[-1], is.character, logical(1)))) {\n      value <- value[[2]]\n    } else if (is.symbol(value) && !is.null(env)) {\n      choices <- get0(as.character(value), envir = env)\n      if (is.character(choices) && length(choices) >= 2) {\n        value <- choices[[1]]\n      }\n    }\n    text <- paste(deparse(value, width.cutoff = 500L), collapse = \" \")\n    if (nchar(text) > 200 || looks_secret(name, text)) NULL else text\n  }\n\n  # What the formals of a library function hold, read once in a request.\n  read_functions <- new.env()\n  signature_of <- function(key, name, package, method, extra) {\n    if (!is.null(read_functions[[key]])) {\n      return(read_functions[[key]])\n    }\n    params <- list()\n    for (fn in c(list(method), extra)) {\n      defaults <- formals_of(fn)\n      for (param in names(defaults)) {\n        # A formal without a default holds the empty symbol, which R reads as a missing argument.\n        if (param == \"...\" || identical(defaults[[param]], quote(expr = ))) {\n          next\n        }\n        value <- defaults[[param]]\n        if (any(vapply(params, function(item) identical(item$name, param), logical(1)))) {\n          next\n        }\n        text <- default_text(param, value, environment(fn))\n        if (!is.null(text)) {\n          params[[length(params) + 1]] <- list(name = param, default = text)\n        }\n      }\n    }\n    entry <- list(\n      `function` = key, name = name, module = package, library = package,\n      version = version_of(package), language = \"R\", params = params, calls = list()\n    )\n    read_functions[[key]] <- entry\n    entry\n  }\n\n  analyze <- function(source) {\n    exprs <- tryCatch(parse(text = source, keep.source = TRUE), error = function(e) e)\n    if (inherits(exprs, \"error\")) {\n      stop(paste(\"Parse error:\", conditionMessage(exprs)), call. = FALSE)\n    }\n    pd <- utils::getParseData(exprs, includeText = TRUE)\n    empty <- list(\n      defs = list(), uses = list(), formulas = list(),\n      columns = stats::setNames(list(), character(0)), decisions = list(), attachments = list()\n    )\n    if (is.null(pd) || nrow(pd) == 0) {\n      if (read_signatures) {\n        empty$signatures <- list()\n      }\n      return(empty)\n    }\n    lines <- strsplit(source, \"\\n\", fixed = TRUE)[[1]]\n    ids <- pd$id\n    token <- pd$token\n    text <- pd$text\n    parent <- pd$parent\n    row_by_id <- integer(max(ids))\n    row_by_id[ids] <- seq_along(ids)\n    row_of <- function(id) {\n      if (is.na(id) || id <= 0 || id > length(row_by_id) || row_by_id[id] == 0L) NA_integer_ else row_by_id[id]\n    }\n    children <- split(seq_len(nrow(pd)), parent)\n    kids <- function(row) {\n      found <- children[[as.character(ids[row])]]\n      if (is.null(found)) integer(0) else found\n    }\n    below <- function(row) {\n      found <- integer(0)\n      todo <- kids(row)\n      while (length(todo)) {\n        found <- c(found, todo[1])\n        todo <- c(kids(todo[1]), todo[-1])\n      }\n      found\n    }\n    node_text <- function(row) {\n      if (pd$terminal[row]) text[row] else utils::getParseText(pd, ids[row])\n    }\n    # The column in UTF-8 bytes of R's column, which counts characters and\n    # moves a tab to the next multiple of 8.\n    byte_col <- function(line, col) {\n      chars <- strsplit(if (line <= length(lines)) lines[[line]] else \"\", \"\")[[1]]\n      shown <- 0L\n      bytes <- 0L\n      for (char in chars) {\n        if (shown + 1L >= col) {\n          break\n        }\n        shown <- if (char == \"\\t\") (shown %/% 8L + 1L) * 8L else shown + 1L\n        bytes <- bytes + nchar(char, type = \"bytes\")\n      }\n      bytes\n    }\n    # The one child of an expr, when it has only one: x for the expr of x.\n    only <- function(row) {\n      found <- kids(row)\n      if (length(found) == 1) found else NA_integer_\n    }\n    symbol_of <- function(row) {\n      one <- only(row)\n      if (!is.na(one) && token[one] %in% c(\"SYMBOL\", \"STR_CONST\")) {\n        name <- text[one]\n        if (token[one] == \"STR_CONST\") name <- str2lang(name)\n        return(name)\n      }\n      NA_character_\n    }\n    # The name an expression starts from: d for d$age, names(d)[2] or d[[\"a\"]].\n    root_of <- function(row) {\n      while (!is.na(row)) {\n        name <- symbol_of(row)\n        if (!is.na(name)) {\n          return(name)\n        }\n        found <- kids(row)\n        if (!length(found) || token[found[1]] != \"expr\") {\n          return(NA_character_)\n        }\n        first <- found[1]\n        call_name <- kids(first)\n        if (length(found) >= 2 && token[found[2]] == \"'('\" && length(call_name) &&\n          any(token[call_name] == \"SYMBOL_FUNCTION_CALL\")) {\n          # A replacement call, names(d) <- ...: the name is its first argument.\n          row <- if (length(found) >= 3 && token[found[3]] == \"expr\") found[3] else NA_integer_\n        } else {\n          row <- first\n        }\n      }\n      NA_character_\n    }\n\n    # Which rows lie in the body or the formals of a function the cell defines.\n    in_function <- logical(nrow(pd))\n    mark <- function(row, inside) {\n      in_function[row] <<- inside\n      found <- kids(row)\n      defines <- any(token[found] %in% c(\"FUNCTION\", \"'\\\\\\\\'\"))\n      for (child in found) mark(child, inside || defines)\n    }\n    for (row in which(parent == 0)) mark(row, FALSE)\n\n    # Assignments: the name each defines, and whether its target is the name alone.\n    defs <- character(0)\n    plain_targets <- integer(0)\n    assignments <- list()\n    for (row in which(!pd$terminal)) {\n      found <- kids(row)\n      if (length(found) != 3 || !(token[found[2]] %in% c(\"LEFT_ASSIGN\", \"EQ_ASSIGN\", \"RIGHT_ASSIGN\"))) {\n        next\n      }\n      right <- token[found[2]] == \"RIGHT_ASSIGN\"\n      target <- if (right) found[3] else found[1]\n      value <- if (right) found[1] else found[3]\n      name <- root_of(target)\n      if (is.na(name)) {\n        next\n      }\n      plain <- !is.na(symbol_of(target))\n      if (plain) {\n        plain_targets <- c(plain_targets, only(target))\n      }\n      assignments[[length(assignments) + 1]] <- list(row = row, name = name, value = value, plain = plain, top = parent[row] == 0)\n      if (!in_function[row]) {\n        defs <- c(defs, name)\n      }\n    }\n    # for (i in ...) defines i, and assign(\"k\", ...) defines k.\n    for (row in which(token == \"forcond\")) {\n      found <- kids(row)\n      at <- found[token[found] == \"SYMBOL\"]\n      if (length(at) && !in_function[row]) {\n        defs <- c(defs, text[at[1]])\n        plain_targets <- c(plain_targets, at[1])\n      }\n    }\n    for (row in which(token == \"SYMBOL_FUNCTION_CALL\" & text == \"assign\")) {\n      call_row <- row_of(parent[row_of(parent[row])])\n      if (is.na(call_row) || in_function[call_row]) {\n        next\n      }\n      found <- kids(call_row)\n      first <- found[match(\"'('\", token[found]) + 1]\n      one <- if (!is.na(first) && token[first] == \"expr\") only(first) else NA_integer_\n      if (!is.na(one) && token[one] == \"STR_CONST\") {\n        defs <- c(defs, str2lang(text[one]))\n      }\n    }\n\n    after_dollar <- function(row) {\n      siblings <- kids(row_of(parent[row]))\n      at <- match(row, siblings)\n      !is.na(at) && at > 1 && token[siblings[at - 1]] %in% c(\"'$'\", \"'@'\")\n    }\n    symbols <- which(token == \"SYMBOL\")\n    uses <- character(0)\n    candidates <- character(0)\n    for (row in symbols) {\n      name <- text[row]\n      if (after_dollar(row)) {\n        candidates <- c(candidates, name)\n        next\n      }\n      candidates <- c(candidates, name)\n      if (!(row %in% plain_targets) && is_global(name)) {\n        uses <- c(uses, name)\n      }\n    }\n    for (row in which(token == \"SYMBOL_FUNCTION_CALL\")) {\n      if (is_global(text[row]) && is.function(get0(text[row], envir = global, inherits = FALSE))) {\n        uses <- c(uses, text[row])\n      }\n    }\n\n    # Strings of assignments that make a frame without reading one: the\n    # values of data.frame(arm = c(\"A\", \"B\")) build the frame and name no\n    # column the cell uses.\n    made <- integer(0)\n    for (assignment in assignments) {\n      if (is.null(frames[[assignment$name]])) {\n        next\n      }\n      inside <- below(assignment$value)\n      if (!any(token[inside] == \"SYMBOL\" & text[inside] %in% names(frames))) {\n        made <- c(made, inside[token[inside] == \"STR_CONST\"])\n      }\n    }\n    for (row in which(token == \"STR_CONST\")) {\n      if (!(row %in% made)) {\n        candidates <- c(candidates, tryCatch(str2lang(text[row]), error = function(e) \"\"))\n      }\n    }\n    used_frames <- intersect(unique(c(uses, defs)), names(frames))\n    touched <- stats::setNames(list(), character(0))\n    for (frame in used_frames) {\n      columns <- sort(intersect(unique(candidates), frames[[frame]]), method = \"radix\")\n      if (length(columns)) {\n        touched[[frame]] <- as.list(columns)\n      }\n    }\n\n    # Formulas, as written: y ~ x + (1 | g).\n    formulas <- character(0)\n    formula_rows <- integer(0)\n    for (row in which(token == \"'~'\")) {\n      at <- row_of(parent[row])\n      up <- at\n      nested <- FALSE\n      while (!is.na(up) && parent[up] != 0) {\n        up <- row_of(parent[up])\n        if (!is.na(up) && up %in% formula_rows) {\n          nested <- TRUE\n          break\n        }\n      }\n      formula_rows <- c(formula_rows, at)\n      written <- node_text(at)\n      if (!nested && nchar(written) < 300) {\n        formulas <- c(formulas, written)\n      }\n    }\n    is_formula <- function(row) {\n      !is.na(row) && any(token[kids(row)] == \"'~'\")\n    }\n\n    # A value written in the cell, as R code, or NA: a number, a string, a\n    # flag, a negative number, or c() of at most 8 numbers.\n    literal_of <- function(row) {\n      if (is.na(row) || token[row] != \"expr\") {\n        return(NA_character_)\n      }\n      found <- kids(row)\n      if (length(found) == 1) {\n        one <- found[1]\n        if (token[one] == \"STR_CONST\") {\n          return(text[one])\n        }\n        if (token[one] == \"NUM_CONST\" && !(text[one] %in% c(\"NA\", \"NA_integer_\", \"NA_real_\", \"NA_character_\", \"NULL\", \"NaN\"))) {\n          return(text[one])\n        }\n        return(NA_character_)\n      }\n      if (length(found) == 2 && token[found[1]] == \"'-'\") {\n        number <- only(found[2])\n        if (!is.na(number) && token[number] == \"NUM_CONST\" && !(text[number] %in% c(\"TRUE\", \"FALSE\", \"NA\", \"NULL\"))) {\n          return(node_text(row))\n        }\n        return(NA_character_)\n      }\n      head <- found[1]\n      if (length(found) >= 4 && token[head] == \"expr\" && token[found[2]] == \"'('\") {\n        name <- kids(head)\n        if (length(name) == 1 && token[name] == \"SYMBOL_FUNCTION_CALL\" && text[name] == \"c\") {\n          values <- found[token[found] == \"expr\"][-1]\n          if (length(values) >= 1 && length(values) <= 8 && !any(token[found] %in% c(\"SYMBOL_SUB\", \"EQ_SUB\")) &&\n            all(vapply(values, function(value) {\n              written <- literal_of(value)\n              !is.na(written) && !grepl(\"^[\\\"']\", written) && !(written %in% c(\"TRUE\", \"FALSE\"))\n            }, logical(1)))) {\n            return(node_text(row))\n          }\n        }\n      }\n      NA_character_\n    }\n\n    decisions <- list()\n    attachments <- list()\n    seen <- character(0)\n    short <- function(fn) {\n      if (is.na(fn)) \"\" else sub(\"^.*::\", \"\", fn)\n    }\n    same <- function(a, b) identical(if (is.null(a)) NA else a, if (is.null(b)) NA else b)\n    # Add a decision of a call, keyed by the call, or of an assignment, keyed by its name.\n    add <- function(entry, call = NULL, at = 0) {\n      key <- paste(entry$name, if (is.null(call)) \"\" else paste(call$line, call$col))\n      if (key %in% seen || looks_secret(entry$name, entry$value)) {\n        return(invisible())\n      }\n      seen <<- c(seen, key)\n      if (!is.null(call)) {\n        for (index in seq_along(decisions)) {\n          other <- decisions[[index]]\n          if (!is.null(other$calls) && identical(other$name, entry$name) && identical(other$value, entry$value) &&\n            identical(other$provenance, entry$provenance) && same(other$param, entry$param) &&\n            short(other$`function`) == short(entry$`function`)) {\n            decisions[[index]]$calls[[length(other$calls) + 1]] <<- call\n            return(invisible())\n          }\n        }\n        entry$calls <- list(call)\n      }\n      entry$.at <- at\n      decisions[[length(decisions) + 1]] <<- entry\n    }\n\n    # The arguments of a call: each with its name, or NA, and the row of its value.\n    arguments_of <- function(call_row) {\n      found <- kids(call_row)\n      opened <- match(\"'('\", token[found])\n      found <- if (length(found) - 1 >= opened + 1) found[(opened + 1):(length(found) - 1)] else integer(0)\n      groups <- list()\n      current <- integer(0)\n      for (row in found) {\n        if (token[row] == \"','\") {\n          groups[[length(groups) + 1]] <- current\n          current <- integer(0)\n        } else {\n          current <- c(current, row)\n        }\n      }\n      groups[[length(groups) + 1]] <- current\n      result <- list()\n      for (group in groups) {\n        if (!length(group)) {\n          next\n        }\n        if (length(group) >= 2 && token[group[2]] == \"EQ_SUB\") {\n          name <- text[group[1]]\n          if (token[group[1]] == \"STR_CONST\") name <- str2lang(name)\n          result[[length(result) + 1]] <- list(name = name, value = if (length(group) >= 3) group[3] else NA_integer_)\n        } else {\n          result[[length(result) + 1]] <- list(name = NA_character_, value = group[1])\n        }\n      }\n      result\n    }\n\n    # The formals that each argument binds to, as R matches them: by exact\n    # name, by a unique start of a name before `...`, then by position. An\n    # argument that binds to none keeps its own name, or NA.\n    bind <- function(arguments, params, extra) {\n      named <- vapply(arguments, function(arg) arg$name, character(1))\n      out <- rep(NA_character_, length(arguments))\n      open <- before_dots(params)\n      exact <- setdiff(c(params, extra), \"...\")\n      used <- character(0)\n      for (index in seq_along(arguments)) {\n        if (!is.na(named[index]) && named[index] %in% exact && !(named[index] %in% used)) {\n          out[index] <- named[index]\n          used <- c(used, named[index])\n        }\n      }\n      for (index in seq_along(arguments)) {\n        if (!is.na(named[index]) && is.na(out[index])) {\n          left <- setdiff(c(open, extra), used)\n          hit <- left[startsWith(left, named[index])]\n          out[index] <- if (length(hit) == 1) hit else named[index]\n          used <- c(used, out[index])\n        }\n      }\n      free <- setdiff(open, used)\n      for (index in seq_along(arguments)) {\n        if (is.na(named[index]) && length(free)) {\n          out[index] <- free[1]\n          free <- free[-1]\n        }\n      }\n      out\n    }\n\n    # The class of the object that an argument names in the global environment, or NULL.\n    object_of <- function(row) {\n      name <- if (is.na(row)) NA_character_ else symbol_of(row)\n      if (is.na(name) || !is_global(name)) NULL else get0(name, envir = global, inherits = FALSE)\n    }\n\n    signatures <- list()\n    for (row in which(token == \"SYMBOL_FUNCTION_CALL\")) {\n      name <- text[row]\n      head <- row_of(parent[row])\n      call_row <- row_of(parent[head])\n      if (is.na(call_row) || name %in% skipped_functions) {\n        next\n      }\n      parts <- kids(call_row)\n      if (length(parts) < 3 || parts[1] != head || token[parts[2]] != \"'('\") {\n        next\n      }\n      head_parts <- kids(head)\n      if (any(token[head_parts] %in% c(\"'$'\", \"'@'\"))) {\n        # A method of an object, obj$fit(): the kernel cannot tell the function.\n        next\n      }\n      package <- if (any(token[head_parts] == \"SYMBOL_PACKAGE\")) text[head_parts[token[head_parts] == \"SYMBOL_PACKAGE\"][1]] else NA_character_\n      arguments <- arguments_of(call_row)\n      # A pipe gives the call its first argument, or the argument that holds its placeholder.\n      outer <- row_of(parent[call_row])\n      if (!is.na(outer)) {\n        around <- kids(outer)\n        if (length(around) == 3 && around[3] == call_row && (token[around[2]] == \"PIPE\" || (token[around[2]] == \"SPECIAL\" && text[around[2]] == \"%>%\"))) {\n          holder <- vapply(arguments, function(arg) {\n            one <- only(arg$value)\n            !is.na(one) && (token[one] == \"PLACEHOLDER\" || (token[one] == \"SYMBOL\" && text[one] == \".\"))\n          }, logical(1))\n          if (any(holder)) {\n            arguments[[which(holder)[1]]]$value <- around[1]\n          } else {\n            arguments <- c(list(list(name = NA_character_, value = around[1])), arguments)\n          }\n        }\n      }\n      unpacks <- any(vapply(arguments, function(arg) {\n        one <- only(arg$value)\n        !is.na(one) && token[one] == \"SYMBOL\" && text[one] == \"...\"\n      }, logical(1)))\n\n      fn <- resolve(name, package)\n      own <- !is.null(fn) && identical(environment(fn), global)\n      from <- if (is.null(fn) || own) NA_character_ else package_of(fn)\n      entry <- known[[name]]\n      if (!is.null(entry) && ((!is.na(package) && !(package %in% c(entry$package, entry$also))) ||\n        (!is.null(fn) && !(from %in% c(entry$package, entry$also))))) {\n        entry <- NULL\n      }\n      positional <- sum(vapply(arguments, function(arg) is.na(arg$name), logical(1)))\n      first <- if (length(arguments)) arguments[[1]]$value else NA_integer_\n      # The formals, of the S3 method that the first argument picks for a generic.\n      params <- NULL\n      extra <- character(0)\n      method <- fn\n      method_name <- name\n      forwarded <- list()\n      if (!is.null(fn)) {\n        if (!is.primitive(fn) && \"UseMethod\" %in% all.names(body(fn))) {\n          object <- object_of(first)\n          # .class2 gives the classes that S3 dispatch reads, since R 4.0.0.\n          dispatch <- get0(\".class2\", envir = baseenv(), mode = \"function\", ifnotfound = class)\n          classes <- if (is_formula(first)) \"formula\" else if (!is.null(object)) dispatch(object) else character(0)\n          for (class in c(classes, \"default\")) {\n            found <- utils::getS3method(name, class, optional = TRUE, envir = global)\n            if (!is.null(found)) {\n              method <- found\n              method_name <- paste(name, class, sep = \".\")\n              if (class == \"formula\") {\n                fallback <- utils::getS3method(name, \"default\", optional = TRUE, envir = global)\n                if (!is.null(fallback)) forwarded <- list(fallback)\n              }\n              break\n            }\n          }\n        }\n        params <- names(formals_of(method))\n        if (!is.na(forwards[name]) && !is.na(from) && from == \"utils\") {\n          passed_to <- get0(forwards[[name]], envir = asNamespace(\"utils\"), inherits = FALSE)\n          if (is.function(passed_to)) forwarded <- list(passed_to)\n        }\n        for (other in forwarded) extra <- c(extra, before_dots(names(formals_of(other))))\n      } else if (!is.null(entry)) {\n        params <- entry$params\n      }\n      bound <- bind(arguments, params, extra)\n      passed <- bound[!is.na(bound)]\n      value_of <- function(param) {\n        at <- match(param, bound)\n        if (is.na(at)) NA_integer_ else arguments[[at]]$value\n      }\n\n      line <- pd$line1[row]\n      col <- byte_col(line, pd$col1[row])\n      file_param <- if (reader(name) && length(params) && !is.na(params[1])) params[1] else NA_character_\n      # The frame the call joins, the file it reads without its extension, or the first frame it works on.\n      target <- NA_character_\n      if (name == \"merge\") {\n        joined <- root_of(value_of(\"y\"))\n        if (!is.na(joined) && (!is.null(frames[[joined]]) || !is_global(joined))) target <- joined\n      }\n      if (is.na(target) && !is.na(file_param)) {\n        written <- literal_of(value_of(file_param))\n        if (!is.na(written) && grepl(\"^[\\\"']\", written)) {\n          target <- sub(\"\\\\.[^.]*$\", \"\", basename(str2lang(written)))\n          if (!nzchar(target)) target <- NA_character_\n        }\n      }\n      if (is.na(target)) {\n        for (arg in arguments) {\n          inside <- if (is.na(arg$value)) integer(0) else c(arg$value, below(arg$value))\n          hits <- inside[token[inside] == \"SYMBOL\" & text[inside] %in% names(frames)]\n          if (length(hits)) {\n            target <- text[hits[1]]\n            break\n          }\n        }\n      }\n      call <- list(line = line, col = col, target = target)\n      at <- line * 1e6 + col\n      shown_name <- if (!is.na(from)) paste0(from, \"::\", name) else if (!is.na(package)) paste0(package, \"::\", name) else if (!is.null(entry)) paste0(entry$package, \"::\", name) else name\n\n      if (!is.null(entry) && !unpacks) {\n        # Whether a factor, a text or a flag is among the variables of the\n        # model, in its data or else in the frame of the kernel that holds\n        # them all, as a frame that a function passes on: the coding of\n        # factors changes nothing in a model of numbers alone, and nothing\n        # is known before the frame exists.\n        model_formula <- value_of(if (\"formula\" %in% bound) \"formula\" else bound[1])\n        data_name <- if (is.na(value_of(\"data\"))) NA_character_ else root_of(value_of(\"data\"))\n        factors <- FALSE\n        if (is_formula(model_formula)) {\n          variables <- all.vars(str2lang(node_text(model_formula)))\n          holder <- if (!is.na(data_name) && !is.null(frames[[data_name]])) {\n            data_name\n          } else {\n            holding <- names(frames)[vapply(frames, function(columns) all(variables %in% columns), logical(1))]\n            if (length(holding)) holding[1] else NA_character_\n          }\n          if (!is.na(holder)) {\n            frame <- get0(holder, envir = global, inherits = FALSE)\n            factors <- any(vapply(intersect(variables, names(frame)), function(column) {\n              values <- frame[[column]]\n              is.factor(values) || is.character(values) || is.logical(values)\n            }, logical(1)))\n          }\n        }\n        paired <- value_of(\"paired\")\n        call_facts <- list(\n          passed = passed,\n          positional = positional,\n          factors = factors,\n          object = object_of(first),\n          two_samples = (is_formula(first) || positional >= 2 || \"y\" %in% passed) &&\n            !identical(literal_of(paired), \"TRUE\")\n        )\n        for (param in names(entry$defaults)) {\n          default <- entry$defaults[[param]]\n          own_param <- if (is.null(default$param)) param else default$param\n          if ((!is.na(own_param) && own_param %in% passed) || !isTRUE(default$when(call_facts))) {\n            next\n          }\n          version <- version_of(entry$package)\n          add(c(list(\n            name = param, value = default$value, provenance = \"library_default\",\n            param = own_param, `function` = paste0(entry$package, \"::\", name), note = default$note,\n            library = entry$package\n          ), if (!is.na(version)) list(version = version)), call, at)\n        }\n      }\n\n      # A function of the analyst's own file: each formal that the call\n      # leaves at its default, and the constant of the file that the default\n      # names, as the Python version shows the defaults of the analyst's\n      # modules.\n      path <- if (own && !unpacks) file_of(fn) else NA_character_\n      if (!is.na(path)) {\n        relative <- substring(path, nchar(folder) + 2)\n        defaults <- formals(fn)\n        highlight <- NULL\n        left <- FALSE\n        for (param in names(defaults)) {\n          if (param == \"...\" || param %in% passed || identical(defaults[[param]], quote(expr = ))) {\n            next\n          }\n          left <- TRUE\n          value <- defaults[[param]]\n          constant <- if (is.symbol(value)) as.character(value) else NA_character_\n          held <- if (is.na(constant)) NULL else get0(constant, envir = environment(fn))\n          if (is.atomic(held) && length(held) == 1) {\n            found <- line_of(path, constant)\n            if (is.null(highlight) && !is.na(found$line)) {\n              highlight <- found\n            }\n            add(list(\n              name = constant, value = paste(deparse(held), collapse = \" \"), provenance = \"defaulted\",\n              param = param, `function` = name, source = list(file = relative, line = found$line)\n            ), call, at)\n          } else {\n            add(list(\n              name = param, value = paste(deparse(value, width.cutoff = 500L), collapse = \" \"), provenance = \"defaulted\",\n              param = param, `function` = name, source = list(file = relative, line = NA)\n            ), call, at)\n          }\n        }\n        symbols_attached <- vapply(attachments, function(attachment) attachment$symbol, character(1))\n        if (left && !(name %in% symbols_attached)) {\n          attachment <- attachment_for(fn, path, relative, name, highlight)\n          if (!is.null(attachment)) {\n            attachments[[length(attachments) + 1]] <- attachment\n          }\n        }\n      }\n\n      if (read_signatures && !is.null(fn) && !own && !unpacks && !is.primitive(method) &&\n        isNamespace(environment(method))) {\n        method_package <- package_of(method)\n        key <- paste0(method_package, \"::\", method_name)\n        read <- signature_of(key, shown_name, method_package, method, forwarded)\n        defaulted <- vapply(read$params, function(item) item$name, character(1))\n        defaulted <- defaulted[!(defaulted %in% passed)]\n        if (length(defaulted)) {\n          if (is.null(signatures[[key]])) signatures[[key]] <- read\n          signatures[[key]]$calls[[length(signatures[[key]]$calls) + 1]] <- c(call, list(defaulted = as.list(defaulted)))\n        }\n      }\n\n      for (index in seq_along(arguments)) {\n        param <- bound[index]\n        if (is.na(param) || (param %in% skipped_params && !identical(param, file_param))) {\n          next\n        }\n        value_row <- arguments[[index]]$value\n        written <- literal_of(value_row)\n        if (is.na(written) && param == \"family\") {\n          # glm(family = binomial) chooses the model as much as a literal does.\n          one <- only(value_row)\n          head_name <- if (!is.na(one) && token[one] == \"SYMBOL\") text[one] else {\n            parts_of <- kids(value_row)\n            call_head <- if (length(parts_of)) kids(parts_of[1]) else integer(0)\n            if (length(call_head) == 1 && token[call_head] == \"SYMBOL_FUNCTION_CALL\") text[call_head] else NA_character_\n          }\n          if (!is.na(head_name) && head_name %in% family_functions) {\n            written <- node_text(value_row)\n          }\n        }\n        if (is.na(written)) {\n          next\n        }\n        if (grepl(\"^[\\\"']\", written)) {\n          value <- tryCatch(str2lang(written), error = function(e) \"\")\n          if (is_global(value) || any(vapply(frames, function(columns) value %in% columns, logical(1)))) {\n            next\n          }\n        }\n        add(list(name = param, value = written, provenance = \"literal\", param = param, `function` = shown_name), call, at)\n      }\n    }\n\n    # Constants assigned at the top level: MIN_DAYS <- 14.\n    for (assignment in assignments) {\n      if (!assignment$top || !assignment$plain) {\n        next\n      }\n      written <- literal_of(assignment$value)\n      if (!is.na(written)) {\n        add(list(name = assignment$name, value = written, provenance = \"literal\", param = NA_character_, `function` = NA_character_),\n          at = pd$line1[assignment$row] * 1e6 + byte_col(pd$line1[assignment$row], pd$col1[assignment$row])\n        )\n      }\n    }\n\n    ranks <- c(defaulted = 0, library_default = 1, literal = 2)\n    if (length(decisions)) {\n      rank <- vapply(decisions, function(decision) ranks[[decision$provenance]] * 1e12 + decision$.at, numeric(1))\n      decisions <- decisions[order(rank)]\n    }\n    decisions <- lapply(decisions, function(decision) {\n      decision$.at <- NULL\n      if (!is.null(decision$calls)) {\n        places <- vapply(decision$calls, function(call) call$line * 1e6 + call$col, numeric(1))\n        decision$calls <- decision$calls[order(places)]\n      }\n      decision\n    })\n    result <- list(\n      defs = as.list(sort(unique(defs), method = \"radix\")),\n      uses = as.list(sort(unique(uses), method = \"radix\")),\n      formulas = as.list(unique(formulas)),\n      columns = touched,\n      decisions = utils::head(decisions, max_decisions),\n      attachments = attachments\n    )\n    if (read_signatures) {\n      listed <- unname(signatures)\n      if (length(listed)) {\n        firsts <- vapply(listed, function(entry) entry$calls[[1]]$line * 1e6 + entry$calls[[1]]$col, numeric(1))\n        listed <- listed[order(firsts)]\n      }\n      result$signatures <- utils::head(listed, max_signatures)\n    }\n    result\n  }\n\n  results <- list()\n  for (cell in args$cells) {\n    results[[cell$id]] <- tryCatch(analyze(cell$source), error = function(e) {\n      list(\n        defs = list(), uses = list(), formulas = list(),\n        columns = stats::setNames(list(), character(0)), decisions = list(), attachments = list(),\n        error = conditionMessage(e)\n      )\n    })\n  }\n  if (!length(results)) {\n    results <- stats::setNames(list(), character(0))\n  }\n  IRdisplay::publish_mimebundle(list(\n    \"application/vnd.whybook.result+json\" = list(cells = results)\n  ))\n}\n";

export const rInspectVariables = "# List the user's variables with what the Variables and Contents sections show.\n#\n# The R version of inspect_variables.py, for R kernels such as xeus-r and\n# IRkernel. The frontend bundle holds the text of this file\n# (scripts/embed-kernel-code.mjs), runs it in the global environment, calls\n# the function with the JSON arguments and removes it again (the R adapter in\n# src/model/languages.ts). It needs jsonlite and IRdisplay, which both kernels\n# depend on. The result goes out as display data with a MIME type that output\n# areas do not render.\n#\n# It lists data frames with their columns, vectors as series, scalars as\n# constants, and matrices with their shape. It does not fingerprint frames,\n# so `args$known` is not read and every listing describes every frame again,\n# and it does not read fitted models.\n.whybook_inspect_variables <- function(args) {\n  max_columns <- if (is.null(args$max_columns)) 20000L else as.integer(args$max_columns)\n  # Above this many values, distinct counts and ranges are skipped.\n  detail_limit <- if (is.null(args$detail_limit)) 2e7 else as.numeric(args$detail_limit)\n\n  # A key, a token or a password in a variable is listed with its length and\n  # \"secret\": true, never its text: the view keeps the listing in the\n  # notebook and sends it with every request to a model. The server, the\n  # Python listing (inspect_variables.py), the analyses of cells and the view\n  # hold the same rule (privacy.py says it in full,\n  # tests/data/secret_names.json holds its cases): only a string is a secret,\n  # when a part of its name says so, as the \"token\" of HF_TOKEN, or its text\n  # holds a known prefix of a key or a long run of letters and digits.\n  secret_words <- c(\n    \"token\", \"secret\", \"secrets\", \"password\", \"passwords\", \"passwd\", \"pwd\",\n    \"credential\", \"credentials\", \"bearer\", \"apikey\", \"auth\"\n  )\n  secret_endings <- c(\"token\", \"secret\", \"password\", \"passwd\", \"apikey\")\n  secret_pairs <- c(\"api key\", \"access key\", \"private key\", \"secret key\")\n  secret_prefix <- paste0(\n    \"(?<![A-Za-z0-9])(?:sk-|sk_live_|sk_test_|hf_|ghp_|gho_|ghu_|ghs_|ghr_|github_pat_|glpat-|xox[abpr]-|xapp-\",\n    \"|AKIA|ASIA|AIza|ya29\\\\.|eyJ|npm_|pypi-)[A-Za-z0-9_.=-]{16,}\"\n  )\n  # A password in a URL, as a connection string holds it, and a query parameter named as a secret.\n  url_password <- \"[A-Za-z][A-Za-z0-9+.-]*://[^\\\\s/?#@:]*:[^\\\\s/?#@]+@\"\n  query_name <- \"[?&][A-Za-z0-9_.-]+=[^&#\\\\s]\"\n  all_of <- function(pattern, text) regmatches(text, gregexpr(pattern, text, perl = TRUE))[[1]]\n\n  secret_name <- function(name) {\n    parts <- tolower(all_of(\"[A-Z]+(?![a-z])|[A-Z]?[a-z]+\", name))\n    if (any(parts %in% secret_words)) {\n      return(TRUE)\n    }\n    for (ending in secret_endings) {\n      if (any(endsWith(parts, ending))) {\n        return(TRUE)\n      }\n    }\n    length(parts) > 1 && any(paste(parts[-length(parts)], parts[-1]) %in% secret_pairs)\n  }\n\n  secret_string <- function(name, text) {\n    if (secret_name(name)) {\n      return(TRUE)\n    }\n    # The text of a string of up to 10,000 characters: a longer one is listed by its length alone.\n    if (is.na(text) || nchar(text) > 10000) {\n      return(FALSE)\n    }\n    if (grepl(secret_prefix, text, perl = TRUE) || grepl(url_password, text, perl = TRUE)) {\n      return(TRUE)\n    }\n    keys <- sub(\"^[?&]([A-Za-z0-9_.-]+)=.*$\", \"\\\\1\", all_of(query_name, text), perl = TRUE)\n    if (any(vapply(keys, secret_name, logical(1)))) {\n      return(TRUE)\n    }\n    runs <- all_of(\"[A-Za-z0-9]{20,}\", text)\n    any(nchar(runs) >= 32 | (grepl(\"[A-Z]\", runs) & grepl(\"[a-z]\", runs) & grepl(\"[0-9]\", runs)))\n  }\n\n  clean <- function(value) {\n    if (inherits(value, c(\"Date\", \"POSIXt\"))) {\n      return(format(value))\n    }\n    if (is.numeric(value)) {\n      if (is.na(value) || !is.finite(value)) {\n        return(NULL)\n      }\n      if (value == round(value) && abs(value) < 2^31) {\n        return(as.integer(value))\n      }\n      return(round(value, 4))\n    }\n    as.character(value)\n  }\n\n  column_tag <- function(label, x, n_unique, rows) {\n    lowered <- tolower(label)\n    if (is.logical(x)) {\n      return(\"bool\")\n    }\n    if (lowered == \"id\" || endsWith(lowered, \"_id\")) {\n      return(\"id\")\n    }\n    if (is.factor(x)) {\n      return(if (is.ordered(x)) \"ord\" else \"cat\")\n    }\n    if (inherits(x, c(\"Date\", \"POSIXt\"))) {\n      return(\"date\")\n    }\n    if (is.integer(x)) {\n      return(\"int\")\n    }\n    if (is.numeric(x)) {\n      return(\"num\")\n    }\n    if (is.character(x)) {\n      if (!is.null(n_unique) && rows > 0 && n_unique > 50 && n_unique > 0.5 * rows) {\n        return(\"text\")\n      }\n      return(\"cat\")\n    }\n    \"other\"\n  }\n\n  column_kind <- function(tag, n_unique) {\n    if (tag == \"bool\" || (identical(n_unique, 2L) && tag %in% c(\"int\", \"num\", \"cat\", \"ord\"))) {\n      return(\"binary\")\n    }\n    switch(tag,\n      int = \"numeric\", num = \"numeric\", date = \"datetime\", cat = \"categorical\",\n      ord = \"categorical\", id = \"id\", text = \"text\", \"other\"\n    )\n  }\n\n  describe_column <- function(label, x, detailed) {\n    rows <- length(x)\n    missing <- sum(is.na(x))\n    entry <- list(label = label, dtype = class(x)[1], missing = missing)\n    n_unique <- NULL\n    if (detailed && is.atomic(x)) {\n      n_unique <- length(unique(x[!is.na(x)]))\n    }\n    tag <- column_tag(label, x, n_unique, rows)\n    entry$tag <- tag\n    entry$kind <- column_kind(tag, n_unique)\n    if (!is.null(n_unique)) {\n      entry$unique <- n_unique\n    }\n    if (detailed && tag %in% c(\"int\", \"num\", \"date\") && missing < rows) {\n      entry$min <- clean(min(x, na.rm = TRUE))\n      entry$max <- clean(max(x, na.rm = TRUE))\n    }\n    # Levels of a factor, a text or a flag; numbers show their range instead.\n    if (!is.null(n_unique) && n_unique <= 6 && (is.factor(x) || is.character(x) || is.logical(x))) {\n      values <- if (is.factor(x)) levels(x) else sort(unique(as.character(x[!is.na(x)])))\n      # A list stays a JSON array when it holds one level.\n      entry$levels <- as.list(utils::head(as.character(values), 6))\n    }\n    entry\n  }\n\n  describe_frame <- function(name, value) {\n    rows <- nrow(value)\n    labels <- utils::head(names(value), max_columns)\n    detailed <- as.numeric(rows) * length(labels) <= detail_limit\n    columns <- lapply(labels, function(label) {\n      tryCatch(\n        describe_column(label, value[[label]], detailed),\n        error = function(e) {\n          list(label = label, tag = \"other\", kind = \"other\", error = conditionMessage(e))\n        }\n      )\n    })\n    list(\n      name = name, label = name, kind = \"dataframe\", type = class(value)[1],\n      rows = rows, n_columns = ncol(value), columns = columns\n    )\n  }\n\n  describe <- function(name, value) {\n    type <- class(value)[1]\n    if (is.data.frame(value)) {\n      return(describe_frame(name, value))\n    }\n    if (is.atomic(value) && is.null(dim(value)) && length(value) == 1 && !is.factor(value)) {\n      if (is.character(value) && secret_string(name, value)) {\n        return(list(name = name, label = name, kind = \"constant\", type = type, secret = TRUE, length = nchar(value)))\n      }\n      text <- paste(deparse(value), collapse = \"\")\n      if ((!is.character(value) || nchar(value) <= 58) && nchar(text) <= 60) {\n        return(list(name = name, label = name, kind = \"constant\", type = type, value = text))\n      }\n      if (is.character(value)) {\n        # A long text is listed by its length, as the Python listing lists it.\n        return(list(name = name, label = name, kind = \"other\", type = type, length = nchar(value)))\n      }\n    }\n    if (!is.null(dim(value))) {\n      return(list(\n        name = name, label = name, kind = \"array\", type = type,\n        shape = as.list(dim(value)), dtype = typeof(value)\n      ))\n    }\n    if (is.atomic(value)) {\n      # A vector is described as a column of its own, as a pandas Series is.\n      entry <- describe_column(name, value, length(value) <= detail_limit)\n      entry$name <- name\n      entry$type <- type\n      entry$rows <- length(value)\n      return(entry)\n    }\n    list(name = name, label = name, kind = \"other\", type = type, length = length(value))\n  }\n\n  variables <- list()\n  # ls() leaves out names that start with a dot, as this function's own name does.\n  for (name in ls(envir = globalenv())) {\n    value <- get(name, envir = globalenv())\n    if (is.function(value) || is.environment(value)) {\n      next\n    }\n    variables[[length(variables) + 1]] <- tryCatch(\n      describe(name, value),\n      error = function(e) {\n        list(name = name, label = name, kind = \"other\", type = class(value)[1], error = conditionMessage(e))\n      }\n    )\n  }\n\n  base <- c(\"stats\", \"graphics\", \"grDevices\", \"utils\", \"datasets\", \"methods\", \"base\")\n  attached <- setdiff(.packages(), base)\n  packages <- stats::setNames(\n    lapply(attached, function(package) as.character(utils::packageVersion(package))),\n    attached\n  )\n\n  IRdisplay::publish_mimebundle(list(\n    \"application/vnd.whybook.result+json\" = list(\n      variables = variables,\n      packages = packages,\n      language = paste(\"R\", getRversion()),\n      cwd = normalizePath(getwd())\n    )\n  ))\n}\n";

export const rKernelFacts = "# What an R kernel has, for an agent that writes cells in it: R's version,\n# whether it reads parquet, and the packages installed.\n#\n# The R version of kernel_facts.py (design iteration 1.69). An agent that\n# answers in a second notebook reads this when the notebook opens, so that it\n# writes code with the packages there are and says which are missing. It\n# installs nothing. It needs jsonlite and IRdisplay, which R kernels depend on.\n.whybook_kernel_facts <- function(args) {\n  installed <- sort(unique(rownames(utils::installed.packages())))\n  IRdisplay::publish_mimebundle(list(\n    \"application/vnd.whybook.result+json\" = list(\n      language = paste(\"R\", getRversion()),\n      parquet = requireNamespace(\"arrow\", quietly = TRUE),\n      packages = as.list(utils::head(installed, 500))\n    )\n  ))\n}\n";

export const rWriteFrames = "# Write data frames of the kernel to files that a notebook of another kernel reads.\n#\n# The R version of write_frames.py (design iteration 1.69): an agent that\n# answers in a second notebook has the analyst's kernel write the frames that\n# the cells to port read, into a folder beside the notebooks. Parquet needs\n# the arrow package here, and a reader there; CSV needs neither.\n# `args$format` is \"parquet\" when the other kernel reads parquet; without\n# arrow here, a frame goes as CSV. It needs jsonlite and IRdisplay, which R\n# kernels depend on.\n.whybook_write_frames <- function(args) {\n  folder <- if (is.null(args$folder)) \"from_r\" else as.character(args$folder)\n  wanted <- if (identical(args$format, \"parquet\")) \"parquet\" else \"csv\"\n  files <- list()\n  errors <- list()\n  for (name in as.character(unlist(args$frames))) {\n    if (!exists(name, envir = globalenv(), inherits = FALSE)) {\n      errors[[length(errors) + 1]] <- list(frame = name, error = paste(\"no variable named\", name))\n      next\n    }\n    value <- get(name, envir = globalenv())\n    if (!is.data.frame(value)) {\n      errors[[length(errors) + 1]] <- list(frame = name, error = paste(name, \"is not a data frame\"))\n      next\n    }\n    format <- if (wanted == \"parquet\" && requireNamespace(\"arrow\", quietly = TRUE)) \"parquet\" else \"csv\"\n    path <- file.path(folder, paste0(name, \".\", format))\n    existed <- file.exists(path)\n    written <- tryCatch(\n      {\n        dir.create(folder, showWarnings = FALSE, recursive = TRUE)\n        if (format == \"parquet\") {\n          arrow::write_parquet(value, path)\n        } else {\n          utils::write.csv(value, path, row.names = FALSE)\n        }\n        TRUE\n      },\n      error = function(e) {\n        errors[[length(errors) + 1]] <<- list(frame = name, error = conditionMessage(e))\n        FALSE\n      }\n    )\n    if (!written) {\n      next\n    }\n    columns <- lapply(utils::head(names(value), 200), function(column) {\n      list(name = column, type = class(value[[column]])[1])\n    })\n    files[[length(files) + 1]] <- list(\n      frame = name,\n      path = path,\n      format = format,\n      rows = nrow(value),\n      columns = columns,\n      existed = existed\n    )\n  }\n  IRdisplay::publish_mimebundle(list(\n    \"application/vnd.whybook.result+json\" = list(folder = folder, files = files, errors = errors)\n  ))\n}\n";

export const r: Record<string, string> = {
  analyze_cells: rAnalyzeCells,
  inspect_variables: rInspectVariables,
  kernel_facts: rKernelFacts,
  write_frames: rWriteFrames
};
